;; --------------------------------------------------------------------
;; CALLMB -- &42BD to &42DB
;;
;; Takes:     BC, DE, HL
;; Leaves:    BC, DE, HL, IY
;;
;; Shown for this routine in disasm/:
;;
;;     Call a routine in the other page.
;;
;;         CALL CALLMB
;;         DEFW <address in the other page>
;;
;;     Reads the word after the call, switches LMPR so that the other page
;;     covers &4000-&7FFF, and jumps to it; the return goes through the stub
;;     below, which puts LMPR back.  The &00 in the `LD H,&00` two instructions
;;     down is a placeholder: the boot sector pokes the other page's number,
;;     less one, into it once it knows which page that is.  &7FFC holds the
;;     ROM's stack pointer as it stood when the DOS was entered.
;;
;;     The parameter is read after the paging has changed, so a value of
;;     &4000 or more is an address in the other page, and is written here as
;;     that page's own label less &4000 -- the mirror of the +&4000 used for
;;     the bit-15 pointers in the tables.  Everywhere else in this file an
;;     inline DEFW is a ROM address, and reading this one that way would name
;;     it for a page that is no longer mapped: DOS_POINT would come out as one
;;     of the ROM variables that share &4FAC.  Below &4000 there is nothing to
;;     correct -- the switch leaves ROM0 in place, so NRREAD really is the ROM
;;     routine at &0010.
;; --------------------------------------------------------------------

; ---- CALLMB ---- from &43B5, &4E53, &4FDA, &51A7, &54F9, &5506, &59C2, &5B9C ...
CALLMB:
               LD IY,(&7FFC)                   ; 42BD FD 2A FC 7F
                                               ; to the alternate register set and back again
               EXX                             ; 42C1 D9
               POP HL                          ; 42C2 E1
               LD E,(HL)                       ; 42C3 5E
               INC HL                          ; 42C4 23
               LD D,(HL)                       ; 42C5 56
               INC HL                          ; 42C6 23
               DEFB &E5                        ; 42C7 e
               LD C,LMPR                       ; 42C8 0E FA
               IN B,(C)                        ; 42CA ED 40

L42CC:
               LD H,&00                        ; 42CC 26 00  the operand is written here at run time, from &40F0
               OUT (C),H                       ; 42CE ED 61
               PUSH BC                         ; 42D0 C5
               LD HL,CALLMB_1                  ; 42D1 21 DC 42
               PUSH HL                         ; 42D4 E5
               PUSH DE                         ; 42D5 D5
                                               ; to the alternate register set and back again
               EXX                             ; 42D6 D9
               RET                             ; 42D7 C9
               DEFB &00,&00,&00                ; 42D8 ...  zero fill
               DEFB &00                        ; 42DB .  LAST ENTRY FOR NOT FOUND

;; --------------------------------------------------------------------
;; CALLMB_1 -- &42DC to &42E5
;;
;; Takes:     BC, DE, HL
;; Leaves:    BC, DE, HL
;; Ends:      RET
;;
;; ? drives OUT (C),B.
;; --------------------------------------------------------------------

; ---- CALLMB_1 ---- from &42D1
CALLMB_1:
                                               ; to the alternate register set and back again
               EXX                             ; 42DC D9
               POP BC                          ; 42DD C1
               OUT (C),B                       ; 42DE ED 41
                                               ; to the alternate register set and back again
               EXX                             ; 42E0 D9
               RET                             ; 42E1 C9

; ---- V42E2 ---- from &4E9E, &4EF2, &642B, MB &6035, MB &603D
V42E2:
               DEFB &00,&00                    ; 42E2 ..  zero fill

; ---- V42E4 ---- from &4381, &51D8, &7859, &785D
V42E4:
               DEFB &00                        ; 42E4 .
               NOP                             ; 42E5 00

;; --------------------------------------------------------------------
;; CALLMB_2 -- &42E6 to &42E7
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; --------------------------------------------------------------------

; ---- CALLMB_2 ---- from &4A7E, &4AA5
CALLMB_2:
               NOP                             ; 42E6 00
               NOP                             ; 42E7 00

;; --------------------------------------------------------------------
;; CALLMB_3 -- &42E8 to &434D
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; --------------------------------------------------------------------

; ---- CALLMB_3 ---- from &4A78, &4AA1
CALLMB_3:
               NOP                             ; 42E8 00
               NOP                             ; 42E9 00

;; --------------------------------------------------------------------
;; CTAB -- the commands the DOS claims from the ROM.
;;
;; Three bytes per entry: the token, then the address of the routine.  The
;; byte before the table is the number of entries; the last entry's token
;; is zero, which nothing matches, so an unrecognised command always falls
;; through to CNF.  SYNTAX walks it with the token in A.
;;
;; What is in A is whatever GCHR returned at the start of the statement, so
;; an entry is a command token only because that is how a statement usually
;; begins.  The table is in ascending order, and the first entry is &2F --
;; not a token at all but the character "/", which is why it sorts below
;; everything else.  That is MasterBASIC's SPLIT: a slash as the first
;; non-space character after a colon cuts the line in two.
;;
;; As with SAMHK, an address with bit 15 set belongs to the MasterBASIC
;; page: the bit is cleared and the routine is called through CALLMB.  That
;; is how MasterBASIC takes over PRINT, LPRINT, SAVE, MERGE, DUMP, REF,
;; RECORD, BLITZ, CLS and LINE, and how its own commands at tokens &F7-&FC
;; are reached.
;; --------------------------------------------------------------------

CTABN:
               DEFB 33                         ; 42EA 33 entries
               DEFB &2F                        ; 42EB '/'
               DEFW MB_CMD_SPLIT_LINE+NOT_IN_THIS_PAGE
               DEFB &86                        ; 42EE WRITE
               DEFW WRITE
               DEFB &8C                        ; 42F1 LINE
               DEFW MB_CMD_LINE+NOT_IN_THIS_PAGE
               DEFB &90                        ; 42F4 DIR
               DEFW DIR
               DEFB &91                        ; 42F7 FORMAT
               DEFW WFOD
               DEFB &92                        ; 42FA ERASE
               DEFW ERAZ
               DEFB &93                        ; 42FD MOVE
               DEFW CMD_MOVE
               DEFB &94                        ; 4300 SAVE
               DEFW MB_CMD_SAVE+NOT_IN_THIS_PAGE
               DEFB &95                        ; 4303 LOAD
               DEFW CMD_LOAD
               DEFB &96                        ; 4306 MERGE
               DEFW MB_CMD_MERGE+NOT_IN_THIS_PAGE
               DEFB &98                        ; 4309 OPEN
               DEFW CMD_OPEN
               DEFB &99                        ; 430C CLOSE
               DEFW CLOSE
               DEFB &9D                        ; 430F BLITZ
               DEFW MB_CMD_BLITZ+NOT_IN_THIS_PAGE
               DEFB &9F                        ; 4312 CLS
               DEFW MB_CMD_CLS+NOT_IN_THIS_PAGE
               DEFB &B3                        ; 4315 CLEAR
               DEFW CLEAR
               DEFB &B8                        ; 4318 READ
               DEFW READ
               DEFB &BB                        ; 431B PRINT
               DEFW MB_CMD_PRINT+NOT_IN_THIS_PAGE
               DEFB &BC                        ; 431E LPRINT
               DEFW MB_CMD_LPRINT+NOT_IN_THIS_PAGE
               DEFB &BF                        ; 4321 DUMP
               DEFW MB_CMD_DUMP+NOT_IN_THIS_PAGE
               DEFB &CE                        ; 4324 REF
               DEFW MB_CMD_REF+NOT_IN_THIS_PAGE
               DEFB &CF                        ; 4327 COPY
               DEFW CMD_COPY
               DEFB &E3                        ; 432A RENAME
               DEFW RENAM
               DEFB &E4                        ; 432D CALL
               DEFW CALL_Label
               DEFB &EF                        ; 4330 RECORD
               DEFW MB_CMD_RECORD+NOT_IN_THIS_PAGE
               DEFB &F1                        ; 4333 PROTECT
               DEFW CMD_PROTECT
               DEFB &F2                        ; 4336 HIDE
               DEFW CMD_HIDE
               DEFB &F7                        ; 4339 BACKUP
               DEFW BACKUP
               DEFB &F8                        ; 433C TIME
               DEFW MB_CMD_TIME+NOT_IN_THIS_PAGE
               DEFB &F9                        ; 433F DATE
               DEFW MB_CMD_DATE+NOT_IN_THIS_PAGE
               DEFB &FA                        ; 4342 ALTER
               DEFW MB_CMD_ALTER+NOT_IN_THIS_PAGE
               DEFB &FB                        ; 4345 SORT
               DEFW MB_CMD_SORT+NOT_IN_THIS_PAGE
               DEFB &FC                        ; 4348 JOIN
               DEFW MB_CMD_JOIN+NOT_IN_THIS_PAGE
               DEFB &00                        ; 434B (end)
               DEFW CKESV

;; --------------------------------------------------------------------
;; SYNTAX -- &434E to &4355
;;
;; Takes:     A
;; Leaves:    F
;;
;; Shown for this routine in disasm/:
;;
;;     The unrecognised-command entry, reached from the JP at page offset
;;     &0203.  The ROM calls it with the error number that made it give up --
;;     29 "not understood" or 53 "no DOS" -- and CHADD pointing at the
;;     statement.
;;
;;     It moves to the DOS's own stack, pushes ENDS as the return address so
;;     that every command routine ends there, and looks the token up in CTAB.
;; --------------------------------------------------------------------

; ---- SYNTAX ---- from &4203
SYNTAX:
               CP &35                          ; 434E FE 35  NO DOS
               JR Z,SYNT1                      ; 4350 28 04
               CP &1D                          ; 4352 FE 1D  NOT UNDERSTOOD
               JR NZ,ST3HP                     ; 4354 20 0A

;; --------------------------------------------------------------------
;; SYNT1 -- &4356 to &435F
;;
;; Takes:     A
;; Leaves:    HL
;; --------------------------------------------------------------------

; ---- SYNT1 ---- from &4350 when A = &35
SYNT1:
               LD (SVCST),A                    ; 4356 32 31 41  ERROR NUMBER
               LD HL,NRFLG                     ; 4359 21 1F 41  NO RECURSE FLAG
               INC (HL)                        ; 435C 34
               DEC (HL)                        ; 435D 35  test it without disturbing A
               LD (HL),&01                     ; 435E 36 01  "NO RECURSE NOW"

;; --------------------------------------------------------------------
;; ST3HP -- &4360 to &439C
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL, IX, IY
;;
;; ? reaches the ROM through CHADD; calls UNWIND_HOOK_STACK, ZFSP, CLEAR_TSTR, RESET_BUFFER_POINTERS; falls into
;; whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- ST3HP ---- from &4354 when A <> &1D
ST3HP:
               JP NZ,CKESV_1                   ; 4360 C2 E5 43  JP IF E.G. DOS CALLED EXPT1NUM
               CALL UNWIND_HOOK_STACK          ; 4363 CD 6C 44
               LD BC,ENDS                      ; 4366 01 10 50
               PUSH BC                         ; 4369 C5  every command returns to ENDS
               CALL ZFSP                       ; 436A CD 8B 44  ZERO FLAG3 AND HKSP
               CALL CLEAR_TSTR                 ; 436D CD 95 44
               CALL RESET_BUFFER_POINTERS      ; 4370 CD 84 4F
                                               ; read the ROM variable CHADD -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 4373 CD 53 50
               DEFW CHADD                      ; 4376 97 5A
               LD (CCHAD),BC                   ; 4378 ED 43 0C 41
                                               ; read the ROM variable XPTR -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 437C CD 53 50
               DEFW XPTR                       ; 437F A3 5A
               LD (V42E4),BC                   ; 4381 ED 43 E4 42
                                               ; read the ROM variable CSTAT -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 4385 CD 53 50
               DEFW CSTAT                      ; 4388 7B 5A
                                               ; write the ROM variable CHADD
               CALL NRWRD                      ; 438A CD 69 50
               DEFW CHADD                      ; 438D 97 5A
               CALL GCHR                       ; 438F CD 42 50
               CP &3A                          ; 4392 FE 3A
               CALL Z,GTNC                     ; 4394 CC 3C 50  SKIP ANY COLON, CSTAT POINTS TO
               EX DE,HL                        ; 4397 EB
               LD HL,CTABN                     ; 4398 21 EA 42
               LD B,(HL)                       ; 439B 46  NO. OF CMDS
               DEC HL                          ; 439C 2B

;; --------------------------------------------------------------------
;; LCMDL -- &439D to &43A4
;;
;; Takes:     A, B, HL
;; Leaves:    F, B, HL
;; --------------------------------------------------------------------

; ---- LCMDL ---- from &43A3 when B is not 0 yet
LCMDL:
               INC HL                          ; 439D 23
               INC HL                          ; 439E 23
               CP (HL)                         ; 439F BE
               INC HL                          ; 43A0 23
               JR Z,LCMDL_1                    ; 43A1 28 02
               DJNZ LCMDL                      ; 43A3 10 F8  IF NOT FOUND, END ON "CNF" ROUTINE

;; --------------------------------------------------------------------
;; LCMDL_1 -- &43A5 to &43AE
;;
;; Takes:     DE, HL
;; Leaves:    F, BC, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- LCMDL_1 ---- from &43A1
LCMDL_1:
               LD C,(HL)                       ; 43A5 4E
               INC HL                          ; 43A6 23
               LD B,(HL)                       ; 43A7 46
               EX DE,HL                        ; 43A8 EB  HL=CHAD
               BIT 7,B                         ; 43A9 CB 78
               JR NZ,LCMDL_DONE                ; 43AB 20 02
               PUSH BC                         ; 43AD C5
               RET                             ; 43AE C9

;; --------------------------------------------------------------------
;; LCMDL_DONE -- &43AF to &43BA
;;
;; Takes:     BC, DE, HL
;; Leaves:    BC, DE, HL, IY
;;
;; ? calls CALLMB; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- LCMDL_DONE ---- from &43AB when bit 7 of B set
LCMDL_DONE:
               RES 7,B                         ; 43AF CB B8
               LD (V43B8),BC                   ; 43B1 ED 43 B8 43
                                               ; call &0000 in the other page: LMPR is switched first, so that address
                                               ; is how the other listing numbers it
               CALL CALLMB                     ; 43B5 CD BD 42

; ---- V43B8 ---- from &43B1
V43B8:
               DEFW &0000                      ; 43B8 00 00
               RET                             ; 43BA C9

;; --------------------------------------------------------------------
;; CKESV -- &43BB to &43E4
;;
;; This routine moves the return address about with EX (SP),HL, so the
;; register tracking below cannot be trusted: read it as a list of what
;; is touched, not of what is destroyed.
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL
;;
;; ? reaches the ROM through CHADD; calls NRWRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     CHECK EXTERNAL SYNTAX VECTOR
;;      Not ours after all. CHADD is put back where the ROM left it and the user's vector is called, if one is
;;      installed;
;;      a vector above &8000 is called with its own page mapped.
;; --------------------------------------------------------------------

CKESV:
               POP BC                          ; 43BB C1  JUNK ENDS
               EX (SP),HL                      ; 43BC E3  CHAD TO STACK, GET ENTSP
               LD (ENTSP),HL                   ; 43BD 22 04 41  ORIG
               LD BC,(CCHAD)                   ; 43C0 ED 4B 0C 41
                                               ; write the ROM variable CHADD
               CALL NRWRD                      ; 43C4 CD 69 50
               DEFW CHADD                      ; 43C7 97 5A
               POP BC                          ; 43C9 C1  CHAD PTR TO CMD OR AFTER FF
               LD HL,(ONERR)                   ; 43CA 2A 41 42
               LD A,H                          ; 43CD 7C
               OR L                            ; 43CE B5
               LD A,(SVCST)                    ; 43CF 3A 31 41
               JR Z,CKESV_1                    ; 43D2 28 11
               BIT 7,H                         ; 43D4 CB 7C
               JP Z,NEXTST_1                   ; 43D6 CA 3E 42
               IN A,(HMPR)                     ; 43D9 DB FB
               LD D,A                          ; 43DB 57  ORIG
               LD A,(EAPG)                     ; 43DC 3A 44 42
               OUT (HMPR),A                    ; 43DF D3 FB
               LD A,(SVCST)                    ; 43E1 3A 31 41
                                               ; dispatch: the address was worked out above
               JP (HL)                         ; 43E4 E9

;; --------------------------------------------------------------------
;; CKESV_1 -- &43E5 to &43F3
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, BC, HL
;;
;; ? reaches the ROM through BSTKEND; calls NRRDD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CKESV_1 ---- from &4360, &43D2
CKESV_1:
               CP &04                          ; 43E5 FE 04
               JR Z,CKESV_2                    ; 43E7 28 22
               CP &1A                          ; 43E9 FE 1A
               JR NZ,CKESV_3                   ; 43EB 20 38
                                               ; read the ROM variable BSTKEND -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 43ED CD 53 50
               DEFW BSTKEND                    ; 43F0 C4 5B
               LD H,B                          ; 43F2 60
               LD L,C                          ; 43F3 69

;; --------------------------------------------------------------------
;; CKESV_LOOP -- &43F4 to &440A
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL
;;
;; ? reaches the ROM through BSTKEND; calls NRWRD, RDBC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CKESV_LOOP ---- from &43F9
CKESV_LOOP:
               CALL RDBC                       ; 43F4 CD BA 50
               LD A,B                          ; 43F7 78
               OR C                            ; 43F8 B1
               JR NZ,CKESV_LOOP                ; 43F9 20 F9
               INC HL                          ; 43FB 23
               RES 7,H                         ; 43FC CB BC
               SET 6,H                         ; 43FE CB F4
               LD B,H                          ; 4400 44
               LD C,L                          ; 4401 4D
                                               ; write the ROM variable BSTKEND
               CALL NRWRD                      ; 4402 CD 69 50
               DEFW BSTKEND                    ; 4405 C4 5B
               LD A,&1A                        ; 4407 3E 1A
               JR CKESV_3                      ; 4409 18 1A

;; --------------------------------------------------------------------
;; CKESV_2 -- &440B to &4424
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, BC, DE, HL
;;
;; ? reaches the ROM through FLAGS; calls CFSO, NRWR, RETURN_INTO_BC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CKESV_2 ---- from &43E7 when A = &04
CKESV_2:
               CALL CFSO                       ; 440B CD F9 4F
               JR NZ,CKESV_3                   ; 440E 20 15
               LD BC,&0057                     ; 4410 01 57 00
               CALL RETURN_INTO_BC             ; 4413 CD AC 7B
               XOR A                           ; 4416 AF
                                               ; write the ROM variable FLAGS
               CALL NRWR                       ; 4417 CD 74 50
               DEFW FLAGS                      ; 441A 3B 5C
               POP HL                          ; 441C E1
               INC HL                          ; 441D 23
               INC HL                          ; 441E 23
               INC HL                          ; 441F 23
               INC HL                          ; 4420 23
               PUSH HL                         ; 4421 E5
               XOR A                           ; 4422 AF
               LD E,A                          ; 4423 5F
               RET                             ; 4424 C9

;; --------------------------------------------------------------------
;; CKESV_3 -- &4425 to &4432
;;
;; Takes:     A, D, HL
;; Leaves:    A, F, DE, HL
;;
;; ? calls NRWR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CKESV_3 ---- from &43EB when A <> &1A, &4409, &440E
CKESV_3:
               PUSH AF                         ; 4425 F5
               XOR A                           ; 4426 AF
               LD E,A                          ; 4427 5F
                                               ; write the ROM variable &5A60
               CALL NRWR                       ; 4428 CD 74 50
               DEFW &5A60                      ; 442B 60 5A
               LD HL,NRFLG                     ; 442D 21 1F 41  RECURSE OK
               LD (HL),E                       ; 4430 73
               POP AF                          ; 4431 F1
               RET                             ; 4432 C9  A=ERROR NO.

;; --------------------------------------------------------------------
;; HOOK -- &4433 to &446B
;;
;; Takes:     A, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through XPTR+1; calls UNWIND_HOOK_STACK, ZFSP, NRWR; falls into whatever follows rather than
;; returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The RST &08 hook handler, reached from the JP at page offset &0200.
;;
;;     The code byte after the RST is doubled to index SAMHK, which discards
;;     bit 7 in the process, so codes 128 upwards map onto entries 0 upwards.
;;     Both register sets are saved first, then INDJP jumps to the entry.
;; --------------------------------------------------------------------

; ---- HOOK ---- from &4200
HOOK:
               ADD A,A                         ; 4433 87  JUNK BIT 7, MAKE WORD OFFSET
               LD (SVCST),A                    ; 4434 32 31 41  HOOK CODE OFFSET
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 4437 08
               LD (HKA),A                      ; 4438 32 DD 41
               CALL UNWIND_HOOK_STACK          ; 443B CD 6C 44
               LD (SVHDR),IX                   ; 443E DD 22 0A 41
                                               ; to the alternate register set and back again
               EXX                             ; 4442 D9
               LD (HKHL),HL                    ; 4443 22 DE 41
               LD (HKDE),DE                    ; 4446 ED 53 E0 41
               LD (HKBC),BC                    ; 444A ED 43 E2 41
                                               ; to the alternate register set and back again
               EXX                             ; 444E D9
               CALL ZFSP                       ; 444F CD 8B 44
                                               ; write the ROM variable XPTR+1
               CALL NRWR                       ; 4452 CD 74 50  A=0
               DEFW XPTR+1                     ; 4455 A4 5A
               LD HL,(SVCST)                   ; 4457 2A 31 41  H=JUNK
               LD A,(HKA)                      ; 445A 3A DD 41
               LD DE,SAMHK                     ; 445D 11 A6 44
               CALL INDJP                      ; 4460 CD CD 78  INDEXED JP USING L
               CALL SETBORDER_BORDCR           ; 4463 CD 52 51
                                               ; to the alternate register set and back again
               EXX                             ; 4466 D9  PASS HL,DE,BC OUT VIA ALT REGS
               XOR A                           ; 4467 AF  "NO ERROR"
               LD E,A                          ; 4468 5F  "NO ACTION"
               JP RENT                         ; 4469 C3 25 50  RESTORE ORIG ENTSP

;; --------------------------------------------------------------------
;; UNWIND_HOOK_STACK -- &446C to &448A
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL, IY
;;
;; ? reaches the ROM through DOSSTK; calls NRRDD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Take the return address into IY, read DOSSTK, and LDDR six bytes down
;;     from &7FFF -- the stack the DOS unwinds to when a hook gives up.
;; --------------------------------------------------------------------

; ---- UNWIND_HOOK_STACK ---- from &4363, &443B
UNWIND_HOOK_STACK:
               POP IY                          ; 446C FD E1  RET ADDR
                                               ; read the ROM variable DOSSTK -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 446E CD 53 50
               DEFW DOSSTK                     ; 4471 59 5C
               LD D,B                          ; 4473 50
               DEFB &59                        ; 4474 Y  READ - SET TO 7FF0H BY BASIC
               DEC DE                          ; 4475 1B
               LD HL,&7FFF                     ; 4476 21 FF 7F
               LD BC,&0006                     ; 4479 01 06 00
               LDDR                            ; 447C ED B8
               INC DE                          ; 447E 13
               EX DE,HL                        ; 447F EB
                                               ; the stack is being reset, so this path does not return
               LD SP,HL                        ; 4480 F9  NEW STACK SO THAT
               LD HL,(ENTSP)                   ; 4481 2A 04 41
               PUSH HL                         ; 4484 E5  OLD VALUE RESTORED ON EXIT
               LD (ENTSP),SP                   ; 4485 ED 73 04 41
                                               ; dispatch: the address was worked out above
               JP (IY)                         ; 4489 FD E9

;; --------------------------------------------------------------------
;; ZFSP -- &448B to &4494
;;
;; Takes:     A
;; Leaves:    A, F, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- ZFSP ---- from &436A, &444F
ZFSP:
               XOR A                           ; 448B AF
               LD (FLAG3),A                    ; 448C 32 0C 7C
               LD H,A                          ; 448F 67
               LD L,A                          ; 4490 6F
               LD (HKSP),HL                    ; 4491 22 0B 42
               RET                             ; 4494 C9

;; --------------------------------------------------------------------
;; CLEAR_TSTR -- &4495 to &449C
;;
;; Takes:     A
;; Leaves:    A, B, HL
;;
;; Shown for this routine in disasm/:
;;
;;     Fill TSTR1 up to UIFA with &FF and set RDAT to the same, which is the
;;     DOS's "nothing here" for a temporary string and its data flag.  The
;;     length is written as UIFA-TSTR1 so the two can move without this
;;     needing to know how far apart they are.
;; --------------------------------------------------------------------

; ---- CLEAR_TSTR ---- from &436D, &638A
CLEAR_TSTR:
               PUSH AF                         ; 4495 F5
               LD A,&FF                        ; 4496 3E FF
               LD HL,TSTR1                     ; 4498 21 32 41
               LD B,UIFA-TSTR1                 ; 449B 06 4B

;; --------------------------------------------------------------------
;; CLEAR_TSTR_LOOP -- &449D to &4519
;;
;; Takes:     A, B, HL
;; Leaves:    A, F, B, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CLEAR_TSTR_LOOP ---- from &449F when B is not 0 yet
CLEAR_TSTR_LOOP:
               LD (HL),A                       ; 449D 77
               INC HL                          ; 449E 23
               DJNZ CLEAR_TSTR_LOOP            ; 449F 10 FC
               LD (RDAT),A                     ; 44A1 32 0D 42
               POP AF                          ; 44A4 F1
               RET                             ; 44A5 C9

;; --------------------------------------------------------------------
;; SAMHK -- the RST &08 hook table.  Entry i is code 128+i.
;;
;; Codes 169, 171 and 173 point into the MasterBASIC page, with bit 15
;; set.  They are what the three ROM vectors MasterBASIC repoints at boot
;; end up reaching -- print a token, match a keyword while tokenising, and
;; dispatch a command.  The vectors themselves hold the addresses of short
;; stubs planted in the ROM's system page at &4BA0, each of which filters
;; on the token and then does RST &08 with the code.  Code 172, the
;; function evaluator, is still the DOS's own HKLEN.
;; --------------------------------------------------------------------

SAMHK:
               DEFW INIT                                        ; 44A6 code 128
               DEFW HGTHD                                       ; 44A8 code 129
               DEFW HK_HLOAD                                    ; 44AA code 130
               DEFW HVERY                                       ; 44AC code 131
               DEFW HK_HSAVE                                    ; 44AE code 132
               DEFW HK_SKSAFE                                   ; 44B0 code 133
               DEFW HK_HOPEN                                    ; 44B2 code 134
               DEFW HK_HCLOS                                    ; 44B4 code 135
               DEFW HAUTO                                       ; 44B6 code 136
               DEFW HSKTD                                       ; 44B8 code 137
               DEFW HK_HDUMMY                                   ; 44BA code 138
               DEFW HK_HVAR                                     ; 44BC code 139
               DEFW HEOF                                        ; 44BE code 140
               DEFW HPTR                                        ; 44C0 code 141
               DEFW HPATH                                       ; 44C2 code 142
               DEFW HK_HLDPG                                    ; 44C4 code 143
               DEFW HVEPG                                       ; 44C6 code 144
               DEFW HSDIR                                       ; 44C8 code 145
               DEFW ROFSM                                       ; 44CA code 146
               DEFW HOFLE                                       ; 44CC code 147
               DEFW HK_SBYT                                     ; 44CE code 148
               DEFW HWSAD                                       ; 44D0 code 149
               DEFW HK_HKSB                                     ; 44D2 code 150
               DEFW HDBOP                                       ; 44D4 code 151
               DEFW SCFSM                                       ; 44D6 code 152
               DEFW MB_HK_HORDER+NOT_IN_THIS_PAGE               ; 44D8 code 153
               DEFW MB_HK_HDUMMY+NOT_IN_THIS_PAGE               ; 44DA code 154
               DEFW MB_HK_PIXELCELL+NOT_IN_THIS_PAGE            ; 44DC code 155
               DEFW MB_HK_SWAPCHARS+NOT_IN_THIS_PAGE            ; 44DE code 156
               DEFW MB_HK_PROGPREP+NOT_IN_THIS_PAGE             ; 44E0 code 157
               DEFW HK_HGFLE                                    ; 44E2 code 158
               DEFW LBYT                                        ; 44E4 code 159
               DEFW HRSAD                                       ; 44E6 code 160
               DEFW HK_HLDBK                                    ; 44E8 code 161
               DEFW HFRSAD                                      ; 44EA code 162
               DEFW HFWSAD                                      ; 44EC code 163
               DEFW REST                                        ; 44EE code 164
               DEFW HK_PCAT                                     ; 44F0 code 165
               DEFW HERAZ                                       ; 44F2 code 166
               DEFW MCHWR                                       ; 44F4 code 167
               DEFW MCHRD                                       ; 44F6 code 168
               DEFW MB_HPRTOK+NOT_IN_THIS_PAGE                  ; 44F8 code 169
               DEFW MB_HK_HPFF+NOT_IN_THIS_PAGE                 ; 44FA code 170
               DEFW MB_HGTTK+NOT_IN_THIS_PAGE                   ; 44FC code 171
               DEFW HKLEN                                       ; 44FE code 172
               DEFW MB_HCMDV+NOT_IN_THIS_PAGE                   ; 4500 code 173
               DEFW MB_HK_RCPTCH+NOT_IN_THIS_PAGE               ; 4502 code 174
               DEFW MB_HK_MERGECOMPFLG+NOT_IN_THIS_PAGE         ; 4504 code 175
               DEFW MB_HK_FARSCAN+NOT_IN_THIS_PAGE              ; 4506 code 176
               DEFW MB_HK_TOKENARG+NOT_IN_THIS_PAGE             ; 4508 code 177
               DEFW MB_HK_SKIPNAME+NOT_IN_THIS_PAGE             ; 450A code 178
               DEFW MB_HK_PUTARG+NOT_IN_THIS_PAGE               ; 450C code 179
               DEFW MB_HK_SERSEND+NOT_IN_THIS_PAGE              ; 450E code 180
               DEFW MB_HK_SERRECV+NOT_IN_THIS_PAGE              ; 4510 code 181
               DEFW MB_SUBSTITUTE_PRINTER_CHAR+NOT_IN_THIS_PAGE ; 4512 code 182
               DEFW MB_HK_COMADENT+NOT_IN_THIS_PAGE             ; 4514 code 183
               DEFW MB_HK_VARSPACE+NOT_IN_THIS_PAGE             ; 4516 code 184
               DEFW MB_HK_SETUPREGS+NOT_IN_THIS_PAGE            ; 4518 code 185

;; --------------------------------------------------------------------
;; GET_DISK_PORT_BASE -- &451A to &4520
;;
;; Takes:     A
;; Leaves:    C
;; Preserves: A, F (saved and restored)
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     PART C11 -- The disk driver
;;
;;       COMMP .. COMMR        addressing the controller's registers
;;       PRECMP / SADC / BUSY  issuing a command
;;       WSAD / RSAD           write and read one sector, with retries
;;       NRSAD                 read a directory sector, building the
;;                             free-sector map as it goes
;;
;;     Gets the disk port IO base, incorporating the disk controller
;;     selection and disk head (side) selection bit.
;;
;;     What was here before:
;;
;;          PART C11 -- The disk driver
;;
;;            COMMP .. COMMR        addressing the controller's registers
;;            PRECMP / SADC / BUSY  issuing a command
;;            WSAD / RSAD           write and read one sector, with retries
;;            NRSAD                 read a directory sector, building the free-sector map as it goes
;;            SRSAD                 read a sector while counting delimiters, for POINT
;;            CDEC / CTSL / CTAS    error recovery, and seeking
;;            REST / TFIHO          restoring the drive, and proving the disk is turning
;;            CKDRV / SELD          drive validation and selection
;;            LDBLK / SVBLK         whole blocks, streamed a sector at a time
;;
;;          Differences from SAMDOS
;;
;;          The shape is SAMDOS's, but three things have changed:
;;
;;            Self-modifying ports. SAMDOS bracketed each transfer with INC C / INC C / INC C ... DEC C to move between
;;            the
;;            status and data registers. MasterDOS instead patches the port numbers into the IN and OUT instructions
;;            before the
;;            loop starts, which is faster in the loop and leaves C free.
;;
;;            RAM discs. Every operation begins with TIRD, "test if RAM disc". Drives 3 to RDLIM-1 are RAM discs, and
;;            for
;;            those the call is diverted to an equivalent in part RAMD that copies pages instead of driving the
;;            controller.
;;
;;            A dirty flag. Bit 3 of (IX+MFLG) records that the sector in the buffer has been written to, so WRIF can
;;            flush it
;;            only when there is something to flush. SAMDOS wrote the buffer back unconditionally.
;;
;;          COMMP / TRCKP / COMMR -- reach the controller's registers
;;
;;          DSC holds the base port with the drive and side selection already in its high bits, so the four registers
;;          are at
;;          DSC+0 (command and status), +1 (track), +2 (sector) and +3 (data).
;; --------------------------------------------------------------------

; ---- GET_DISK_PORT_BASE ---- from &4521, &4527, &452F, &55AE
GET_DISK_PORT_BASE:
               PUSH AF                         ; 451A F5
               LD A,(DSC)                      ; 451B 3A 10 41
               LD C,A                          ; 451E 4F
               POP AF                          ; 451F F1
               RET                             ; 4520 C9

;; --------------------------------------------------------------------
;; TRCKP -- &4521 to &4525
;;
;; Takes:     A
;; Leaves:    F, C
;; Ends:      RET
;;
;; ? calls GET_DISK_PORT_BASE.
;; --------------------------------------------------------------------

; ---- TRCKP ---- from &46FE, &4751
TRCKP:
               CALL GET_DISK_PORT_BASE         ; 4521 CD 1A 45
               INC C                           ; 4524 0C
               RET                             ; 4525 C9

;; --------------------------------------------------------------------
;; READ_SELECTED_DISK_STATUS -- &4526 to &452D
;;
;; Takes:     A, BC
;; Leaves:    A, F
;; Preserves: BC (saved and restored)
;; Ends:      RET
;;
;; ? drives IN A,(C); calls GET_DISK_PORT_BASE.
;; --------------------------------------------------------------------

; ---- READ_SELECTED_DISK_STATUS ---- from &456D, &47BA, &47D5, &47E2
READ_SELECTED_DISK_STATUS:
               PUSH BC                         ; 4526 C5
               CALL GET_DISK_PORT_BASE         ; 4527 CD 1A 45
               IN A,(C)                        ; 452A ED 78
               POP BC                          ; 452C C1
               RET                             ; 452D C9

;; --------------------------------------------------------------------
;; WRITE_SELECTED_DISK_CMD -- &452E to &4535
;;
;; Takes:     A, BC
;; Leaves:    registers unchanged
;; Preserves: BC (saved and restored)
;; Ends:      RET
;;
;; ? drives OUT (C),A; calls GET_DISK_PORT_BASE.
;; --------------------------------------------------------------------

; ---- WRITE_SELECTED_DISK_CMD ---- from &455C
WRITE_SELECTED_DISK_CMD:
               PUSH BC                         ; 452E C5
               CALL GET_DISK_PORT_BASE         ; 452F CD 1A 45
               OUT (C),A                       ; 4532 ED 79
               POP BC                          ; 4534 C1
               RET                             ; 4535 C9

;; --------------------------------------------------------------------
;; CKDE -- &4536 to &4538
;;
;; Takes:     DE
;; Leaves:    A, F
;;
;; Shown for this routine in disasm/:
;;
;;     (PGES1) is a page number, and DE is an offset in the range 0000-7FFF.
;;
;;     On entry, DE is about to be decremented. The routine checks if DE would cross
;;     a page boundary as it is decremented.
;;
;;     If it would, the PGES1 value is decremented, and the DE value is adjusted upwards by 16K.
;; --------------------------------------------------------------------

; ---- CKDE ---- from &4972
CKDE:
               LD A,D                          ; 4536 7A
               OR E                            ; 4537 B3
               RET NZ                          ; 4538 C0

;; --------------------------------------------------------------------
;; ADJUST_PAGE_DE -- &4539 to &4546
;;
;; Takes:     D
;; Leaves:    A, F, D
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Similar to CKDE, except it always perfoms the adjustment and doesn't check if DE
;;     is about to cross a page boundary first.
;; --------------------------------------------------------------------

; ---- ADJUST_PAGE_DE ---- from &4859
ADJUST_PAGE_DE:
               LD A,(PGES1)                    ; 4539 3A 50 41
               AND A                           ; 453C A7
               RET Z                           ; 453D C8
               DEC A                           ; 453E 3D
               LD (PGES1),A                    ; 453F 32 50 41
               LD A,D                          ; 4542 7A
               ADD A,&40                       ; 4543 C6 40
               LD D,A                          ; 4545 57
               RET                             ; 4546 C9

;; --------------------------------------------------------------------
;; PRECMX -- &4547 to &4548
;;
;; Takes:     nothing in registers
;; Leaves:    C
;;
;; Shown for this routine in disasm/:
;;
;;     PRECOMPENSATION CALCULATOR
;;      The inner tracks have the highest bit density and need their transitions shifted to compensate. Bit 1 of the
;;      write
;;      command turns that off; it is left off for the outer half of the disk and switched on for the inner half.
;; --------------------------------------------------------------------

; ---- PRECMX ---- from &4590, &49F4, &79FE
PRECMX:
               LD C,WRITE_SECTOR_CMD           ; 4547 0E A2

;; --------------------------------------------------------------------
;; PRECMP -- &4549 to &4557
;;
;; Takes:     C, D, HL
;; Leaves:    A, F, BC, HL
;;
;; ? calls TSTD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- PRECMP ---- from &55BB
PRECMP:
               CALL TSTD                       ; 4549 CD F4 4A  GET TRACKS ON DISC
               RRA                             ; 454C 1F
               AND &3F                         ; 454D E6 3F  ** MASK TOP BIT (SIDEDNES),
               LD B,A                          ; 454F 47  HALVE TRK/SIDE USUALLY 40D
               LD A,D                          ; 4550 7A
               AND &7F                         ; 4551 E6 7F
               SUB B                           ; 4553 90  E.G. TRACK 0-40=CY, SO JR LEAVING
               JR C,WAIT_DC_READY_BEFORE_CMD   ; 4554 38 02  JR IF CURRENT TRK IN D IS AN
               RES 1,C                         ; 4556 CB 89  ELSE TURN *ON* PRECMP

;; --------------------------------------------------------------------
;; WAIT_DC_READY_BEFORE_CMD -- &4558 to &455A
;;
;; Takes:     A, BC
;; Leaves:    A, F
;;
;; ? calls BUSY; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Wait for the disk controller to be ready before continuing.
;; --------------------------------------------------------------------

; ---- WAIT_DC_READY_BEFORE_CMD ---- from &4554 when A < B, &456A, &46F1, &478D, &48B4, &4F9D, &54B7
WAIT_DC_READY_BEFORE_CMD:
               CALL BUSY                       ; 4558 CD 6D 45

;; --------------------------------------------------------------------
;; WRITE_DRIVE_CMD_AND_DELAY -- &455B to &4560
;;
;; Takes:     BC
;; Leaves:    A, B
;;
;; ? calls WRITE_SELECTED_DISK_CMD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- WRITE_DRIVE_CMD_AND_DELAY ---- from &47CC
WRITE_DRIVE_CMD_AND_DELAY:
               LD A,C                          ; 455B 79
               CALL WRITE_SELECTED_DISK_CMD    ; 455C CD 2E 45
               LD B,&14                        ; 455F 06 14

;; --------------------------------------------------------------------
;; POST_CMD_WAIT -- &4561 to &4563
;;
;; Takes:     B
;; Leaves:    B
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- POST_CMD_WAIT ---- from &4561 when B is not 0 yet
POST_CMD_WAIT:
               DJNZ POST_CMD_WAIT              ; 4561 10 FE
               RET                             ; 4563 C9

;; --------------------------------------------------------------------
;; DWAIT -- &4564 to &456C
;;
;; Takes:     B
;; Leaves:    A, F, C
;;
;; ? calls WAIT_DC_READY_BEFORE_CMD, TIRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      DWAIT -- make sure the drive is up to speed before a write
;;
;;      A read-address command is issued purely for its side effect: it spins the motor up and does not return until the
;;      disk is turning. Without it a write issued straight after a step could start before the drive was ready, because
;;      the controller would already think the drive was running.
;; --------------------------------------------------------------------

; ---- DWAIT ---- from &4583, &493D, &4D6B, &5A80, &666A
DWAIT:
               CALL TIRD                       ; 4564 CD 5A 61
               RET NC                          ; 4567 D0
               LD C,READ_ADDRESS_CMD           ; 4568 0E C0  READ ADDRESS CMD CODE
               CALL WAIT_DC_READY_BEFORE_CMD   ; 456A CD 58 45  SPIN UP DISC IN CASE IT IS OFF

;; --------------------------------------------------------------------
;; BUSY -- &456D to &4577
;;
;; Takes:     A, BC
;; Leaves:    A, F
;; Ends:      JR
;;
;; ? calls READ_SELECTED_DISK_STATUS, BRKTST.
;;
;; Shown for this routine in disasm/:
;;
;;     (OR STEP IN/OUT WILL START DRIVE,
;;     THEN WSAD WILL WRITE TOO SOON
;;     'COS "DRIVE RUNNING") WAIT TILL
;;     FINISHED CMD (ALTERS SECT REG)
;;     TEST FOR CHIP BUSY
;; --------------------------------------------------------------------

; ---- BUSY ---- from &4558, &4576, &474E, &47BF when bit 2 of A set, &7A01
BUSY:
               CALL READ_SELECTED_DISK_STATUS  ; 456D CD 26 45
               BIT 0,A                         ; 4570 CB 47
               RET Z                           ; 4572 C8
               CALL BRKTST                     ; 4573 CD 2A 50
               JR BUSY                         ; 4576 18 F5

;; --------------------------------------------------------------------
;; WRIF -- &4578 to &457A
;;
;; Takes:     IX
;; Leaves:    DE
;;
;; ? calls GET_TRACK_AND_SECTOR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- WRIF ---- from &6E8E, &70FD, &7146
WRIF:
               CALL GET_TRACK_AND_SECTOR       ; 4578 CD BF 4F  GET DE=CUR SECTOR

;; --------------------------------------------------------------------
;; WRIF2 -- &457B to &457F
;;
;; Takes:     IX
;; Leaves:    F
;; --------------------------------------------------------------------

; ---- WRIF2 ---- from &6FC8
WRIF2:
               BIT 3,(IX+&0C)                  ; 457B DD CB 0C 5E
               RET Z                           ; 457F C8  RET IF SECTOR HAS NOT BEEN

;; --------------------------------------------------------------------
;; WRITE_SECTOR -- &4580 to &4582
;;
;; Takes:     IX
;; Leaves:    A
;;
;; ? calls SELECT_DRIVE; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     A sector out: wait for the drive with DWAIT, check the track through
;;     TIRDXDCT, then interrupts off, CTAS and PRECMX to position, and the
;;     drive's status port poked into CHECK_WRITE_STATUS's own operand from
;;     DSC before the transfer.
;; --------------------------------------------------------------------

; ---- WRITE_SECTOR ---- from &6FA7
WRITE_SECTOR:
               CALL SELECT_DRIVE               ; 4580 CD 29 48

;; --------------------------------------------------------------------
;; NWSAD -- &4583 to &4585
;;
;; Takes:     B
;; Leaves:    A, F, C
;;
;; ? calls DWAIT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

NWSAD:
               CALL DWAIT                      ; 4583 CD 64 45

;; --------------------------------------------------------------------
;; WSAD -- &4586 to &458C
;;
;; Takes:     A
;; Leaves:    A, F
;;
;; ? calls TIRDXDCT; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      WSAD -- write the sector buffer to track D, sector E
;;
;;      Loops until the sector is written or CDEC gives up. The exit is unusual: on success CDEC discards the return
;;      address of the call below it and returns to WSAD's own caller with HL pointing at the buffer, so the JR is only
;;      ever reached on a retry.
;;
;;      Errors: REP23 if the disk is write protected, REP4 after ten attempts
;;
;;     WRITE SECTOR AT DE
;; --------------------------------------------------------------------

; ---- WSAD ---- from &495F, &49D3, &4D8A, &4DFB, &4E62, &556E, &5D1A, &5D2C ...
WSAD:
               CALL TIRDXDCT                   ; 4586 CD 56 61
               JP NC,RDWSCT                    ; 4589 D2 C1 74  a RAM disc: copy pages instead
               DI                              ; 458C F3

;; --------------------------------------------------------------------
;; WSA1 -- &458D to &45AB
;;
;; Takes:     DE, IX
;; Leaves:    A, F, C, HL
;; Ends:      JR
;;
;; ? calls PRECMX, CHECK_WRITE_STATUS, RETRY_OR_GIVE_UP, CTAS.
;; --------------------------------------------------------------------

; ---- WSA1 ---- from &45AA
WSA1:
               CALL CTAS                       ; 458D CD 38 47
               CALL PRECMX                     ; 4590 CD 47 45  WRITE SECTOR CMD
               LD A,(DSC)                      ; 4593 3A 10 41
                                               ; self-modifying: patches the operand of the IN at &45AE
               LD (CHECK_WRITE_STATUS+1),A     ; 4596 32 AF 45  SELF-MOD STATUS PORT
               ADD A,DISKCTL_DATA_OFS          ; 4599 C6 03
               LD C,A                          ; 459B 4F  DATA PORT
               CALL GTBUF                      ; 459C CD A0 4F
               CALL CHECK_WRITE_STATUS         ; 459F CD AE 45
               BIT 5,A                         ; 45A2 CB 6F
               JP NZ,REP23                     ; 45A4 C2 80 51  ERROR IF WRITE-PROTECTED
               CALL RETRY_OR_GIVE_UP           ; 45A7 CD C6 46
               JR WSA1                         ; 45AA 18 E1

;; --------------------------------------------------------------------
;; WRITE_DATA_LOOP -- &45AC to &45AD
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; --------------------------------------------------------------------

; ---- WRITE_DATA_LOOP ---- from &45B3 when bit 0 was set
WRITE_DATA_LOOP:
               OUTI                            ; 45AC ED A3

;; --------------------------------------------------------------------
;; CHECK_WRITE_STATUS -- &45AE to &45B6
;;
;; Takes:     nothing in registers
;; Leaves:    A, F
;; Ends:      JR
;;
;; ? drives IN A,(&00).
;;
;; Shown for this routine in disasm/:
;;
;;     Checks the command status to see if the write is complete, and if not, loops until the
;;     controller is ready to write another byte.
;;
;;     The status port to use is set by self-modifying code. This ensures that the
;;     correct drive is used, and the correct drive-head is energized.
;; --------------------------------------------------------------------

; ---- CHECK_WRITE_STATUS ---- from &459F, &45B5, &55C2
CHECK_WRITE_STATUS:
               IN A,(&00)                      ; 45AE DB 00  Read the drive controller status port (specific port chosen
                                               ; by code above)
               RRCA                            ; 45B0 0F
               RET NC                          ; 45B1 D0  RET IF DONE
               RRCA                            ; 45B2 0F
               JR C,WRITE_DATA_LOOP            ; 45B3 38 F7  JR IF DISK READY FOR BYTE
               JR CHECK_WRITE_STATUS           ; 45B5 18 F7

;; --------------------------------------------------------------------
;; READ_SECTOR -- &45B7 to &45BC
;;
;; Takes:     A
;; Leaves:    A, F
;;
;; ? calls TIRDXDCT; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The read side, and the most called routine in this half.  TIRDXDCT
;;     checks the track, RSSR selects the sector, RDDATA does the transfer,
;;     and a failure goes round again from &45BD rather than giving up at
;;     once.
;; --------------------------------------------------------------------

; ---- READ_SECTOR ---- from &4602, &4633 when bit 5 of A clear, &48FF, &4E08, &5558, &5582, &5A14, &5D62 ...
READ_SECTOR:
               CALL TIRDXDCT                   ; 45B7 CD 56 61
               JP NC,RDRSCT                    ; 45BA D2 33 75

;; --------------------------------------------------------------------
;; READ_SECTOR_LOOP -- &45BD to &45C7
;;
;; Takes:     B, DE, HL, IX
;; Leaves:    A, F, C, HL
;; Ends:      JR
;;
;; ? calls RDDATA, RETRY_OR_GIVE_UP, RSSR.
;; --------------------------------------------------------------------

; ---- READ_SECTOR_LOOP ---- from &45C6
READ_SECTOR_LOOP:
               CALL RSSR                       ; 45BD CD 97 4F
               CALL RDDATA                     ; 45C0 CD C8 45
               CALL RETRY_OR_GIVE_UP           ; 45C3 CD C6 46
               JR READ_SECTOR_LOOP             ; 45C6 18 F5

;; --------------------------------------------------------------------
;; RDDATA -- &45C8 to &45D4
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; Ends:      JR
;;
;; ? drives IN A,(&00).
;; --------------------------------------------------------------------

; ---- RDDATA ---- from &45C0, &46F7, &54BD
RDDATA:
               LD A,(DSC)                      ; 45C8 3A 10 41  STATUS PORT
                                               ; self-modifying: patches the operand of the IN at &45D9
               LD (CHECK_READ_STATUS+1),A      ; 45CB 32 DA 45  patches the port of the IN at &45D9
               ADD A,DISKCTL_DATA_OFS          ; 45CE C6 03
                                               ; self-modifying: patches the operand of the IN at &45D5
               LD (READ_DATA_LOOP+1),A         ; 45D0 32 D6 45  patches the port of the IN at &45D5
               JR CHECK_READ_STATUS            ; 45D3 18 04

;; --------------------------------------------------------------------
;; READ_DATA_LOOP -- &45D5 to &45D8
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;;
;; ? drives IN A,(&00); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- READ_DATA_LOOP ---- from &45E0
READ_DATA_LOOP:
               IN A,(&00)                      ; 45D5 DB 00  the port is written here at run time, from &45D0
               LD (HL),A                       ; 45D7 77
               INC HL                          ; 45D8 23

;; --------------------------------------------------------------------
;; CHECK_READ_STATUS -- &45D9 to &45E1
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; Ends:      JR
;;
;; ? drives IN A,(&00).
;;
;; Shown for this routine in disasm/:
;;
;;     Checks the command status to see if the read op is complete, and if not, loops until the
;;     controller has read another byte from the disk.
;;
;;     The status port to use is set by self-modifying code. This ensures that the
;;     correct drive is used, and the correct drive-head is energized.
;; --------------------------------------------------------------------

; ---- CHECK_READ_STATUS ---- from &45D3, &45DE when bit 0 was clear
CHECK_READ_STATUS:
               IN A,(&00)                      ; 45D9 DB 00  Read the drive controller status port (specific port chosen
                                               ; by code above)
               RRCA                            ; 45DB 0F
               RET NC                          ; 45DC D0  RET IF READ SECTOR CMD FINISHED
               RRA                             ; 45DD 1F
               JR NC,CHECK_READ_STATUS         ; 45DE 30 F9  JR IF NO BYTE IS READY TO READ
               JR READ_DATA_LOOP               ; 45E0 18 F3

;; --------------------------------------------------------------------
;; SECTOR_FOR_CHANNEL -- &45E2 to &45F8
;;
;; Takes:     DE, IX
;; Leaves:    A, F, E, HL
;;
;; ? calls GETSCR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Take the flags at (IX+&04) and decide how to reach the data: bit 2
;;     sends it through GETSCR for a screen, and what comes back is checked
;;     against &04 before being used.
;; --------------------------------------------------------------------

; ---- SECTOR_FOR_CHANNEL ---- from &4B44, &4B85
SECTOR_FOR_CHANNEL:
               LD A,(IX+&04)                   ; 45E2 DD 7E 04
               BIT 2,A                         ; 45E5 CB 57
               JR Z,SECTOR_FOR_CHANNEL_3       ; 45E7 28 48
               CALL GETSCR                     ; 45E9 CD 2C 49
               PUSH DE                         ; 45EC D5
               LD A,D                          ; 45ED 7A
               CP &04                          ; 45EE FE 04
               LD A,E                          ; 45F0 7B
               JR NZ,SECTOR_FOR_CHANNEL_1      ; 45F1 20 06
               CP &02                          ; 45F3 FE 02
               JR NZ,SECTOR_FOR_CHANNEL_2      ; 45F5 20 1B
               DEC A                           ; 45F7 3D
               LD E,A                          ; 45F8 5F

;; --------------------------------------------------------------------
;; SECTOR_FOR_CHANNEL_1 -- &45F9 to &45FE
;;
;; Takes:     A
;; Leaves:    A, F, HL
;; --------------------------------------------------------------------

; ---- SECTOR_FOR_CHANNEL_1 ---- from &45F1 when A <> &04
SECTOR_FOR_CHANNEL_1:
               DEC A                           ; 45F9 3D
               JR NZ,SECTOR_FOR_CHANNEL_2      ; 45FA 20 16
               LD HL,MB_NEXT_SCREEN_BYTE_1     ; 45FC 21 80 A2

;; --------------------------------------------------------------------
;; SECTOR_FOR_CHANNEL_LOOP -- &45FF to &4611
;;
;; Takes:     A, E, HL
;; Leaves:    A, F, E, HL
;;
;; ? calls READ_SECTOR, ISECT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SECTOR_FOR_CHANNEL_LOOP ---- from &460A
SECTOR_FOR_CHANNEL_LOOP:
               LD (BUF),HL                     ; 45FF 22 0F 7C
               CALL READ_SECTOR                ; 4602 CD B7 45
               INC H                           ; 4605 24
               INC H                           ; 4606 24
               CALL ISECT                      ; 4607 CD 24 56
               JR NZ,SECTOR_FOR_CHANNEL_LOOP   ; 460A 20 F3
               LD HL,DRAM                      ; 460C 21 13 7D
               LD (BUF),HL                     ; 460F 22 0F 7C

;; --------------------------------------------------------------------
;; SECTOR_FOR_CHANNEL_2 -- &4612 to &4627
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, HL
;; Preserves: DE (saved and restored)
;; --------------------------------------------------------------------

; ---- SECTOR_FOR_CHANNEL_2 ---- from &45F5 when A <> &02, &45FA when A is not 0 yet
SECTOR_FOR_CHANNEL_2:
               POP DE                          ; 4612 D1
               PUSH DE                         ; 4613 D5
               LD A,E                          ; 4614 7B
               ADD A,A                         ; 4615 87
               ADD A,&A0                       ; 4616 C6 A0
               LD H,A                          ; 4618 67
               LD L,&80                        ; 4619 2E 80
               LD DE,DRAM                      ; 461B 11 13 7D
               LD BC,&0200                     ; 461E 01 00 02
               LDIR                            ; 4621 ED B0
               XOR A                           ; 4623 AF
               LD (V7C0E),A                    ; 4624 32 0E 7C
               POP DE                          ; 4627 D1

;; --------------------------------------------------------------------
;; SET_SCREEN_POINTER -- &4628 to &4630
;;
;; Takes:     HL
;; Leaves:    A
;; Ends:      RET
;;
;; ? drives OUT (HMPR),A.
;;
;; Shown for this routine in disasm/:
;;
;;     Store HL in PTRSCR and put PORT1 back into HMPR, which is the pair
;;     that ends every access to a screen the DOS has borrowed.
;; --------------------------------------------------------------------

; ---- SET_SCREEN_POINTER ---- from &49CF, &55A6, &5BBB, &7943
SET_SCREEN_POINTER:
               LD (PTRSCR),HL                  ; 4628 22 2C 41
               LD A,(PORT1)                    ; 462B 3A 2E 41
               OUT (HMPR),A                    ; 462E D3 FB
               RET                             ; 4630 C9

;; --------------------------------------------------------------------
;; SECTOR_FOR_CHANNEL_3 -- &4631 to &4634
;;
;; Takes:     A
;; Leaves:    F
;; --------------------------------------------------------------------

; ---- SECTOR_FOR_CHANNEL_3 ---- from &45E7 when bit 2 of A clear
SECTOR_FOR_CHANNEL_3:
               BIT 5,A                         ; 4631 CB 6F
               JR Z,READ_SECTOR                ; 4633 28 82

;; --------------------------------------------------------------------
;; NRSAD -- &4635 to &463A
;;
;; Takes:     A
;; Leaves:    A, F
;;
;; ? calls TIRDXDCT; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      NRSAD -- read a directory sector, accumulating the free-sector map as it goes
;;
;;      As well as reading the sector, this ORs the bytes of every directory entry that is in use into the page holding
;;      NSAM. Each file's own sector map sits at a fixed offset within its entry, and NSAM is placed so that the offsets
;;      line up -- so by the time the directory has been scanned, the map of sectors in use has been rebuilt for free.
;;
;;      L' counts bytes within the entry and wraps every 256; at each wrap NRS22 looks at the first byte of the new
;;      entry.
;;      If the entry is in use H' is set to NSAM's page, and if it is free H' is set to zero, so the accumulation goes
;;      to
;;      ROM and is discarded.
;;
;;      The port numbers are patched into the instructions rather than held in registers, because there is not enough
;;      time
;;      to do both that and service the data request.
;;
;;     READ SECTOR AT DE
;; --------------------------------------------------------------------

NRSAD:
               CALL TIRDXDCT                   ; 4635 CD 56 61
               JP NC,NRDRSCT                   ; 4638 D2 16 75

;; --------------------------------------------------------------------
;; NRSA1 -- &463B to &464D
;;
;; Takes:     B, DE, HL, IX
;; Leaves:    A, F, BC, HL
;; Preserves: DE (saved and restored)
;; Ends:      JR
;;
;; ? calls NRDDATA, RETRY_OR_GIVE_UP, RSSR.
;; --------------------------------------------------------------------

; ---- NRSA1 ---- from &464C
NRSA1:
               CALL RSSR                       ; 463B CD 97 4F
                                               ; to the alternate register set and back again
               EXX                             ; 463E D9
               LD L,&FF                        ; 463F 2E FF  so the first INC L wraps to zero and takes the NRS22 path
               LD D,&40                        ; 4641 16 40
                                               ; to the alternate register set and back again
               EXX                             ; 4643 D9
               PUSH DE                         ; 4644 D5
               CALL NRDDATA                    ; 4645 CD 4E 46
               POP DE                          ; 4648 D1
               CALL RETRY_OR_GIVE_UP           ; 4649 CD C6 46
               JR NRSA1                        ; 464C 18 ED

;; --------------------------------------------------------------------
;; NRDDATA -- &464E to &465F
;;
;; Takes:     C, DE, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JR
;;
;; ? drives IN A,(&00).
;; --------------------------------------------------------------------

; ---- NRDDATA ---- from &4645
NRDDATA:
               LD A,(DSC)                      ; 464E 3A 10 41  STATUS PORT
                                               ; self-modifying: patches the operand of the IN at &4666
               LD (TGT1+1),A                   ; 4651 32 67 46  patches the port of the IN at &4666
                                               ; self-modifying: patches the operand of the IN at &4676
               LD (NRSA3+1),A                  ; 4654 32 77 46  patches the port of the IN at &4676
               ADD A,DISKCTL_DATA_OFS          ; 4657 C6 03
                                               ; self-modifying: patches the operand of the IN at &466B
               LD (NRSA2+1),A                  ; 4659 32 6C 46  patches the port of the IN at &466B
               LD B,&02                        ; 465C 06 02  MASK FOR BIT 1
               JR NRSA3                        ; 465E 18 16

;; --------------------------------------------------------------------
;; NRS22 -- &4660 to &4664
;;
;; Takes:     A, D
;; Leaves:    A, F, H
;; --------------------------------------------------------------------

; ---- NRS22 ---- from &4671 when L wraps to 0
NRS22:
               LD H,D                          ; 4660 62  NSAM MSB
               AND A                           ; 4661 A7  Z IF DIR ENTRY IS ERASED OR UNUSED
               JR NZ,NRS25                     ; 4662 20 01
               LD H,A                          ; 4664 67  DUMP DATA TO ROM

;; --------------------------------------------------------------------
;; NRS25 -- &4665 to &4665
;;
;; Takes:     BC, DE, HL
;; Leaves:    BC, DE, HL
;; --------------------------------------------------------------------

; ---- NRS25 ---- from &4662 when A <> 0
NRS25:
                                               ; to the alternate register set and back again
               EXX                             ; 4665 D9

;; --------------------------------------------------------------------
;; TGT1 -- &4666 to &466A
;;
;; Takes:     B
;; Leaves:    A, F
;;
;; ? drives IN A,(&00); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

TGT1:
               IN A,(&00)                      ; 4666 DB 00  the port is written here at run time, from &4651
               AND B                           ; 4668 A0
               JR Z,NRSA3                      ; 4669 28 0B  JR IF NO BYTE IS READY TO READ

;; --------------------------------------------------------------------
;; NRSA2 -- &466B to &4675
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL
;;
;; ? drives IN A,(&00); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- NRSA2 ---- from &467D
NRSA2:
               IN A,(&00)                      ; 466B DB 00  the port is written here at run time, from &4659
               LD (HL),A                       ; 466D 77
               INC HL                          ; 466E 23
                                               ; to the alternate register set and back again
               EXX                             ; 466F D9
               INC L                           ; 4670 2C
               JR Z,NRS22                      ; 4671 28 ED  JR IF START OF DIR ENTRY
               OR (HL)                         ; 4673 B6
               LD (HL),A                       ; 4674 77
                                               ; to the alternate register set and back again
               EXX                             ; 4675 D9

;; --------------------------------------------------------------------
;; NRSA3 -- &4676 to &467E
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JR
;;
;; ? drives IN A,(&00).
;; --------------------------------------------------------------------

; ---- NRSA3 ---- from &465E, &4669 when no bit of B is set, &467B when bit 0 was clear
NRSA3:
               IN A,(&00)                      ; 4676 DB 00  the port is written here at run time, from &4654
               RRCA                            ; 4678 0F
               RET NC                          ; 4679 D0  RET IF READ SECTOR CMD FINISHED
               RRA                             ; 467A 1F
               JR NC,NRSA3                     ; 467B 30 F9  JR IF NO BYTE IS READY TO READ
               JR NRSA2                        ; 467D 18 EC

