;; --------------------------------------------------------------------
;; SEEKD -- &4742 to &4749
;;
;; Takes:     E
;; Leaves:    A, F, BC
;;
;; ? drives OUT (C),E; calls SELD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SEEKD ---- from &4733 when A <> &04, &4736
SEEKD:
               CALL SELD                       ; 4742 CD 2F 48
               INC A                           ; 4745 3C
               INC A                           ; 4746 3C
               LD C,A                          ; 4747 4F  SECTOR PORT
               OUT (C),E                       ; 4748 ED 59

;; --------------------------------------------------------------------
;; CTA2 -- &474A to &475D
;;
;; Takes:     C, D, HL
;; Leaves:    A, F, BC, HL
;;
;; ? drives IN A,(C); calls TRCKP, BUSY, BITF6; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CTA2 ---- from &4779
CTA2:
               LD A,D                          ; 474A 7A
               AND &7F                         ; 474B E6 7F
               LD B,A                          ; 474D 47
               CALL BUSY                       ; 474E CD 6D 45
               CALL TRCKP                      ; 4751 CD 21 45
               IN A,(C)                        ; 4754 ED 78
               CP B                            ; 4756 B8
               RET Z                           ; 4757 C8
               PUSH AF                         ; 4758 F5
               CALL BITF6                      ; 4759 CD 3A 51
               JR Z,CTA3                       ; 475C 28 14  JR IF NOT LOAD/SAVE BLOCK

;; --------------------------------------------------------------------
;; CTA25 -- &475E to &4771
;;
;; Takes:     nothing in registers
;; Leaves:    A, F
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

CTA25:
               LD A,(SVHL+1)                   ; 475E 3A 06 7C
               CP &C0                          ; 4761 FE C0
               JR C,CTA3                       ; 4763 38 0D
               RES 6,A                         ; 4765 CB B7  &C000 -> &8000
               LD (SVHL+1),A                   ; 4767 32 06 7C
               IN A,(HMPR)                     ; 476A DB FB
               INC A                           ; 476C 3C
               LD (PORT1),A                    ; 476D 32 2E 41
               OUT (HMPR),A                    ; 4770 D3 FB

;; --------------------------------------------------------------------
;; CTA3 -- &4772 to &477A
;;
;; Takes:     BC, D, HL
;; Leaves:    A, F, BC, HL
;; Ends:      JR
;;
;; ? drives IN A,(C), IN A,(HMPR); calls TRCKP, BUSY, STEP_HEAD_OUT, STEP_HEAD_IN.
;; --------------------------------------------------------------------

; ---- CTA3 ---- from &475C, &4763 when A < &C0
CTA3:
               POP AF                          ; 4772 F1
               CALL NC,STEP_HEAD_OUT           ; 4773 D4 7B 47
               CALL C,STEP_HEAD_IN             ; 4776 DC 7F 47
               JR CTA2                         ; 4779 18 CF

;; --------------------------------------------------------------------
;; STEP_HEAD_OUT -- &477B to &477E
;;
;; Takes:     A, BC, HL
;; Leaves:    A, F, BC
;; Preserves: HL (saved and restored)
;; Ends:      JR
;;
;; ? calls WAIT_DC_READY_BEFORE_CMD, STEP.
;; --------------------------------------------------------------------

; ---- STEP_HEAD_OUT ---- from &46E6, &46E9, &4773, &47C2
STEP_HEAD_OUT:
               LD C,STEP_OUT_CMD               ; 477B 0E 7B
               JR STEP_HEAD_OUT_1              ; 477D 18 02

;; --------------------------------------------------------------------
;; STEP_HEAD_IN -- &477F to &4780
;;
;; Takes:     nothing in registers
;; Leaves:    C
;;
;; Shown for this routine in disasm/:
;;
;;     One step of the head, either way: the direction is the only
;;     difference and both fall into the same code, which issues the command
;;     and then consults V42BB -- the double-step setting the manual calls
;;     DBSTP, "can be POKEd to a non-zero value to cause double stepping of
;;     the drive head ... useful when reading 40-track disks" -- and repeats
;;     the step when it is set.
;; --------------------------------------------------------------------

; ---- STEP_HEAD_IN ---- from &46E3, &46EC, &471E, &4776, &54A8, &5522, &558A
STEP_HEAD_IN:
               LD C,STEP_IN_CMD                ; 477F 0E 5B

;; --------------------------------------------------------------------
;; STEP_HEAD_OUT_1 -- &4781 to &478C
;;
;; Takes:     A, BC
;; Leaves:    A, F, C
;; Preserves: B (saved and restored)
;;
;; ? calls STEP; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- STEP_HEAD_OUT_1 ---- from &477D
STEP_HEAD_OUT_1:
               PUSH BC                         ; 4781 C5
               CALL STEP                       ; 4782 CD 8D 47
               POP BC                          ; 4785 C1
               LD A,(V42BB)                    ; 4786 3A BB 42
               AND A                           ; 4789 A7
               RET Z                           ; 478A C8
               RES 4,C                         ; 478B CB A1

;; --------------------------------------------------------------------
;; STEP -- &478D to &478F
;;
;; Takes:     A, BC
;; Leaves:    A, F
;;
;; ? calls WAIT_DC_READY_BEFORE_CMD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- STEP ---- from &4782
STEP:
               CALL WAIT_DC_READY_BEFORE_CMD   ; 478D CD 58 45

;; --------------------------------------------------------------------
;; STPDEL -- &4790 to &479B
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;;
;; Shown for this routine in disasm/:
;;
;;     STEP DELAY ROUTINE
;;      The delay comes from STPRAT or STPRT2 according to which drive is selected, so a slower drive can be given more
;;      time by poking the DOS variables. Zero means no delay at all.
;; --------------------------------------------------------------------

STPDEL:
               PUSH HL                         ; 4790 E5
               LD HL,STPRAT                    ; 4791 21 23 42
               LD A,(DSC)                      ; 4794 3A 10 41
               BIT 4,A                         ; 4797 CB 67  set for drive 2
               JR Z,STPD1                      ; 4799 28 01
               INC HL                          ; 479B 23

;; --------------------------------------------------------------------
;; STPD1 -- &479C to &479E
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; --------------------------------------------------------------------

; ---- STPD1 ---- from &4799 when bit 4 of A clear
STPD1:
               LD A,(HL)                       ; 479C 7E
               POP HL                          ; 479D E1
               AND A                           ; 479E A7

