;; STPD4 -- &47A4 to &47AC
;;
;; Takes:     BC
;; Leaves:    A, F, BC
;; Ends:      JR
;; --------------------------------------------------------------------

; ---- STPD4 ---- from &47A7
STPD4:
               DEC BC                          ; 47A4 0B
               LD A,B                          ; 47A5 78
               OR C                            ; 47A6 B1
               JR NZ,STPD4                     ; 47A7 20 FB
               POP AF                          ; 47A9 F1
               DEC A                           ; 47AA 3D
               JR STPD2                        ; 47AB 18 F2

;; --------------------------------------------------------------------
