;; --------------------------------------------------------------------
;; TFIHO -- &47C7 to &47D0
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC
;;
;; ? calls WRITE_DRIVE_CMD_AND_DELAY, SELD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      TFIHO -- wait for the index hole to be seen both present and absent, which can only happen if the disk is
;;      turning.
;;      H counts the attempts, so a stopped disk times out rather than hanging.
;;
;;     TEST FOR INDEX HOLE
;;     EXIT: NZ=OK, Z=TIMED OUT, NO HOLE
;; --------------------------------------------------------------------

; ---- TFIHO ---- from &47B4, &7B78
TFIHO:
               CALL SELD                       ; 47C7 CD 2F 48
               LD C,FORCE_INTERRUPT_CMD        ; 47CA 0E D0  force interrupt, terminating anything in progress
               CALL WRITE_DRIVE_CMD_AND_DELAY  ; 47CC CD 5B 45  RESET DISC CHIP
               LD B,&00                        ; 47CF 06 00

;; --------------------------------------------------------------------
;; TFIHL -- &47D1 to &47D4
;;
;; Takes:     B
;; Leaves:    B, H
;; --------------------------------------------------------------------

; ---- TFIHL ---- from &47D1 when B is not 0 yet
TFIHL:
               DJNZ TFIHL                      ; 47D1 10 FE
               LD H,&80                        ; 47D3 26 80  LOOPS BEFORE TIME-OUT

