;; --------------------------------------------------------------------
;; SVBS1 -- &4A67 to &4A6C
;;
;; Takes:     BC
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- SVBS1 ---- from &4A71, &7640
SVBS1:
               LD A,B                          ; 4A67 78
               SUB &02                         ; 4A68 D6 02
