;; --------------------------------------------------------------------
;; SVBS2 -- &4A6D to &4A72
;;
;; Takes:     BC, HL
;; Leaves:    A, F, BC, HL
;; Ends:      JR
;; --------------------------------------------------------------------

SVBS2:
               LD (HL),&00                     ; 4A6D 36 00  PAD WITH ZEROS
