; ---- PFNM0 ---- from &5A2B, &5A7D, &5BA6
PFNM0:
               PUSH HL                         ; 4B0E E5
               LD BC,&0A0A                     ; 4B0F 01 0A 0A

;; --------------------------------------------------------------------
;; PFNM1 -- &4B12 to &4B20
;;
;; Takes:     B, HL
;; Leaves:    A, F
