;; --------------------------------------------------------------------
;; FDH5_1 -- &4C2D to &4C52
;;
;; Takes:     DE, HL, IX
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls PFNME, POINT, PNUM3, SPC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FDH5_1 ---- from &4C10
FDH5_1:
               CALL PFNME                      ; 4C2D CD 09 4B  PRINT FILE NAME FOR DIR 1/2
               PUSH DE                         ; 4C30 D5
               CALL POINT                      ; 4C31 CD AC 4F
               LD A,(HL)                       ; 4C34 7E
               AND &1F                         ; 4C35 E6 1F
               CP &15                          ; 4C37 FE 15
               JR Z,FDH85                      ; 4C39 28 1C  JR IF DIR
               PUSH AF                         ; 4C3B F5
               LD A,&20                        ; 4C3C 3E 20
               LD BC,(DOSBUF)                  ; 4C3E ED 4B 00 7C  SECTORS USED
               LD HL,&03E7                     ; 4C42 21 E7 03
               AND A                           ; 4C45 A7
               SBC HL,BC                       ; 4C46 ED 42  CY IF >999 SECTS USED
               LD H,B                          ; 4C48 60
               LD L,C                          ; 4C49 69
               JR C,FDH84                      ; 4C4A 38 07
               CALL PNUM3                      ; 4C4C CD 2F 57
               CALL SPC                        ; 4C4F CD 64 57
               AND A                           ; 4C52 A7

;; --------------------------------------------------------------------
;; FDH84 -- &4C53 to &4C56
