;; --------------------------------------------------------------------
;; FDH9 -- &4C5D to &4C79
;;
;; Takes:     HL
;; Leaves:    A, F, BC, HL
;;
;; Shown for this routine in disasm/:
;;
;;     TEST FOR SPECIFIC FILE NAME
;;      Looking a file up rather than listing. A subdirectory's tag is noted on the way past, so MAXT ends up holding
;;      the
;;      highest in use.
;; --------------------------------------------------------------------

; ---- FDH9 ---- from &4B95 when no bit of &06 is set
FDH9:
               LD A,(DCHAN+4)                  ; 4C5D 3A 04 7C
               AND &18                         ; 4C60 E6 18
               JR Z,FDHd                       ; 4C62 28 28  JR IF NEITHER BIT 3 NOR 4 ARE SET
               LD A,(HL)                       ; 4C64 7E
               AND &1F                         ; 4C65 E6 1F
               CP DFT                          ; 4C67 FE 15  DIR
               JR NZ,FDH92                     ; 4C69 20 11
               LD BC,DIRT                      ; 4C6B 01 FA 00
               ADD HL,BC                       ; 4C6E 09  PT TO DIR TAG
               LD A,(MAXT)                     ; 4C6F 3A 35 42  CURRENT MAX
               CP (HL)                         ; 4C72 BE  CP TAG OF THIS DIR
               JR NC,FDH91                     ; 4C73 30 05  JR IF NO NEW MAX TAG
               LD A,(HL)                       ; 4C75 7E
               LD (MAXT),A                     ; 4C76 32 35 42
               AND A                           ; 4C79 A7

;; --------------------------------------------------------------------
;; FDH91 -- &4C7A to &4C7B
;;
;; Takes:     BC, HL
;; Leaves:    F, HL
;; --------------------------------------------------------------------

; ---- FDH91 ---- from &4C73 when A >= (HL)
FDH91:
               SBC HL,BC                       ; 4C7A ED 42  PT TO DIR TAG FOR FILE

;; --------------------------------------------------------------------
;; FDH92 -- &4C7C to &4C87
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; --------------------------------------------------------------------

; ---- FDH92 ---- from &4C69 when A <> DFT
FDH92:
               INC H                           ; 4C7C 24
               DEC HL                          ; 4C7D 2B
               DEC HL                          ; 4C7E 2B
               LD A,(CDIRT)                    ; 4C7F 3A 31 42
               CP (HL)                         ; 4C82 BE
               JR Z,FDH95                      ; 4C83 28 03  JR IF RIGHT DIR
               INC A                           ; 4C85 3C
               JR NZ,FDHd                      ; 4C86 20 04  JR UNLESS 0FFH "ANY" DIR

;; --------------------------------------------------------------------
;; FDH95 -- &4C88 to &4C8B
;;
;; Takes:     DE, IX
;; Leaves:    F, B, DE
;;
;; ? calls CKNAM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FDH95 ---- from &4C83 when A = (HL)
FDH95:
               CALL CKNAM                      ; 4C88 CD C2 4C
               RET Z                           ; 4C8B C8

;; --------------------------------------------------------------------
;; FDHd -- &4C8C to &4C9A
;;
;; Takes:     DE, HL, IX
;; Leaves:    A, F, BC, HL, IX
;; Preserves: DE (saved and restored)
;; Ends:      JP
;;
;; ? calls CKNAM, CLEAR_TRANSFER_COUNT, POINT.
;;
;; Shown for this routine in disasm/:
;;
;;     CALCULATE NEXT DIRECTORY ENTRY
;;      Two entries to a sector, ten sectors to a track, DTKS tracks. Sector 1 of track 4 is skipped because that is
;;      where
;;      the DOS file itself begins.
;; --------------------------------------------------------------------

; ---- FDHd ---- from &4BC2 when A <> B, &4BFA, &4C5B, &4C62 when no bit of &18 is set, &4C86 when A is not 0, &4CBE
; when A <> 0
FDHd:
               LD A,(DCHAN+RPTH)               ; 4C8C 3A 0E 7C
               DEC A                           ; 4C8F 3D
               JR Z,FDHe                       ; 4C90 28 09  JR IF WE HAVE JUST DONE SECOND DIR
               CALL CLEAR_TRANSFER_COUNT       ; 4C92 CD 8E 4F
               INC (IX+&0E)                    ; 4C95 DD 34 0E  NEXT ENTRY
               JP FDH1_1                       ; 4C98 C3 88 4B

;; --------------------------------------------------------------------
;; FDHe -- &4C9B to &4CA7
;;
;; Takes:     DE
;; Leaves:    A, F, DE
;;
;; ? calls ISECT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FDHe ---- from &4C90 when A reaches 0
FDHe:
               CALL ISECT                      ; 4C9B CD 24 56  NEXT SECTOR
               JP NZ,FDH1                      ; 4C9E C2 85 4B  JP IF NOT LAST SECT IN TRACK
               INC D                           ; 4CA1 14  INC TRACK
               LD A,D                          ; 4CA2 7A
               CP &04                          ; 4CA3 FE 04
               JR NZ,FDHE2                     ; 4CA5 20 01
               INC E                           ; 4CA7 1C  SECT=2 IF TRACK=4 (SKIP DOS)

;; --------------------------------------------------------------------
;; FDHE2 -- &4CA8 to &4CB0
;;
;; Takes:     D
;; Leaves:    A, F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- FDHE2 ---- from &4CA5 when A <> &04
FDHE2:
               LD A,(DTKS)                     ; 4CA8 3A 30 42
               CP D                            ; 4CAB BA
               JP NZ,FDH1                      ; 4CAC C2 85 4B
               AND A                           ; 4CAF A7  NZ
               RET                             ; 4CB0 C9

;; --------------------------------------------------------------------
;; FDHF -- &4CB1 to &4CC1
;;
;; Takes:     DE, HL, IX
;; Leaves:    A, F, HL
;; Ends:      RET
;;
;; ? calls CLAIM_FREE_SLOT.
;;
;; Shown for this routine in disasm/:
;;
;;     MasterBASIC changed this routine: only 11 of the 18
;;     instructions stock MasterDOS 2.3 has in FDHF survive
;;     here, so that version's description of it has been
;;     left out rather than carried across.  Compare
;;     ref/masterdos/annotated-src/masterdos23.asm.
;; --------------------------------------------------------------------

; ---- FDHF ---- from &4B8D when A = 0
FDHF:
               CALL CLAIM_FREE_SLOT            ; 4CB1 CD E0 4F
               LD A,(IX+&04)                   ; 4CB4 DD 7E 04
               CPL                             ; 4CB7 2F
               BIT 6,A                         ; 4CB8 CB 77
               RET Z                           ; 4CBA C8  RET IF GOT WHAT WE WANTED
               INC HL                          ; 4CBB 23
               LD A,(HL)                       ; 4CBC 7E
               AND A                           ; 4CBD A7  **
               JR NZ,FDHd                      ; 4CBE 20 CC  JR IF DIR ENTRY HAS BEEN USED AT
               INC A                           ; 4CC0 3C  NZ
               RET                             ; 4CC1 C9  USED PART OF DIR DEALT WITH

;; --------------------------------------------------------------------
;; CKNAM -- &4CC2 to &4CD0
;;
;; Takes:     DE, IX
;; Leaves:    F, B, DE
;;
;; ? calls POINT; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      CKNAM -- compare the name in the entry with the one in NSTR1
;;
;;      Case is ignored by masking bit 5. With bit 3 of the mode set, "?" matches any single character and "*" matches
;;      everything up to a "." -- so "*.bak" works and a bare "*" matches every file.
;;
;;      Exit:   Z if the names match
;;
;;     CHECK FILE NAME IN DIR
;;     EXIT: Z IF MATCHED
;; --------------------------------------------------------------------

; ---- CKNAM ---- from &4BD6, &4C88, &5EAA
CKNAM:
               PUSH DE                         ; 4CC2 D5
               CALL POINT                      ; 4CC3 CD AC 4F
               LD B,&0B                        ; 4CC6 06 0B
               LD DE,NSTR1                     ; 4CC8 11 3A 41
               BIT 3,(IX+&04)                  ; 4CCB DD CB 04 5E
               JR Z,CKNM1_LOOP                 ; 4CCF 28 0E  JR IF TYPE IRREL - SKIP TYPE

;; --------------------------------------------------------------------
;; CKNM1 -- &4CD1 to &4CDE
;;
;; Takes:     DE, HL
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- CKNM1 ---- from &4CE1 when B is not 0 yet
CKNM1:
               LD A,(DE)                       ; 4CD1 1A
               CP &2A                          ; 4CD2 FE 2A
               JR Z,CKNM1_1                    ; 4CD4 28 10  MATCH ANY LEN IF "*"
               CP &3F                          ; 4CD6 FE 3F
               JR Z,CKNM1_LOOP                 ; 4CD8 28 05  MATCH ANY CHAR IF "?"
               XOR (HL)                        ; 4CDA AE
               AND &DF                         ; 4CDB E6 DF
               JR NZ,CKNM1_DONE                ; 4CDD 20 05

;; --------------------------------------------------------------------
;; CKNM1_LOOP -- &4CDF to &4CE2
;;
;; Takes:     B, DE, HL
;; Leaves:    B, DE, HL
;; --------------------------------------------------------------------

; ---- CKNM1_LOOP ---- from &4CCF when bit 3 of (IX+&04) clear, &4CD8 when A = &3F, &4CF3 when A = &2E
CKNM1_LOOP:
               INC DE                          ; 4CDF 13
               INC HL                          ; 4CE0 23
               DJNZ CKNM1                      ; 4CE1 10 EE

;; --------------------------------------------------------------------
;; CKNM1_LOOP2 -- &4CE3 to &4CE3
;;
;; Takes:     A
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- CKNM1_LOOP2 ---- from &4CE7 when B reaches 0, &4CEE when A <> &2E
CKNM1_LOOP2:
               XOR A                           ; 4CE3 AF  MATCH=Z

;; --------------------------------------------------------------------
;; CKNM1_DONE -- &4CE4 to &4CE5
;;
;; Takes:     nothing in registers
;; Leaves:    DE
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CKNM1_DONE ---- from &4CDD when a bit of &DF is set
CKNM1_DONE:
               POP DE                          ; 4CE4 D1
               RET                             ; 4CE5 C9

;; --------------------------------------------------------------------
;; CKNM1_1 -- &4CE6 to &4CEF
;;
;; Takes:     B, DE, HL
;; Leaves:    A, F, B, DE, HL
;; --------------------------------------------------------------------

; ---- CKNM1_1 ---- from &4CD4 when A = &2A
CKNM1_1:
               DEC B                           ; 4CE6 05
               JR Z,CKNM1_LOOP2                ; 4CE7 28 FA
               INC DE                          ; 4CE9 13
               INC HL                          ; 4CEA 23
               LD A,(DE)                       ; 4CEB 1A
               CP &2E                          ; 4CEC FE 2E
               JR NZ,CKNM1_LOOP2               ; 4CEE 20 F3  E.G. "*" OR "A*" MATCHES ANYTHING

;; --------------------------------------------------------------------
;; CKNM1_LOOP3 -- &4CF0 to &4CF9
;;
;; Takes:     B, HL
;; Leaves:    A, F, B, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CKNM1_LOOP3 ---- from &4CF6 when B is not 0 yet
CKNM1_LOOP3:
               LD A,(HL)                       ; 4CF0 7E
               CP &2E                          ; 4CF1 FE 2E
               JR Z,CKNM1_LOOP                 ; 4CF3 28 EA  IF MATCHING "." FOUND,
               INC HL                          ; 4CF5 23
               DJNZ CKNM1_LOOP3                ; 4CF6 10 F8
               POP DE                          ; 4CF8 D1
               RET                             ; 4CF9 C9  NO MATCH

;; --------------------------------------------------------------------
;; CLSAM -- &4CFA to &4CFF
;;
;; Takes:     A
;; Leaves:    A, F, B, HL
;; --------------------------------------------------------------------

; ---- CLSAM ---- from &4D31 when A = 0, &69E1
CLSAM:
               XOR A                           ; 4CFA AF
               LD HL,SAM                       ; 4CFB 21 0F 40
               LD B,&C3                        ; 4CFE 06 C3

;; --------------------------------------------------------------------
;; CLSML -- &4D00 to &4D04
;;
;; Takes:     A, B, HL
;; Leaves:    B, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CLSML ---- from &4D02 when B is not 0 yet
CLSML:
               LD (HL),A                       ; 4D00 77
               INC HL                          ; 4D01 23
               DJNZ CLSML                      ; 4D02 10 FC
               RET                             ; 4D04 C9

;; --------------------------------------------------------------------
;; ROFSM -- &4D05 to &4D21
;;
;; Takes:     IX
;; Leaves:    A, F, BC, HL
;;
;; ? calls OFSM, GRWA; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      ROFSM / OFSM -- open a file for writing
;;
;;      Scanning the directory rebuilds the free-sector map and, if a file of the same name is found, offers to
;;      overwrite
;;      it. The map already includes the old file's sectors by then, so rather than rescanning, DBAML XORs the old
;;      file's
;;      own bitmap out of the global one -- the bits it contributed are exactly the ones to release.
;;
;;      SAMCNT counts long-term open files. While any is open the map must not be cleared, because it describes space
;;      that
;;      those files are still claiming.
;;
;;      Exit:   NC and the file is open; CY if the user declined to overwrite
;;
;;     RND/SERIAL OPEN FILE SECTOR ADDRESS MAP - INC SAMCNT
;;     OF LONG-TERM OPEN FILES (CHANS BUFFERS)
;; --------------------------------------------------------------------

; ---- ROFSM ---- from &6CA9, &6CF5
ROFSM:
               CALL OFSM                       ; 4D05 CD 2B 4D
               LD A,(SAMCNT)                   ; 4D08 3A 34 42
               INC A                           ; 4D0B 3C
               LD (SAMCNT),A                   ; 4D0C 32 34 42
               DEC A                           ; 4D0F 3D
               JR NZ,ROFSM_DONE                ; 4D10 20 10  JR IF NOT FIRST FILE
               CALL GRWA                       ; 4D12 CD 3C 74  GET CUR. RAND WORD ADDR IN HL
               LD C,(HL)                       ; 4D15 4E
               INC HL                          ; 4D16 23
               LD B,(HL)                       ; 4D17 46
               LD (SAMRN),BC                   ; 4D18 ED 43 6D 42  RND NO. OF DISC USED FOR SAM
               LD A,(DRIVE)                    ; 4D1C 3A 0B 7C
               LD (TDVAR),A                    ; 4D1F 32 6F 42

;; --------------------------------------------------------------------
;; ROFSM_DONE -- &4D22 to &4D23
;;
;; Takes:     A
;; Leaves:    A, F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- ROFSM_DONE ---- from &4D10 when A is not 0 yet
ROFSM_DONE:
               XOR A                           ; 4D22 AF  NC - OK
               RET                             ; 4D23 C9

;; --------------------------------------------------------------------
;; L4D24 -- &4D24 to &4D27
;;
;; Takes:     A, HL
;; Leaves:    A
;;
;; ? calls CKDRV; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

               LD (HL),A                       ; 4D24 77
               CALL CKDRV                      ; 4D25 CD 07 48

;; --------------------------------------------------------------------
;; GOFSM -- &4D28 to &4D2A
;;
;; Takes:     nothing in registers
;; Leaves:    HL, IX
;;
;; ? calls RESET_BUFFER_POINTERS; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- GOFSM ---- from &64EB, &6626, &7211
GOFSM:
               CALL RESET_BUFFER_POINTERS      ; 4D28 CD 84 4F

;; --------------------------------------------------------------------
;; OFSM -- &4D2B to &4D2C
;;
;; Takes:     IX
;; Leaves:    registers unchanged
;; --------------------------------------------------------------------

; ---- OFSM ---- from &4D05, &541E, &5A6F
OFSM:
               PUSH IX                         ; 4D2B DD E5

;; --------------------------------------------------------------------
;; OFSM_1 -- &4D2D to &4D3A
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls FDHR, CLSAM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OFSM_1 ---- from MB &5256
OFSM_1:
               LD A,(SAMCNT)                   ; 4D2D 3A 34 42
               AND A                           ; 4D30 A7
               CALL Z,CLSAM                    ; 4D31 CC FA 4C  NO CLEAR IF OPEN-TYPE FILE(S) HAS
               LD A,&30                        ; 4D34 3E 30  BIT 5=CREATE SAM,BIT 4=TEST FOR NAME
               CALL FDHR                       ; 4D36 CD 31 4B
               JR NZ,OFM4                      ; 4D39 20 5B  JR IF NAME NOT FOUND

;; --------------------------------------------------------------------
;; OFSM_2 -- &4D3B to &4D6A
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, B, HL
;;
;; ? reaches the ROM through OVERF; calls POINT, NRRD, CALL_ROM_66CB; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OFSM_2 ---- from &4D94
OFSM_2:
               PUSH DE                         ; 4D3B D5
               CALL CALL_ROM_66CB              ; 4D3C CD 70 5E
               JP NZ,REP28                     ; 4D3F C2 8C 51  "FILE NAME USED" IF "OPEN DIR"
               CALL POINT                      ; 4D42 CD AC 4F
               AND &1F                         ; 4D45 E6 1F
               CP &15                          ; 4D47 FE 15
               JP Z,REP28                      ; 4D49 CA 8C 51  OR IF DIR FILE
                                               ; read the ROM variable OVERF -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 4D4C CD 5E 50
               DEFW OVERF                      ; 4D4F B9 5B
               AND A                           ; 4D51 A7
               JR Z,OFSM_4                     ; 4D52 28 1A  NO "OVERWRITE? Y/N" IF SAVE OVER
               PUSH HL                         ; 4D54 E5
               CALL HK_SKSAFE                  ; 4D55 CD 23 47  IN CASE "N"
               POP HL                          ; 4D58 E1
               BIT 6,(HL)                      ; 4D59 CB 76
               JP NZ,REP33_2                   ; 4D5B C2 9E 51  "PROTECTED FILE"
               CALL PMO5                       ; 4D5E CD FA 57  "OVERWRITE"
               CALL FNM7K                      ; 4D61 CD 17 59  FILE NAME, "Y/N", KEY
               JR Z,OFSM_3                     ; 4D64 28 05  JR IF "Y"
               POP DE                          ; 4D66 D1
               POP IX                          ; 4D67 DD E1
               SCF                             ; 4D69 37  SIGNAL ERROR
               RET                             ; 4D6A C9  AND ABORT

;; --------------------------------------------------------------------
;; OFSM_3 -- &4D6B to &4D6D
;;
;; Takes:     B
;; Leaves:    A, F, C
;;
;; ? calls DWAIT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OFSM_3 ---- from &4D64
OFSM_3:
               CALL DWAIT                      ; 4D6B CD 64 45  IN CASE STOPPED

;; --------------------------------------------------------------------
;; OFSM_4 -- &4D6E to &4D7E
;;
;; Takes:     HL
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls POINT, DDEL; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OFSM_4 ---- from &4D52 when A = 0
OFSM_4:
               CALL DDEL                       ; 4D6E CD 5F 65
               CALL POINT                      ; 4D71 CD AC 4F
               LD (HL),&00                     ; 4D74 36 00
               LD BC,&000F                     ; 4D76 01 0F 00
               ADD HL,BC                       ; 4D79 09  POINT TO SAM OF FILE IN BUFFER
               LD DE,SAM                       ; 4D7A 11 0F 40  POINT TO BAM FOR DISC SO FAR
               LD B,&C3                        ; 4D7D 06 C3

;; --------------------------------------------------------------------
;; DBAML -- &4D7F to &4D95
;;
;; Takes:     B, DE, HL
;; Leaves:    A, F, B, DE, HL, IX
;;
;; ? calls WSAD, FDH1, CLAIM_FREE_SLOT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- DBAML ---- from &4D84 when B is not 0 yet
DBAML:
               LD A,(DE)                       ; 4D7F 1A
               XOR (HL)                        ; 4D80 AE  REVERSE BITS ORED IN BY FDHR
               LD (DE),A                       ; 4D81 12  UPDATE BAM TO TAKE ACCOUNT OF
               INC E                           ; 4D82 1C  ERASURE
               INC HL                          ; 4D83 23
               DJNZ DBAML                      ; 4D84 10 F9
               POP DE                          ; 4D86 D1
               CALL CLAIM_FREE_SLOT            ; 4D87 CD E0 4F
               CALL WSAD                       ; 4D8A CD 86 45  WRITE DIR SECT TO DISC
               LD IX,DOSBUF                    ; 4D8D DD 21 00 7C
               CALL FDH1                       ; 4D91 CD 85 4B  COMPLETE BAM BY SCANNING REST OF
               JR Z,OFSM_2                     ; 4D94 28 A5  JR IF SECOND OR OTHER COPY...

;; --------------------------------------------------------------------
;; OFM4 -- &4D96 to &4D9B
;;
;; Takes:     nothing in registers
;; Leaves:    B, IX
;;
;; Shown for this routine in disasm/:
;;
;;     SHOLD NEVER BE!
;;
;;     CLEAR AREA FOR NEW DIR ENTRY IN BUFFER
;; --------------------------------------------------------------------

; ---- OFM4 ---- from &4D39
OFM4:
               POP IX                          ; 4D96 DD E1
               PUSH IX                         ; 4D98 DD E5
               LD B,&00                        ; 4D9A 06 00  256 iterations: the whole entry image

;; --------------------------------------------------------------------
;; OFM5 -- &4D9C to &4DD6
;;
;; Takes:     B, IX
;; Leaves:    A, F, BC, DE, HL
;; Preserves: IX (saved and restored)
;; Ends:      RET
;;
;; ? calls FNFS, OFM6, CLEAR_TRANSFER_COUNT, SET_TRACK_AND_SECTOR.
;; --------------------------------------------------------------------

; ---- OFM5 ---- from &4DA2 when B is not 0 yet
OFM5:
               LD (IX+&13),&00                 ; 4D9C DD 36 13 00
               INC IX                          ; 4DA0 DD 23
               DJNZ OFM5                       ; 4DA2 10 F8
               POP IX                          ; 4DA4 DD E1
               PUSH IX                         ; 4DA6 DD E5
               LD HL,NSTR1                     ; 4DA8 21 3A 41
               LD B,&0B                        ; 4DAB 06 0B
               CALL OFM6                       ; 4DAD CD D7 4D
               POP IX                          ; 4DB0 DD E1
               PUSH IX                         ; 4DB2 DD E5
               LD BC,&00DC                     ; 4DB4 01 DC 00
               ADD IX,BC                       ; 4DB7 DD 09
               LD HL,UIFA+15                   ; 4DB9 21 8C 41
               LD B,&21                        ; 4DBC 06 21
               CALL OFM6                       ; 4DBE CD D7 4D
               POP IX                          ; 4DC1 DD E1
               CALL CALL_ROM_66CB              ; 4DC3 CD 70 5E
               CALL Z,FNFS                     ; 4DC6 CC 83 4A  AVOID FNFS IF EXISTING OPENTYPE
               CALL SET_TRACK_AND_SECTOR       ; 4DC9 CD C6 4F
               LD (IX+&20),D                   ; 4DCC DD 72 20  FIRST TRACK
               LD (IX+&21),E                   ; 4DCF DD 73 21  AND SECTOR OF FILE IN DIR
               CALL CLEAR_TRANSFER_COUNT       ; 4DD2 CD 8E 4F
               XOR A                           ; 4DD5 AF  NC=OK
               RET                             ; 4DD6 C9

;; --------------------------------------------------------------------
;; OFM6 -- &4DD7 to &4DE0
;;
;; Takes:     B, HL, IX
;; Leaves:    A, B, HL, IX
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- OFM6 ---- from &4DAD, &4DBE, &4DDE when B is not 0 yet
OFM6:
               LD A,(HL)                       ; 4DD7 7E
               LD (IX+&13),A                   ; 4DD8 DD 77 13
               INC HL                          ; 4DDB 23
               INC IX                          ; 4DDC DD 23
               DJNZ OFM6                       ; 4DDE 10 F7
               RET                             ; 4DE0 C9

;; --------------------------------------------------------------------
;; BEEP -- &4DE1 to &4DF7
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through BEEPR; calls CMR; falls into whatever follows rather than returning.
