;; --------------------------------------------------------------------
;; SCFSM -- &4DF8 to &4DFD
;;
;; Takes:     A, IX
;; Leaves:    A, F, DE
;;
;; ? calls WSAD, GET_TRACK_AND_SECTOR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      CFSM -- close the file being written
;;
;;      Writes the directory entry built up in the entry image into the slot FSLSR noted earlier, or finds one if that
;;      has
;;      become stale.
;;
;;      The first entry of the directory -- track 0, sector 1, entry 1 -- is special: it also holds the disk name, the
;;      disk's random identifying word, the directory tag and the count of extra directory tracks. Those are read from
;;      the
;;      disk and written back unchanged, so only the parts of the entry that belong to the file are replaced.
;;
;;     SPECIAL CFSM USED WHEN SEVERAL BLOCKS MAY BE WRITTEN TO SAME
;;     FILE AND LAST SECTOR NEEDS SAVING BECAUSE HSVBL USED.
;; --------------------------------------------------------------------

; ---- SCFSM ---- from &5A9D, &6549
SCFSM:
               CALL GET_TRACK_AND_SECTOR       ; 4DF8 CD BF 4F
               CALL WSAD                       ; 4DFB CD 86 45  LAST SECTOR

;; --------------------------------------------------------------------
;; CFSM -- &4DFE to &4E12
;;
;; Takes:     A, HL, IX
;; Leaves:    A, F, BC, DE, HL, IX
;; Ends:      JR
;;
;; ? calls READ_SECTOR, CFMC, POINT, NRRD.
;; --------------------------------------------------------------------

; ---- CFSM ---- from &544D, &6551, &7220
CFSM:
               PUSH IX                         ; 4DFE DD E5
               LD DE,(FSLOT)                   ; 4E00 ED 5B FC 41
               INC E                           ; 4E04 1C
               DEC E                           ; 4E05 1D
               JR Z,CLOSX                      ; 4E06 28 0B  DIR PROBABLY FULL - BUT DO A FULL
               CALL READ_SECTOR                ; 4E08 CD B7 45  READ DIR SECTOR WITH FREE SLOTS
               LD A,(FSLTE)                    ; 4E0B 3A FE 41
               LD (DCHAN+RPTH),A               ; 4E0E 32 0E 7C  PT RPT TO FREE SLOT
               JR NCF25                        ; 4E11 18 08

;; --------------------------------------------------------------------
;; CLOSX -- &4E13 to &4E1A
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls FDHR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CLOSX ---- from &4E06 when E reaches 0, &6ED5 when bit 2 of (IX+&0C) clear
CLOSX:
               LD A,&40                        ; 4E13 3E 40  FIND FREE SLOT
               CALL FDHR                       ; 4E15 CD 31 4B
               JP NZ,REP25                     ; 4E18 C2 86 51  DIRECTORY FULL

;; --------------------------------------------------------------------
;; NCF25 -- &4E1B to &4E42
;;
;; Takes:     DE, HL, IX
;; Leaves:    A, F, BC, HL, IX
;;
;; ? calls CFMC, POINT; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     UPDATE DIRECTORY
;;     JPED TO FROM CLOSP
;; --------------------------------------------------------------------

; ---- NCF25 ---- from &4E11, &6EEE
NCF25:
               CALL POINT                      ; 4E1B CD AC 4F
               LD (SVIX),IX                    ; 4E1E DD 22 07 7C
               POP IX                          ; 4E22 DD E1
               PUSH IX                         ; 4E24 DD E5
               LD A,E                          ; 4E26 7B
               DEC A                           ; 4E27 3D
               OR D                            ; 4E28 B2
               OR B                            ; 4E29 B0  OFFSET FROM 'POINT'
               LD B,&00                        ; 4E2A 06 00  B=COUNT FOR 256 BYTES
               JR NZ,NCF25_1                   ; 4E2C 20 15  JR IF NOT T0,S1,ENTRY1
               LD BC,&D20A                     ; 4E2E 01 0A D2  C=0AH
               CALL CFMC                       ; 4E31 CD 6B 4E  COPY BYTES 0-D1 FROM BUFFER
               ADD HL,BC                       ; 4E34 09  SKIP DISC NAME - KEEP AS READ FROM
               ADD IX,BC                       ; 4E35 DD 09  (BC=000AH)
               LD B,&20                        ; 4E37 06 20
               CALL CFMC                       ; 4E39 CD 6B 4E  COPY BYTES DC-FB FROM BUFFER, ONLY
               LD A,(IX+&15)                   ; 4E3C DD 7E 15  READ DIR TAG
               INC HL                          ; 4E3F 23
               INC HL                          ; 4E40 23
               LD (HL),A                       ; 4E41 77  USE DIR TAG FROM BUFFER, NOT DISC
               CP A                            ; 4E42 BF  Z

;; --------------------------------------------------------------------
;; NCF25_1 -- &4E43 to &4E57
;;
;; Takes:     B, DE, HL, IX
;; Leaves:    A, F, B, HL, IX
;;
;; ? reaches the ROM through CURCMD; calls CFMC, NRRD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- NCF25_1 ---- from &4E2C
NCF25_1:
               CALL NZ,CFMC                    ; 4E43 C4 6B 4E
               LD IX,(SVIX)                    ; 4E46 DD 2A 07 7C
                                               ; read the ROM variable CURCMD -- the word below is its address, and the
                                               ; call returns past it
