               LD (DIFA+31),A                  ; 4F33 32 CC 41
               LD (PAGE2),A                    ; 4F36 32 6D 41
               LD (DIFA+32),HL                 ; 4F39 22 CD 41
               LD (HD0D2),HL                   ; 4F3C 22 68 41
               JR GTFL8                        ; 4F3F 18 0A

