;; Leaves:    A, BC, DE, HL, IY
;;
;; ? calls CALLMB; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Hand (IX+&0E) to MasterBASIC's BYTE_TO_DECIMAL through CALLMB, so the
;;     page count can be printed as three characters.
;; --------------------------------------------------------------------

; ---- REPORT_PAGE_COUNT ---- from &4C12, &7B46
REPORT_PAGE_COUNT:
               LD A,(IX+&0E)                   ; 4FD7 DD 7E 0E
                                               ; call &4224 in the other page: LMPR is switched first, so that address
                                               ; is how the other listing numbers it
               CALL CALLMB                     ; 4FDA CD BD 42
               DEFW &4224                      ; 4FDD 24 42
               RET                             ; 4FDF C9

;; --------------------------------------------------------------------
;; CLAIM_FREE_SLOT -- &4FE0 to &4FEF
;;
;; Takes:     DE
;; Leaves:    A, F
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Take FSLOT if nothing has it -- a non-zero value returns at once --
;;     and record the entry beside it in FSLTE.
;; --------------------------------------------------------------------

; ---- CLAIM_FREE_SLOT ---- from &4CB1, &4D87
CLAIM_FREE_SLOT:
               LD A,(FSLOT)                    ; 4FE0 3A FC 41
               AND A                           ; 4FE3 A7
               RET NZ                          ; 4FE4 C0
               LD (FSLOT),DE                   ; 4FE5 ED 53 FC 41
               LD A,(V7C0E)                    ; 4FE9 3A 0E 7C
               LD (FSLTE),A                    ; 4FEC 32 FE 41
               RET                             ; 4FEF C9

;; --------------------------------------------------------------------
;; CIEL -- &4FF0 to &4FF2
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GCHR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      PART D1 -- The ROM interface, the flag byte, errors, and the NMI snapshot
;;
;;        CIEL / CFSO / CEOS    statement parsing: end of statement, and which pass this is
;;        ENDS / RENT           finishing a command and unwinding
;;        NRRD / NRWR / RDA     reading and writing the ROM's system variables
;;        HLFG / SETF0 .. BITF7 the DOS's flag byte
;;        BCC / BCR             the border colour flashed during disk access
;;        REP4 .. DERR, ERRTBL  error reporting and the message table
;;        NMI .. SNAP8          the snapshot button
;;
;;      Reaching the system variables
;;
;;      The DOS occupies &4000-&7FFF, which is where the ROM's system variables also live, so it cannot simply read one.
;;      SAMDOS asked the ROM to do it, through the jump table entry at &0103 and a one-instruction helper. MasterDOS
;;      does
;;      the paging itself: it maps page 0 at &8000 and rewrites the address into that window by setting bit 15 and
;;      clearing bit 14, which turns &5C3B into &9C3B. RDA, RDBC and WRTBC are the result, and the author's comment
;;      records why -- "replace CALL CMR:DW NRREAD - faster".
;;
;;      Error reporting
;;
;;      The REP stubs are a chain: each loads its code into A and then skips the next two bytes with a DEFB &21, an
;;      "LD HL,nn" whose operand is the following instruction. The chain falls through to a single tail that plants the
;;      code in the byte after a CALL DERR and calls it -- so one copy of the call serves thirty-odd error codes.
;;
;;      ERRTBL is indexed by the code less 81. Many entries are a single space, because MasterDOS leaves those reports
;;      to
;;      the ROM; the ones it does supply are compressed against the ROM's own substring dictionary, whose indices are
;;      the
;;      equates just above the table. That the author could use the ROM's private compression table is a reminder that
;;      he
;;      wrote both.
;;
;;     CHECK IS IT END OF LINE
;; --------------------------------------------------------------------

; ---- CIEL ---- from &5007, &5B16, &5B1E, &5F14, &60A8, &6DAF
CIEL:
               CALL GCHR                       ; 4FF0 CD 42 50

;; --------------------------------------------------------------------
;; IS_END_OF_STATEMENT -- &4FF3 to &4FF8
;;
;; Takes:     A
;; Leaves:    F
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     Carriage return or colon, returning Z for either, which is the DOS's
;;     own copy of the test MasterBASIC spells AT_END_OF_STATEMENT.
;; --------------------------------------------------------------------

; ---- IS_END_OF_STATEMENT ---- from &6A72
IS_END_OF_STATEMENT:
               CP &0D                          ; 4FF3 FE 0D  CR
               RET Z                           ; 4FF5 C8
               CP &3A                          ; 4FF6 FE 3A  ":"
               RET                             ; 4FF8 C9

;; --------------------------------------------------------------------
;; CFSO -- &4FF9 to &5006
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, HL
;;
;; ? reaches the ROM through FLAGS; calls NRRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     CHECK FOR SYNTAX ONLY
;;      NZ when running, Z while the line's syntax is being checked. A is preserved across the call through SVA.
;; --------------------------------------------------------------------

; ---- CFSO ---- from &440B, &500C, &5F6C, &618B, &6289, &62B7, &62C8, &6A97 ...
CFSO:
               LD (SVA),A                      ; 4FF9 32 1D 41
                                               ; read the ROM variable FLAGS -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 4FFC CD 5E 50
               DEFB &3B                        ; 4FFF ;

; ---- V5000 ---- from MB &522B
V5000:
               DEFB &5C                        ; 5000 \
               AND &80                         ; 5001 E6 80
               LD A,(SVA)                      ; 5003 3A 1D 41
               RET                             ; 5006 C9

;; --------------------------------------------------------------------
;; CEOS -- &5007 to &500B
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CIEL; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     CHECK FOR END OF SYNTAX
;;      On the syntax pass this does not return to its caller at all: it falls through to ENDS, which is how every
;;      command
;;      comes to do nothing while syntax is being checked.
;; --------------------------------------------------------------------

; ---- CEOS ---- from &5963, &599D, &5B4B, &5B55, &5D59, &5E00, &5F31, &5F75 ...
CEOS:
               CALL CIEL                       ; 5007 CD F0 4F
               JR NZ,REP0HC                    ; 500A 20 2D

;; --------------------------------------------------------------------
;; ABORT -- &500C to &500F
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, HL
;;
;; ? calls CFSO; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

ABORT:
               CALL CFSO                       ; 500C CD F9 4F
               RET NZ                          ; 500F C0

;; --------------------------------------------------------------------
;; ENDS -- &5010 to &5012
;;
;; Takes:     nothing in registers
;; Leaves:    E
;;
;; Shown for this routine in disasm/:
;;
;;     END OF STATEMENT
;;      E is what the ROM reads back: 0 means the command is complete, 1 that the ROM's own load/save machinery should
;;      carry on from here.
;; --------------------------------------------------------------------

; ---- ENDS ---- from &4366, &53CC, &590A when A = &45
ENDS:
               LD E,&00                        ; 5010 1E 00  NO ACTION
               DEFB &21                        ; 5012 !  "JR+2"

;; --------------------------------------------------------------------
;; ENDSX -- &5013 to &5014
;;
;; Takes:     nothing in registers
;; Leaves:    E
;; --------------------------------------------------------------------

; ---- ENDSX ---- from &607B
ENDSX:
               LD E,&01                        ; 5013 1E 01

;; --------------------------------------------------------------------
;; END1 -- &5015 to &5024
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? reaches the ROM through XPTR+1; calls NRWR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- END1 ---- from &641D, &655C
END1:
               XOR A                           ; 5015 AF
                                               ; write the ROM variable XPTR+1
               CALL NRWR                       ; 5016 CD 74 50
               DEFW XPTR+1                     ; 5019 A4 5A
               CALL SETBORDER_BORDCR           ; 501B CD 52 51
               LD (NRFLG),A                    ; 501E 32 1F 41  RECURSE OK
                                               ; the stack is being reset, so this path does not return
               LD SP,(ENTSP)                   ; 5021 ED 7B 04 41

;; --------------------------------------------------------------------
;; RENT -- &5025 to &5029
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- RENT ---- from &4469
RENT:
               POP HL                          ; 5025 E1
               LD (ENTSP),HL                   ; 5026 22 04 41  OLD VALUE
               RET                             ; 5029 C9

;; --------------------------------------------------------------------
;; BRKTST -- &502A to &5030
;;
;; Takes:     nothing in registers
;; Leaves:    A, F
;;
;; ? drives IN A,(STAT); falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     TEST FOR BREAK ROUTINE
;;      Reads the keyboard row selected by putting &F7 on the high address lines and tests the bit ESC occupies. Called
;;      from inside the drive polling loops, so a disk that never becomes ready can still be escaped from.
