                                               ; read the ROM variable CHADP -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 51E8 CD 5E 50
               DEFW CHADP                      ; 51EB 96 5A
                                               ; write the ROM variable XPTRP
               CALL NRWR                       ; 51ED CD 74 50
               DEFW XPTRP                      ; 51F0 A2 5A
               XOR A                           ; 51F2 AF
               LD (FLAG3),A                    ; 51F3 32 0C 7C
               LD (NRFLG),A                    ; 51F6 32 1F 41  RECURSE OK
               LD E,A                          ; 51F9 5F
               POP HL                          ; 51FA E1
               LD A,(HL)                       ; 51FB 7E  ERR NO.
                                               ; the stack is being reset, so this path does not return
               LD SP,&7FFA                     ; 51FC 31 FA 7F  OK WHETHER CMD OR HOOK
               RET                             ; 51FF C9

;; --------------------------------------------------------------------
;; The messages the DOS prints, indexed by the error code less 81, each
;; ended by bit 7 of its last character.  Bytes below 32 are indices
;; into the ROM's dictionary of common substrings, which is why so many
;; entries are shorter than what they print: 0 is "Invalid ", 11 is
;; "No ", 17 is " not ", 23 is "file", and the rest are in
;; ref/masterdos/docs/errors.md.
;;
;; THIS TABLE IS NOW READ OUT OF THE IMAGE rather than listed by hand.
;; tools/dis_mb.py walks it from this label, expands the compression and
;; fills in any code the ROM's text and errors.md do not already name,
;; so every DOS error in the listing carries the message the machine
;; would actually print.  Where the two overlap they agree: eighteen
;; codes, 84 to 112, read the same from the table as from the document.
;;
;; SEVEN CODES ARE PAST THE END OF THE DOCUMENTATION.  errors.md stops
;; at 112.  The table carries on:
;;
;;     113  Directory not found
;;     114  Directory not empty
;;     115  No pages free
;;     116  PROTECTED file
;;     117  No Buffer
;;     118  Page overlap
;;     119  Size mismatch
;;
;; and then stops being messages -- the bytes after 119 decode as one or
;; two characters, which is what ends the walk.
;;
;; THE TABLE IS WRITTEN IN THOSE NAMES TOO.  MasterDOS's source calls
;; the codes INVALID, ERROR, TREAM, NO, SNOTS, SNAME, TOOMANY, TATEMENT
;; and FILE, and none of the nine clashes with a label in either half,
;; so the listing uses them: DEFB NO where the byte is &0B, and
;; DEFB FILE+&80 where it is &97 and ends the message.
;;
;; THREE OF THE SEVEN UNDOCUMENTED CODES ARE ACTUALLY RAISED, which is
;; the check on having read them right.  The DOS's own chain of error
;; stubs loads 113 at &5195, 114 just after it, and MasterBASIC loads
;; 119 at &43AD.  The other four -- 115 to 118 -- have messages that
;; nothing in either half loads into A; they would be raised by
;; CALL DERR with the code inline, which is the other way in.
;;
;; 119 is the one that prompted this.  MasterBASIC's REP_SIZE_MISMATCH
;; at &43AD loads it, and the only thing that reaches that stub is
;; &706E, which compares a stored pointer against DE just after reading
;; PRPTR and PRPTRP, the ROM's proc address and proc page.  "Size
;; mismatch" fits, and it is the table's own word rather than a guess.
;; --------------------------------------------------------------------

ERRTBL:
               DEFB " "+&80                    ; 5200 A0
               DEFB " "+&80                    ; 5201 A0
               DEFB " "+&80                    ; 5202 A0
               DEFM "Escape requeste"          ; 5203 45 73 63 61 70 65 20 72
               DEFB "d"+&80                    ; 5212 E4
               DEFM "TRK-"                     ; 5213 54 52 4B 2D

; ---- PRTRK ---- from &51BD
PRTRK:
               DEFM " "                        ; 5217 20

; ---- V5218 ---- from &51C3
V5218:
               DEFM "  ,SCT-"                  ; 5218 20 20 2C 53 43 54 2D

; ---- PRSEC ---- from &51CF
PRSEC:
               DEFM "  ,Erro"                  ; 521F 20 20 2C 45 72 72 6F
               DEFB "r"+&80                    ; 5226 F2
               DEFM "Format TRK-"              ; 5227 46 6F 72 6D 61 74 20 54

; ---- FMTRK ---- from &51C0
FMTRK:
               DEFM " "                        ; 5232 20

; ---- V5233 ---- from &51C7
V5233:
               DEFM "   los"                   ; 5233 20 20 20 6C 6F 73
               DEFB "t"+&80                    ; 5239 F4
               DEFM "Check disk in driv"       ; 523A 43 68 65 63 6B 20 64 69
               DEFB "e"+&80                    ; 524C E5
               DEFB " "+&80                    ; 524D A0
               DEFB " "+&80                    ; 524E A0
               DEFB " "+&80                    ; 524F A0
               DEFB INVALID                    ; 5250
               DEFM "devic"                    ; 5251 64 65 76 69 63
               DEFB "e"+&80                    ; 5256 E5
               DEFB " "+&80                    ; 5257 A0
               DEFM "Verify faile"             ; 5258 56 65 72 69 66 79 20 66
               DEFB "d"+&80                    ; 5264 E4
               DEFM "Wrong "                   ; 5265 57 72 6F 6E 67 20
               DEFB FILE                       ; 526B
               DEFM " typ"                     ; 526C 20 74 79 70
               DEFB "e"+&80                    ; 5270 E5
               DEFB " "+&80                    ; 5271 A0
               DEFB " "+&80                    ; 5272 A0
               DEFB " "+&80                    ; 5273 A0
               DEFB " "+&80                    ; 5274 A0
               DEFM "Reading a write "         ; 5275 52 65 61 64 69 6E 67 20
               DEFB FILE+&80                   ; 5285 97
               DEFM "Writing a read "          ; 5286 57 72 69 74 69 6E 67 20
               DEFB FILE+&80                   ; 5295 97
               DEFB NO                         ; 5296
               DEFM "AUTO* "                   ; 5297 41 55 54 4F 2A 20
               DEFB FILE+&80                   ; 529D 97
               DEFB " "+&80                    ; 529E A0
               DEFB NO                         ; 529F
               DEFM "such driv"                ; 52A0 73 75 63 68 20 64 72 69
               DEFB "e"+&80                    ; 52A9 E5
               DEFM "Disk is write protecte"   ; 52AA 44 69 73 6B 20 69 73 20
               DEFB "d"+&80                    ; 52C0 E4
               DEFM "Disk ful"                 ; 52C1 44 69 73 6B 20 66 75 6C
               DEFB "l"+&80                    ; 52C9 EC
               DEFM "Directory ful"            ; 52CA 44 69 72 65 63 74 6F 72
               DEFB "l"+&80                    ; 52D7 EC
               DEFM "File"                     ; 52D8 46 69 6C 65
               DEFB SNOTS                      ; 52DC
               DEFM "foun"                     ; 52DD 66 6F 75 6E
               DEFB "d"+&80                    ; 52E1 E4
               DEFB " "+&80                    ; 52E2 A0
               DEFM "File"                     ; 52E3 46 69 6C 65
               DEFB SNAME                      ; 52E7
               DEFM " use"                     ; 52E8 20 75 73 65
               DEFB "d"+&80                    ; 52EC E4
               DEFB " "+&80                    ; 52ED A0
               DEFM "S"                        ; 52EE 53
               DEFB TREAM                      ; 52EF
               DEFM " use"                     ; 52F0 20 75 73 65
               DEFB "d"+&80                    ; 52F4 E4
               DEFM "Channel use"              ; 52F5 43 68 61 6E 6E 65 6C 20
               DEFB "d"+&80                    ; 5300 E4
               DEFM "Directory"                ; 5301 44 69 72 65 63 74 6F 72
               DEFB SNOTS                      ; 530A
               DEFM "foun"                     ; 530B 66 6F 75 6E
               DEFB "d"+&80                    ; 530F E4
               DEFM "Directory"                ; 5310 44 69 72 65 63 74 6F 72
               DEFB SNOTS                      ; 5319
               DEFM "empt"                     ; 531A 65 6D 70 74
               DEFB "y"+&80                    ; 531E F9
               DEFB NO                         ; 531F
               DEFM "pages fre"                ; 5320 70 61 67 65 73 20 66 72
               DEFB "e"+&80                    ; 5329 E5
               DEFM "PROTECTED "               ; 532A 50 52 4F 54 45 43 54 45
               DEFB FILE+&80                   ; 5334 97
               DEFB NO                         ; 5335
               DEFM "Buffe"                    ; 5336 42 75 66 66 65
               DEFB "r"+&80                    ; 533B F2
               DEFM "Page overla"              ; 533C 50 61 67 65 20 6F 76 65
               DEFB "p"+&80                    ; 5347 F0
