;; --------------------------------------------------------------------
;; NMI -- &5355 to &5373
;;
;; Takes:     BC, DE, HL, IX, IY, I
;; Leaves:    A, F, BC, DE, HL
;;
;; Shown for this routine in disasm/:
;;
;;      NMI -- the snapshot button
;;
;;      Pressing the NMI button freezes whatever is running and offers to write it to disk. The whole machine state is
;;      pushed onto a stack in the DOS's own page, and the key held down when the button was pressed chooses what
;;      happens:
;;
;;        1 or 5   call the user vector at NMIKA, with page NMIKP mapped -- the hook a utility installs itself on. The
;;                 default vector is &0004, which simply returns, so the default action is to do nothing and ask again
;;        2        resume, having done nothing
;;        3        save the screen as a SCREEN$
;;        4        save a 48K snapshot
;;        X        step the page mapped at &8000, so a page other than the default can be captured
;;
;;      The file name is formed from the drive and the directory position it lands in, so successive snapshots do not
;;      collide. Control returns through SNAP7, which restores everything and jumps back into the interrupted code.
;;
;;     NON MASK INT ROUT.
;; --------------------------------------------------------------------

; ---- NMI ---- from &4206, &546F
NMI:
               LD (STR),SP                     ; 5355 ED 73 90 7F
                                               ; the stack is being reset, so this path does not return
               LD SP,STR                       ; 5359 31 90 7F
               LD A,I                          ; 535C ED 57
               PUSH AF                         ; 535E F5
               PUSH HL                         ; 535F E5
               PUSH BC                         ; 5360 C5
               PUSH DE                         ; 5361 D5
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 5362 08
                                               ; to the alternate register set and back again
               EXX                             ; 5363 D9
               PUSH AF                         ; 5364 F5
               PUSH HL                         ; 5365 E5
               PUSH BC                         ; 5366 C5
               PUSH DE                         ; 5367 D5
               PUSH IX                         ; 5368 DD E5
               PUSH IY                         ; 536A FD E5
               LD HL,SNAP7                     ; 536C 21 57 54
               PUSH HL                         ; 536F E5
               LD (HKSP),SP                    ; 5370 ED 73 0B 42  an error during the save unwinds here, which resumes
                                               ; the program

;; --------------------------------------------------------------------
;; SNAP29 -- &5374 to &5379
;;
;; Takes:     nothing in registers
;; Leaves:    A
;;
;; ? drives OUT (HMPR),A; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SNAP29 ---- from &5392
SNAP29:
               LD A,&04                        ; 5374 3E 04
               OUT (HMPR),A                    ; 5376 D3 FB  ZX RAM AT 8000H
               IM 1                            ; 5378 ED 56

;; --------------------------------------------------------------------
;; SNAP3 -- &537A to &5386
;;
;; Takes:     nothing in registers
;; Leaves:    F, BC, E
;;
;; ? drives IN E,(C); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SNAP3 ---- from &53B6 when bit 2 of E set, &53F3
SNAP3:
               LD BC,&F7FE                     ; 537A 01 FE F7
               IN E,(C)                        ; 537D ED 58  BITS 0-4=DIGITS 1-5
               BIT 0,E                         ; 537F CB 43
               JR Z,SNAP31                     ; 5381 28 04  JR IF "1"
               BIT 4,E                         ; 5383 CB 63
               JR NZ,SNAP32                    ; 5385 20 0D  JR IF NOT "5"

;; --------------------------------------------------------------------
;; SNAP31 -- &5387 to &5393
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, E, HL
;; Ends:      JR
;;
;; ? drives IN E,(C), OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- SNAP31 ---- from &5381 when bit 0 of E clear
SNAP31:
               LD HL,(NMIKA)                   ; 5387 2A 3B 42
               LD A,(NMIKP)                    ; 538A 3A 3A 42  NORMALLY 4
               OUT (HMPR),A                    ; 538D D3 FB
               CALL HLJUMP                     ; 538F CD 05 00  JUST RET USUALLY (0004H)
               JR SNAP29                       ; 5392 18 E0

;; --------------------------------------------------------------------
;; SNAP32 -- &5394 to &53A0
;;
;; Takes:     C, E
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JP, JR
;;
;; ? drives IN A,(C); calls CKDRX, DSVBL, FDHR, OFSM.
;; --------------------------------------------------------------------

; ---- SNAP32 ---- from &5385 when bit 4 of E set
SNAP32:
               BIT 1,E                         ; 5394 CB 4B  RET IF "2"
               RET Z                           ; 5396 C8
               BIT 2,E                         ; 5397 CB 53
               JR NZ,SNAP3A                    ; 5399 20 06  JR IF NOT "3"
               LD A,&14                        ; 539B 3E 14  SCREEN$ TYPE
               LD D,&1B                        ; 539D 16 1B  SCREEN LENGTH MSB
               JR SNAP4                        ; 539F 18 2E

;; --------------------------------------------------------------------
;; SNAP3A -- &53A1 to &53AA
;;
;; Takes:     C, E
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JP, JR
;;
;; ? drives IN A,(C); calls CKDRX, DSVBL, FDHR, OFSM.
;; --------------------------------------------------------------------

; ---- SNAP3A ---- from &5399 when bit 2 of E set
SNAP3A:
               BIT 3,E                         ; 53A1 CB 5B
               JR NZ,SNAP3B                    ; 53A3 20 06  JR IF NOT "4"
               LD A,&05                        ; 53A5 3E 05  48K SNAPSHOT TYPE
               LD D,&C0                        ; 53A7 16 C0  LEN MSB
               JR SNAP4                        ; 53A9 18 24

;; --------------------------------------------------------------------
;; SNAP3B -- &53AB to &53B7
;;
;; Takes:     A, BC
;; Leaves:    A, F, B, E
;;
;; ? drives IN E,(C), OUT (C),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      Step to the next page and wait for the key to be released, so the user can pick which page is captured. The
;;      border
;;      changes as they go, which is the only feedback available with the machine frozen.
;; --------------------------------------------------------------------

; ---- SNAP3B ---- from &53A3 when bit 3 of E set
SNAP3B:
               INC A                           ; 53AB 3C
               AND &07                         ; 53AC E6 07
               OUT (C),A                       ; 53AE ED 79  BORDER
               LD B,&FE                        ; 53B0 06 FE
               IN E,(C)                        ; 53B2 ED 58
               BIT 2,E                         ; 53B4 CB 53
               JR NZ,SNAP3                     ; 53B6 20 C2  LOOP IF NOT "X"

;; --------------------------------------------------------------------
;; SNAP3C -- &53B8 to &53CE
;;
;; Takes:     BC
;; Leaves:    A, F, E
;; Ends:      JP
;;
;; ? drives IN E,(C), OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- SNAP3C ---- from &53BC when bit 2 of E clear
SNAP3C:
               IN E,(C)                        ; 53B8 ED 58
               BIT 2,E                         ; 53BA CB 53
               JR Z,SNAP3C                     ; 53BC 28 FA  LOOP TILL NOT "X"
               CALL DELBC                      ; 53BE CD 5F 00  DELAY BC
               LD A,(SNPRT0)                   ; 53C1 3A 06 41
               OUT (HMPR),A                    ; 53C4 D3 FB
               LD A,(SNPRT2)                   ; 53C6 3A 08 41
               OUT (VMPR),A                    ; 53C9 D3 FC
               EI                              ; 53CB FB
               JP ENDS                         ; 53CC C3 10 50

;; --------------------------------------------------------------------
;; SNAP4 -- &53CF to &53EA
;;
;; Takes:     A, C, D
;; Leaves:    A, F, B, E, HL, IX
;;
;; ? drives IN A,(C); falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SNAP4 ---- from &539F, &53A9
SNAP4:
               LD (SNME),A                     ; 53CF 32 E4 41
               LD HL,&8000                     ; 53D2 21 00 80  ZX RAM STARTS AT 8000H
               LD E,L                          ; 53D5 5D  ZERO E
               LD (SNLEN),DE                   ; 53D6 ED 53 F4 41
               LD (SNADD),HL                   ; 53DA 22 F6 41
               LD IX,DOSBUF                    ; 53DD DD 21 00 7C
               LD B,&FE                        ; 53E1 06 FE
               IN A,(C)                        ; 53E3 ED 78
               RRA                             ; 53E5 1F
               LD A,&01                        ; 53E6 3E 01
               JR C,SNAP4A                     ; 53E8 38 01  JR IF NOT "SHIFT"
               INC A                           ; 53EA 3C  DRIVE 2

;; --------------------------------------------------------------------
;; SNAP4A -- &53EB to &53FE
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls CKDRX, FDHR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SNAP4A ---- from &53E8 when bit 0 was set
SNAP4A:
               CALL CKDRX                      ; 53EB CD 0A 48
               LD A,&40                        ; 53EE 3E 40
               CALL FDHR                       ; 53F0 CD 31 4B
               JR NZ,SNAP3                     ; 53F3 20 85  LOOP IF NO SPACE
               LD A,D                          ; 53F5 7A
               AND &07                         ; 53F6 E6 07
               JR Z,SNAP5                      ; 53F8 28 05
               ADD A,&30                       ; 53FA C6 30
               LD (SNME+5),A                   ; 53FC 32 E9 41

;; --------------------------------------------------------------------
;; SNAP5 -- &53FF to &5440
;;
;; Takes:     E, IX
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls OFSM, SVHD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SNAP5 ---- from &53F8 when no bit of &07 is set
SNAP5:
               LD L,E                          ; 53FF 6B
               SLA L                           ; 5400 CB 25
               DEC L                           ; 5402 2D
               LD A,(IX+&0E)                   ; 5403 DD 7E 0E
               ADD A,L                         ; 5406 85
               ADD A,&40                       ; 5407 C6 40
               LD (SNME+6),A                   ; 5409 32 EA 41
               LD HL,SNME                      ; 540C 21 E4 41
               LD DE,NSTR1                     ; 540F 11 3A 41
               LD BC,&0018                     ; 5412 01 18 00
               LDIR                            ; 5415 ED B0
               XOR A                           ; 5417 AF
               LD (FLAG3),A                    ; 5418 32 0C 7C
               LD (PGES1),A                    ; 541B 32 50 41
               CALL OFSM                       ; 541E CD 2B 4D
               LD HL,STR-20                    ; 5421 21 7C 7F
               LD DE,FSA+220                   ; 5424 11 EF 7C
               LD BC,&0016                     ; 5427 01 16 00
               LD A,(NSTR1)                    ; 542A 3A 3A 41
               CP &05                          ; 542D FE 05
               JR Z,SNAP6                      ; 542F 28 10  JR IF 48K SNAP - NO HDR. COPY REGS
               XOR A                           ; 5431 AF
               LD (DE),A                       ; 5432 12  FLAGS
               INC DE                          ; 5433 13
               LD (DE),A                       ; 5434 12  SCREEN MODE
               CALL SVHD                       ; 5435 CD 3B 5F
               LD HL,SNPTAB                    ; 5438 21 50 54  SCREEN$ START, LEN
               LD DE,FSA+236                   ; 543B 11 FF 7C
               LD BC,&0007                     ; 543E 01 07 00

;; --------------------------------------------------------------------
;; SNAP6 -- &5441 to &5456
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JP
;;
;; ? calls DSVBL.
;; --------------------------------------------------------------------

; ---- SNAP6 ---- from &542F when A = &05
SNAP6:
               LDIR                            ; 5441 ED B0
               LD HL,(SNADD)                   ; 5443 2A F6 41
               LD DE,(SNLEN)                   ; 5446 ED 5B F4 41
               CALL DSVBL                      ; 544A CD 59 49
               JP CFSM                         ; 544D C3 FE 4D

; ---- SNPTAB ---- from &5438
SNPTAB:
               DEFB &6E,&00                    ; 5450 n.  START (IF 256K MACHINE)
               ADD A,B                         ; 5452 80
               DEFB &00                        ; 5453 .  LEN
               NOP                             ; 5454 00
               DEC DE                          ; 5455 1B
               DEFB &FF                        ; 5456 .

;; --------------------------------------------------------------------
;; SNAP7 -- &5457 to &5496
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, HL, IX, IY, I
;;
;; ? drives OUT (HMPR),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      SNAP7 -- resume the interrupted program
;;
;;      Unwinds the register stack, leaves a copy of the NMI entry point and the paging registers where a resumed
;;      snapshot
;;      can find them, restores the interrupt mode, and jumps back into the code that was interrupted.
;;
;;     RETURN ADDRESS OF SNAPSHOT
;; --------------------------------------------------------------------

; ---- SNAP7 ---- from &536C, &5971 when C reaches 0, &5FF4
SNAP7:
               DI                              ; 5457 F3
               LD A,&03                        ; 5458 3E 03
               OUT (HMPR),A                    ; 545A D3 FB  SPECTRUM "ROM" AT 8000H
               LD HL,&0000                     ; 545C 21 00 00
               LD (HKSP),HL                    ; 545F 22 0B 42
                                               ; the stack is being reset, so this path does not return
               LD SP,STR-20                    ; 5462 31 7C 7F
               POP IY                          ; 5465 FD E1
               POP IX                          ; 5467 DD E1
               POP DE                          ; 5469 D1
               POP BC                          ; 546A C1
               POP HL                          ; 546B E1
               POP AF                          ; 546C F1
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 546D 08
                                               ; to the alternate register set and back again
               EXX                             ; 546E D9
               LD HL,NMI                       ; 546F 21 55 53
               LD (&B8F6),HL                   ; 5472 22 F6 B8
               LD A,(SNPRT0)                   ; 5475 3A 06 41
               LD (&B8F8),A                    ; 5478 32 F8 B8
               LD A,(SNPRT1)                   ; 547B 3A 07 41
               LD (&B8F9),A                    ; 547E 32 F9 B8
               LD A,(SNPRT2)                   ; 5481 3A 08 41
               LD (&B8FA),A                    ; 5484 32 FA B8
               POP DE                          ; 5487 D1
               POP BC                          ; 5488 C1
               POP HL                          ; 5489 E1
               POP AF                          ; 548A F1
               LD I,A                          ; 548B ED 47
               CP &00                          ; 548D FE 00
               JR Z,SNAP8                      ; 548F 28 06
               CP &3F                          ; 5491 FE 3F
               JR Z,SNAP8                      ; 5493 28 02
               IM 2                            ; 5495 ED 5E

;; --------------------------------------------------------------------
;; SNAP8 -- &5497 to &549D
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- SNAP8 ---- from &548F when A = &00, &5493 when A = &3F
SNAP8:
                                               ; the stack is being reset, so this path does not return
               LD SP,(STR)                     ; 5497 ED 7B 90 7F
               JP &B900                        ; 549B C3 00 B9

;; --------------------------------------------------------------------
;; DFMT -- &549E to &54A6
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, B
;;
;; ? calls CKDRV, SELD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      PART E1 -- Formatting, and the printing the catalogue needs
;;
;;        DFMT / DMT1 / WFM     format a disk, and build the track image the controller writes
;;        FESET                 stamp track 0 sector 1 with the disk's name, identity and directory size
;;        ITRCK / ISECT         track and sector housekeeping
;;        PNTYP / DRTAB         print a file's type, and for some types its address and length
;;        PNUM6 .. PNM5         decimal printing with leading-zero suppression
;;        PTM / MCPT            print a message, expanding the DOS's own compression codes
;;        PMO3 .. PMYNAE        the messages
;;        PNDNM                 print the disk's name
;;        CYES / FNMAE          the confirmation prompts
;;
;;      Two layers of message compression
;;
;;      Part D1's error table compresses against the ROM's dictionary. The messages here compress against MasterDOS's
;;      own,
;;      MCPT, whose codes are 1 to 12 and are listed with the table. Code 0 is not a substring at all: it clears the
;;      lower
;;      screen, so a message can begin by wiping what was there.
;;
;;      DFMT -- FORMAT
;;
;;      Writes every track, then either copies another disk onto it, verifies it, or does neither, depending on whether
;;      a
;;      second drive was named.
;;
;;      Before anything is destroyed, track 0 sector 1 is read so that the existing disk's name can be shown in the
;;      confirmation prompt -- a read error there is taken as "blank or unreadable disk" and the prompt is skipped.
;;
;;      Formatting uses the controller's write-track command, which writes a whole track from an image in memory
;;      including
;;      the gaps, sync fields and address marks. The controller stops at the index hole, so the trailing gap is
;;      deliberately longer than a track and the surplus is never written.
;;
;;     DISC FORMAT ROUTINE
;; --------------------------------------------------------------------

; ---- DFMT ---- from &60F9
DFMT:
               DI                              ; 549E F3
               CALL CKDRV                      ; 549F CD 07 48
               CALL SELD                       ; 54A2 CD 2F 48
               LD B,&0A                        ; 54A5 06 0A  step in a little, so the restore below has somewhere to
                                               ; come back from

;; --------------------------------------------------------------------
;; DFMTA -- &54A7 to &54D6
;;
;; Takes:     BC, IX
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls WAIT_DC_READY_BEFORE_CMD, RDDATA, CTAS, STEP_HEAD_IN; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- DFMTA ---- from &54AC when B is not 0 yet
DFMTA:
               PUSH BC                         ; 54A7 C5
               CALL STEP_HEAD_IN               ; 54A8 CD 7F 47
               POP BC                          ; 54AB C1
               DJNZ DFMTA                      ; 54AC 10 F9
               CALL REST                       ; 54AE CD AD 47
               CALL CTAS                       ; 54B1 CD 38 47
               DI                              ; 54B4 F3
               LD C,READ_SECTOR_CMD            ; 54B5 0E 80
               CALL WAIT_DC_READY_BEFORE_CMD   ; 54B7 CD 58 45
               CALL GTBUF                      ; 54BA CD A0 4F
               CALL RDDATA                     ; 54BD CD C8 45
               AND &0D                         ; 54C0 E6 0D
               JR NZ,DFMTB                     ; 54C2 20 2C  JR IF ERROR ON READ T0/S1
               CALL PMO6                       ; 54C4 CD 09 58  "FORMAT "
               LD HL,V7DE5                     ; 54C7 21 E5 7D
               LD A,(HL)                       ; 54CA 7E
               INC A                           ; 54CB 3C
