               LD BC,&FFD6                     ; 5605 01 D6 FF
               ADD HL,BC                       ; 5608 09  PT TO DISC NAME DEST (BYTE D2H)
               PUSH DE                         ; 5609 D5
               LD DE,NSTR1+1                   ; 560A 11 3B 41
               EX DE,HL                        ; 560D EB
