;; --------------------------------------------------------------------
;; PNDNM -- &5898 to &589A
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;;
;; Shown for this routine in disasm/:
;;
;;      PNDNM -- print the disk's name
;;
;;      A disk formatted by SAMDOS has no name field, and reads as 00 or &FF there; those print "SAM DOS". A name of "*"
;;      means the disk was formatted by MasterDOS but not named, and prints "MASTER DOS". Anything else is a real name
;;      and
;;      is copied into the message at DNAME, which is printed in place.
;;
;;      Bit 7 of the first character is reserved as an "in back-up" marker and is cleared as the name is read.
;;
;;     PRINT DISC NAME
;; --------------------------------------------------------------------

; ---- PNDNM ---- from &5C0C
PNDNM:
               LD HL,DNAME                     ; 5898 21 B5 58

;; --------------------------------------------------------------------
;; PNDN2 -- &589B to &589E
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; --------------------------------------------------------------------

; ---- PNDN2 ---- from &54D7
PNDN2:
               LD A,(HL)                       ; 589B 7E  00 IF OLD DOS, OR FF IF NEV USED
               RES 7,(HL)                      ; 589C CB BE  SO NEV CAN USE BIT 7 AS IBU MARKER
               INC A                           ; 589E 3C

;; --------------------------------------------------------------------
;; PNDN2_1 -- &589F to &58A3
;;
;; Takes:     A, HL
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- PNDN2_1 ---- from &7BF4
PNDN2_1:
               CP &02                          ; 589F FE 02
               JR C,PMOSD                      ; 58A1 38 DD  PRINT "   SAM DOS " IF OLD DOS
               LD A,(HL)                       ; 58A3 7E

;; --------------------------------------------------------------------
;; PNDN2_2 -- &58A4 to &58A7
;;
;; Takes:     A
;; Leaves:    F
;; --------------------------------------------------------------------

; ---- PNDN2_2 ---- from &7BED
PNDN2_2:
               CP &2A                          ; 58A4 FE 2A
               JR NZ,PMO8                      ; 58A6 20 0A  PRINT DISC NAME IF THERE IS ONE,

;; --------------------------------------------------------------------
;; PMOMD -- &58A8 to &58B1
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;;
;; ? calls PTM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

PMOMD:
               CALL PTM                        ; 58A8 CD 7C 57
               DEFM "MASTER"                   ; 58AB 4D 41 53 54 45 52
               DEFB &86                        ; 58B1

;; --------------------------------------------------------------------
;; PMO8 -- &58B2 to &58D0
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;;
;; ? calls PTM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- PMO8 ---- from &58A6 when A <> &2A
PMO8:
               CALL PTM                        ; 58B2 CD 7C 57

; ---- DNAME ---- from &5898, &748D
DNAME:
               DEFB &00,&00,&00,&00,&00,&00,&00,&00,&00,&00 ; 58B5
               DEFB " "+&80                                 ; 58BF A0
               DEFB "M"+&80                                 ; 58C0 CD
               DEFM "|W OPEN Fil"                           ; 58C1 7C 57 20 4F 50 45 4E 20
               DEFB "e"+&80                                 ; 58CC E5

; ---- MSGUN ---- from &58E5
MSGUN:
               DEFM "UN "                      ; 58CD 55 4E 20
               DEFB &08                        ; 58D0

;; --------------------------------------------------------------------
;; OHNM -- &58D1 to &58ED
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through CURCMD; calls NRRD, WIQF, CLSL; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      OHNM -- print the name of the command that is asking for confirmation
;;
;;      The command token is printed as a keyword, which means turning off the ROM's in-quotes flag so that the byte is
;;      expanded rather than shown as a graphic. PROTECT and HIDE with OFF are prefixed with "UN", the trailing
;;      backspace
;;      cancelling the space the keyword expansion adds.
;; --------------------------------------------------------------------

; ---- OHNM ---- from &5D39
OHNM:
               CALL CLSL                       ; 58D1 CD E4 5A
               XOR A                           ; 58D4 AF
               CALL WIQF                       ; 58D5 CD F8 58  TOKENS ON
                                               ; read the ROM variable CURCMD -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 58D8 CD 5E 50
               DEFW CURCMD                     ; 58DB 74 5B
               CP &F1                          ; 58DD FE F1
               JR C,OHNM2                      ; 58DF 38 0D  JR IF ERASE OR COPY
               PUSH AF                         ; 58E1 F5
               CALL BITF1                      ; 58E2 CD 22 51
               LD HL,MSGUN                     ; 58E5 21 CD 58
               LD B,&04                        ; 58E8 06 04
               CALL NZ,PRINT_B_CHARACTERS      ; 58EA C4 1B 5C  PRINT "UN" IF PROTECT OR HIDE OFF
               POP AF                          ; 58ED F1

;; --------------------------------------------------------------------
;; OHNM2 -- &58EE to &58F7
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls PRINT_A_KEEPING_IT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OHNM2 ---- from &58DF when A < &F1
OHNM2:
               CALL PRINT_A_KEEPING_IT         ; 58EE CD 66 57  PRINT PROTECT, HIDE, ERASE OR COPY
               LD A,&22                        ; 58F1 3E 22
               CALL PRINT_A_KEEPING_IT         ; 58F3 CD 66 57  NOW E.G. ERASE "
               LD A,&01                        ; 58F6 3E 01

;; --------------------------------------------------------------------
;; WIQF -- &58F8 to &58FD
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? reaches the ROM through INQUFG; calls NRWR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- WIQF ---- from &58D5
WIQF:
                                               ; write the ROM variable INQUFG
               CALL NRWR                       ; 58F8 CD 74 50
               DEFW INQUFG                     ; 58FB BA 5A
               RET                             ; 58FD C9

