;; Ends:      RET
;;
;; ? calls PFNME, PMYNAE, CYES1.
;;
;; Shown for this routine in disasm/:
;;
;;      FNMAE -- ask about one file, offering yes, no, all or end
;;
;;      "A" clears the flag that makes the DOS ask at all, so the rest of the operation runs without further prompting;
;;      "E" abandons the command entirely.
;; --------------------------------------------------------------------

; ---- FNMAE ---- from &5D3C
FNMAE:
               CALL PFNME                      ; 58FE CD 09 4B  PRINT FILE NAME
               CALL PMYNAE                     ; 5901 CD 8A 58  Y/N/A/E
               CALL CYES1                      ; 5904 CD 20 59
               RET Z                           ; 5907 C8  RET IF "Y"
               CP &45                          ; 5908 FE 45
               JP Z,ENDS                       ; 590A CA 10 50  END
               CP &41                          ; 590D FE 41
               RET NZ                          ; 590F C0
               LD HL,FLAG3                     ; 5910 21 0C 7C
               RES 7,(HL)                      ; 5913 CB BE  "?" OPTION OFF - DO ALL
               CP A                            ; 5915 BF  Z - "Y"
               RET                             ; 5916 C9

