               POP BC                          ; 5A17 C1
               LD HL,&01FE                     ; 5A18 21 FE 01
               CALL M510                       ; 5A1B CD DF 71  GET AHL=HL+BC*510 (MAX FILE SIZE)
               CALL PAGEFORM                   ; 5A1E CD E4 75
               RES 7,H                         ; 5A21 CB BC  A=PAGES, HL=LEN MOD 16K

;; --------------------------------------------------------------------
