               CALL GCOP                       ; 5A58 CD A9 5A
               CALL ROOM_LEFT_IN_PAGE          ; 5A5B CD 56 48
               CALL TSPCE1                     ; 5A5E CD 34 59
               CALL BSWOP                      ; 5A61 CD 61 62
               CALL TRX                        ; 5A64 CD E6 62
               CALL CKDRV                      ; 5A67 CD 07 48
               CALL BITF3                      ; 5A6A CD 2E 51
               JR NZ,CYSV1                     ; 5A6D 20 08  JR IF NOT FIRST PASS
               CALL OFSM                       ; 5A6F CD 2B 4D
               JR C,COPY3                      ; 5A72 38 2C  JR IF "OVERWRITE?" AND N
               CALL SETF3                      ; 5A74 CD FE 50  "NO OFSM NEXT TIME"

;; --------------------------------------------------------------------
;; CYSV1 -- &5A77 to &5A9F
;;
;; Takes:     IX
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls DWAIT, HSVBK, PFNM0, SCFSM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CYSV1 ---- from &5A6D
CYSV1:
               CALL PMOH                       ; 5A77 CD 74 58  "SAVING "
               LD HL,NSTR1+1                   ; 5A7A 21 3B 41
               CALL PFNM0                      ; 5A7D CD 0E 4B
               CALL DWAIT                      ; 5A80 CD 64 45  SPIN DISK IF STOPPED
               CALL GCOP                       ; 5A83 CD A9 5A
               LD DE,(TEMPW1)                  ; 5A86 ED 5B 12 42  LEN
               CALL HSVBK                      ; 5A8A CD 46 49
               CALL BITF1                      ; 5A8D CD 22 51
               JR NZ,COPY3                     ; 5A90 20 0E  NO CLOSE IF PART STILL TO DO
               LD HL,STR-30                    ; 5A92 21 72 7F
               LD DE,FSA+210                   ; 5A95 11 E5 7C
               LD BC,&002A                     ; 5A98 01 2A 00
               LDIR                            ; 5A9B ED B0
               CALL SCFSM                      ; 5A9D CD F8 4D

;; --------------------------------------------------------------------
;; COPY3 -- &5AA0 to &5AA8
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JP
;;
;; ? calls DWAIT, READ_SECTOR, CKDRV, ROOM_LEFT_IN_PAGE.
;; --------------------------------------------------------------------

; ---- COPY3 ---- from &5A72, &5A90
COPY3:
               CALL BSWOP                      ; 5AA0 CD 61 62
               CALL TSPCE2                     ; 5AA3 CD 3D 59  MSG IF SINGLE DRIVE
               JP COPYB_LOOP                   ; 5AA6 C3 E3 59

;; --------------------------------------------------------------------
;; GCOP -- &5AA9 to &5AB6
;;
;; Takes:     nothing in registers
;; Leaves:    A, HL
;; Ends:      RET
;;
;; ? drives OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- GCOP ---- from &5A58, &5A83
GCOP:
               LD HL,(TEMPW2)                  ; 5AA9 2A 14 42
               LD A,H                          ; 5AAC 7C
               LD (PGES1),A                    ; 5AAD 32 50 41
               LD A,L                          ; 5AB0 7D
               OUT (HMPR),A                    ; 5AB1 D3 FB
               LD HL,MB_PUTSWA                 ; 5AB3 21 00 80
               RET                             ; 5AB6 C9

;; --------------------------------------------------------------------
;; FFPG -- &5AB7 to &5ABE
;;
;; Takes:     A
;; Leaves:    A, F, B, HL
;;
;; ? drives OUT (HMPR),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      FFPG -- find the largest run of free pages
;;
;;      Walks the ROM's page allocation table downwards from the top, measuring each run of zero -- unallocated --
;;      entries
;;      and keeping the longest. The table is in the system page, which is mapped at &8000 for the duration.
;;
;;      Exit:   B = the size of the largest free block in pages, E = the page it starts at
;;
;;     FIND FREE PAGES
;;     EXIT: SYS PAGE AT 8000H, B=SIZE OF MAX FREE BLOCK IN PAGES,
;;           E=PAGE NUMBER
;; --------------------------------------------------------------------

; ---- FFPG ---- from &5A2E, &6A0C
FFPG:
               XOR A                           ; 5AB7 AF
               OUT (HMPR),A                    ; 5AB8 D3 FB
               LD HL,ALLOCT+FS+31              ; 5ABA 21 1F 91
               LD B,&00                        ; 5ABD 06 00  BIGGEST BLOCK SO FAR=0 PAGES

;; --------------------------------------------------------------------
;; FFM -- &5ABF to &5ABF
;;
;; Takes:     L
;; Leaves:    F, L
;; --------------------------------------------------------------------

; ---- FFM ---- from &5AD0 when A >= C, &5AD5
FFM:
               INC L                           ; 5ABF 2C

;; --------------------------------------------------------------------
;; FFPL -- &5AC0 to &5AC7
;;
;; Takes:     HL
;; Leaves:    A, F, C, L
;; --------------------------------------------------------------------

; ---- FFPL ---- from &5AC4 when A <> 0
FFPL:
               DEC L                           ; 5AC0 2D
               RET Z                           ; 5AC1 C8
               LD A,(HL)                       ; 5AC2 7E
               AND A                           ; 5AC3 A7
               JR NZ,FFPL                      ; 5AC4 20 FA  LOOP, LOOKING FOR A FREE PAGE
               LD C,&00                        ; 5AC6 0E 00  CURRENT BLOCK=0 PAGES

;; --------------------------------------------------------------------
;; CFPL -- &5AC8 to &5AD6
;;
;; Takes:     BC, HL
;; Leaves:    A, F, BC, E, L
;; Ends:      JR
;; --------------------------------------------------------------------

; ---- CFPL ---- from &5ACC when A = 0
CFPL:
               DEC L                           ; 5AC8 2D
               LD A,(HL)                       ; 5AC9 7E
               INC C                           ; 5ACA 0C
               AND A                           ; 5ACB A7
               JR Z,CFPL                       ; 5ACC 28 FA  LOOP WHILE PAGES FREE, COUNTING
               LD A,B                          ; 5ACE 78
               CP C                            ; 5ACF B9
               JR NC,FFM                       ; 5AD0 30 ED  JR IF CURRENT BLOCK NO BIGGER
               LD B,C                          ; 5AD2 41  NEW MAX SIZE
               LD E,L                          ; 5AD3 5D
               INC E                           ; 5AD4 1C  POINT TO FIRST PAGE IN FREE BLOCK
               JR FFM                          ; 5AD5 18 E8

;; --------------------------------------------------------------------
;; BUDT -- &5AD7 to &5AE3
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
;;
;; ? calls GETSCR.
;; --------------------------------------------------------------------

; ---- BUDT ---- from &59DE, &6272
BUDT:
               CALL GETSCR                     ; 5AD7 CD 2C 49
               LD HL,RPT                       ; 5ADA 21 0D 7C
               LD DE,&B800                     ; 5ADD 11 00 B8  ALLOWS 1580H BYTES FOR SECTOR LIST
               LD BC,&0306                     ; 5AE0 01 06 03  LEN OF RPT, BUF, NSR, FSA, DRAM
               RET                             ; 5AE3 C9

;; --------------------------------------------------------------------
;; CLSL -- &5AE4 to &5AED
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through CLSLOW; calls CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CLSL ---- from &55A0, &5789, &58D1, &592F, &594E
CLSL:
               PUSH IX                         ; 5AE4 DD E5  USED BY MODE 1/2 CLS
                                               ; call the ROM at CLSLOW with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 5AE6 CD B2 7B
               DEFW CLSLOW                     ; 5AE9 51 01
               POP IX                          ; 5AEB DD E1
               RET                             ; 5AED C9

;; --------------------------------------------------------------------
;; DIR -- &5AEE to &5B0B
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GTNC, SEPARX, EVSRM, FDFSR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      DIR -- the catalogue
;;
;;      Several forms, distinguished as they are parsed:
;;
;;        DIR                 names only, sorted, in as many columns as the window allows
;;        DIR n / DIR "name"  the detailed listing: number, name, sectors, type
;;        DIR ... !           forces the short form
;;        DIR DATE            the detailed listing with each file's date and time
;;        DIR #s              to a stream other than 2
;;        DIR =               set the directory (see part SUBD)
;;        DIR ?               include files from every subdirectory, not just the current one
;;
;;      The short form cannot print as it goes, because the names have to be sorted first: DITOB collects them into the
;;      screen page, ORDER sorts them there, and PCNML prints them in columns.
;;
;;     CALL UP DIRECTORY
;; --------------------------------------------------------------------

DIR:
               CALL FDFSR                      ; 5AEE CD CF 66  CALL GTIXD, GTDEF, NULL NAME
               LD A,&02                        ; 5AF1 3E 02
               LD (SSTR1),A                    ; 5AF3 32 38 41  STREAM 2
               XOR A                           ; 5AF6 AF
               LD (DTFLG),A                    ; 5AF7 32 33 42  "PRINT DATES" OFF
               CALL GTNC                       ; 5AFA CD 3C 50
               CP &3D                          ; 5AFD FE 3D
               JP Z,STDIR                      ; 5AFF CA 23 72
               CP &23                          ; 5B02 FE 23
               JR NZ,CAT0                      ; 5B04 20 06
               CALL EVSRM                      ; 5B06 CD 99 62
               CALL SEPARX                     ; 5B09 CD DC 5E

;; --------------------------------------------------------------------
;; CAT0 -- &5B0C to &5B1A
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CIEL, GTNC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CAT0 ---- from &5B04 when A <> &23
CAT0:
               CP &F9                          ; 5B0C FE F9  "DATE" TOKEN
               JR NZ,CAT1                      ; 5B0E 20 0B
               LD (DTFLG),A                    ; 5B10 32 33 42  "PRINT DATES" ON (NZ)
               CALL GTNC                       ; 5B13 CD 3C 50  SKIP "DATE"
               CALL CIEL                       ; 5B16 CD F0 4F
               JR Z,CAT2                       ; 5B19 28 37  "DIR DATE" GIVES DETAILED,

;; --------------------------------------------------------------------
;; CAT1 -- &5B1B to &5B3A
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    BC, DE, HL, IY
;; Preserves: A, F (saved and restored)
;;
;; ? calls CIEL, ALLSR, SEPAR, EVEXP; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CAT1 ---- from &5B0E when A <> &F9
CAT1:
               CALL ALLSR                      ; 5B1B CD C6 5C
               CALL CIEL                       ; 5B1E CD F0 4F
               JR Z,CAT1a                      ; 5B21 28 28  JUST "DIR" GIVES SIMPLE DIR
               CALL EVEXP                      ; 5B23 CD 60 61  EVAL DRIVE, OR FILE NAME
               JR NC,CAT11                     ; 5B26 30 13  JR IF IT WAS A NAME
               CALL SEPAR                      ; 5B28 CD E4 5E  ,/;/"
               JR NZ,CAT12                     ; 5B2B 20 14
               LD A,(DSTR1)                    ; 5B2D 3A 36 41
               PUSH AF                         ; 5B30 F5  Z
               CALL EVNAM                      ; 5B31 CD CF 61  EVAL NAME - ,/;/" FOLLOWED DRIVE
               CALL NZ,EVFINS                  ; 5B34 C4 21 73  NUMBER
               POP AF                          ; 5B37 F1  Z
               LD (DSTR1),A                    ; 5B38 32 36 41  KEEP DRIVE NO SET BY NUMBER

;; --------------------------------------------------------------------
;; CAT11 -- &5B3B to &5B40
;;
;; Takes:     BC, DE
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GCHR, EVFINS; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CAT11 ---- from &5B26
CAT11:
               CALL NZ,EVFINS                  ; 5B3B C4 21 73  PROCESS NAME IF RUN TIME
               CALL GCHR                       ; 5B3E CD 42 50

;; --------------------------------------------------------------------
;; CAT12 -- &5B41 to &5B4A
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GTNC, ALLSR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CAT12 ---- from &5B2B
CAT12:
               CP &21                          ; 5B41 FE 21
               JR NZ,CAT2                      ; 5B43 20 0D  JR IF E.G. DIR 1,"NAME" OR DIR 1
               CALL GTNC                       ; 5B45 CD 3C 50  SKIP "!" - E.G. DIR 1,"NAME"!
               CALL ALLSR                      ; 5B48 CD C6 5C  OR DIR 1!-SIMPLE

;; --------------------------------------------------------------------
;; CAT1a -- &5B4B to &5B51
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JR
;;
;; ? calls CKDRV, CEOS, CMR.
;; --------------------------------------------------------------------

; ---- CAT1a ---- from &5B21
CAT1a:
               CALL CEOS                       ; 5B4B CD 07 50
               LD A,&02                        ; 5B4E 3E 02  SIMPLE DIR
               JR HK_PCAT                      ; 5B50 18 0F

;; --------------------------------------------------------------------
;; CAT2 -- &5B52 to &5B60
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through JCLSBL; calls CEOS, ALLSR, CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CAT2 ---- from &5B19, &5B43 when A <> &21
CAT2:
               CALL ALLSR                      ; 5B52 CD C6 5C
               CALL CEOS                       ; 5B55 CD 07 50
               LD A,&01                        ; 5B58 3E 01  WINDOW
                                               ; call the ROM at JCLSBL with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 5B5A CD B2 7B
               DEFW JCLSBL                     ; 5B5D 4E 01
               LD A,&04                        ; 5B5F 3E 04  SINGLE COLUMN DETAILED DIR

;; --------------------------------------------------------------------
;; HK_PCAT -- &5B61 to &5B8D
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through STREAM; calls CKDRV, CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- HK_PCAT ---- from &5B50
HK_PCAT:
               PUSH AF                         ; 5B61 F5
               CALL CKDRV                      ; 5B62 CD 07 48
               LD A,(SSTR1)                    ; 5B65 3A 38 41
                                               ; call the ROM at STREAM with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 5B68 CD B2 7B
               DEFW STREAM                     ; 5B6B 12 01
               CALL ZDVS                       ; 5B6D CD 23 5C  ZERO VARS
               POP AF                          ; 5B70 F1  2 IF SIMPLE
               CP &02                          ; 5B71 FE 02
               JR NZ,PCAT2                     ; 5B73 20 4E
               CALL DITOB                      ; 5B75 CD 30 5C
               CALL SETBORDER_BORDCR           ; 5B78 CD 52 51  DIR TO BUFFER
               CALL PDIRH                      ; 5B7B CD 09 5C  PRINT HEADER
               LD HL,(PTRSCR)                  ; 5B7E 2A 2C 41
               LD DE,&A000                     ; 5B81 11 00 A0
               AND A                           ; 5B84 A7
               SBC HL,DE                       ; 5B85 ED 52  HL=TEXT LEN (1SL
               JR Z,PCN3                       ; 5B87 28 32  L5AA9 ? L5AA9 ? L5AA9_PCN3 ?  ;*
               LD BC,&000A                     ; 5B89 01 0A 00  *
               LD D,B                          ; 5B8C 50  *
               LD E,B                          ; 5B8D 58  *

;; --------------------------------------------------------------------
;; HK_PCAT_LOOP -- &5B8E to &5BA0
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CALLMB; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- HK_PCAT_LOOP ---- from &5B91
HK_PCAT_LOOP:
               INC DE                          ; 5B8E 13  *
               SBC HL,BC                       ; 5B8F ED 42  *
               JR NZ,HK_PCAT_LOOP              ; 5B91 20 FB  L5A80 = L5A80 = L5A80         ;*
               LD HL,&A000                     ; 5B93 21 00 A0  HL=START, DE=FILES
               LD A,(SRTFG)                    ; 5B96 3A 29 42
               AND A                           ; 5B99 A7
               JR Z,HK_PCAT_1                  ; 5B9A 28 05
                                               ; call &47FB in the other page: LMPR is switched first, so that address
                                               ; is how the other listing numbers it
               CALL CALLMB                     ; 5B9C CD BD 42
               DEFW &47FB                      ; 5B9F FB 47

;; --------------------------------------------------------------------
;; HK_PCAT_1 -- &5BA1 to &5BA4
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL
;;
;; ? calls COLUMNS_FOR_DIRECTORY; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- HK_PCAT_1 ---- from &5B9A when A = 0
HK_PCAT_1:
               CALL COLUMNS_FOR_DIRECTORY      ; 5BA1 CD 8B 5C  NAMES/LINE IN B. COULD BE 1,2,3...
               LD C,B                          ; 5BA4 48

;; --------------------------------------------------------------------
;; PCNML -- &5BA5 to &5BB5
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, B, DE
;; Preserves: C (saved and restored)
;;
;; ? calls PFNM0; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- PCNML ---- from &5BB9
PCNML:
               PUSH BC                         ; 5BA5 C5  B=NAMES/LINE COUNTER, C=RELOAD
               CALL PFNM0                      ; 5BA6 CD 0E 4B  PRINT NAME, ADVANCE HL
               POP BC                          ; 5BA9 C1
               DEC DE                          ; 5BAA 1B
               LD A,D                          ; 5BAB 7A
               OR E                            ; 5BAC B3
               JR Z,PCN3                       ; 5BAD 28 0C  EXIT IF ALL DONE
               LD A,&20                        ; 5BAF 3E 20
               DJNZ PCN2                       ; 5BB1 10 03  JR AND USE SPACE UNLESS LAST
               LD A,&0D                        ; 5BB3 3E 0D
               LD B,C                          ; 5BB5 41  RELOAD COUNTER

;; --------------------------------------------------------------------
;; PCN2 -- &5BB6 to &5BBA
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, B, DE, HL, IY
;; Preserves: C (saved and restored)
;; Ends:      JR
;;
;; ? calls PFNM0, PRINT_A_KEEPING_IT.
;; --------------------------------------------------------------------

; ---- PCN2 ---- from &5BB1 when B is not 0 yet
PCN2:
               CALL PRINT_A_KEEPING_IT         ; 5BB6 CD 66 57  CR OR SPACE
               JR PCNML                        ; 5BB9 18 EA

;; --------------------------------------------------------------------
;; PCN3 -- &5BBB to &5BC2
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JP, JR
;;
;; ? calls SET_SCREEN_POINTER, PNUM4, SPC, PRINT_A_KEEPING_IT.
;; --------------------------------------------------------------------

; ---- PCN3 ---- from &5B87, &5BAD
PCN3:
               CALL SET_SCREEN_POINTER         ; 5BBB CD 28 46
               CALL PNCR                       ; 5BBE CD FC 5B
               JR PCN4                         ; 5BC1 18 03

;; --------------------------------------------------------------------
;; PCAT2 -- &5BC3 to &5BC5
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls FDHR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- PCAT2 ---- from &5B73 when A <> &02
PCAT2:
               CALL FDHR                       ; 5BC3 CD 31 4B  DO COMPLEX DIRECTORY

;; --------------------------------------------------------------------
;; PCN4 -- &5BC6 to &5BFB
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls PNUM4, SPC, PRINT_A_KEEPING_IT, PMO3; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      The summary: free kilobytes, files in this directory, and free directory slots. PLUR adds the "s" unless the
;;      count
;;      happens to be one.
;; --------------------------------------------------------------------

; ---- PCN4 ---- from &5BC1
PCN4:
               CALL PMO3                       ; 5BC6 CD E2 57  "Number of Free K-Bytes = "
               CALL STATS                      ; 5BC9 CD 3E 5C  GET HL=FREE SECTS, DE=FREE SLOTS
               PUSH DE                         ; 5BCC D5
               SRL H                           ; 5BCD CB 3C
               RR L                            ; 5BCF CB 1D  HALVE FREE SECTS
               XOR A                           ; 5BD1 AF
               CALL PNUM4                      ; 5BD2 CD 29 57  FREE K
               CALL PNCR                       ; 5BD5 CD FC 5B  CARRIAGE RETURN
               LD HL,(FCNT)                    ; 5BD8 2A 1C 42
               PUSH HL                         ; 5BDB E5
               XOR A                           ; 5BDC AF
               CALL PNUM4                      ; 5BDD CD 29 57  PRINT NO. OF FILES IN CURRENT DIR
               CALL PMOE                       ; 5BE0 CD 58 58  PRINT " File"
               POP HL                          ; 5BE3 E1
               CALL PLUR                       ; 5BE4 CD 01 5C
               LD A,&2C                        ; 5BE7 3E 2C
               CALL PRINT_A_KEEPING_IT         ; 5BE9 CD 66 57
               CALL SPC                        ; 5BEC CD 64 57
               POP HL                          ; 5BEF E1
               PUSH HL                         ; 5BF0 E5
               XOR A                           ; 5BF1 AF
               CALL PNUM4                      ; 5BF2 CD 29 57  PRINT SLOTS FREE
               CALL PMOF                       ; 5BF5 CD 60 58  PRINT " Free Slot"
               POP HL                          ; 5BF8 E1
               CALL PLUR                       ; 5BF9 CD 01 5C

;; --------------------------------------------------------------------
;; PNCR -- &5BFC to &5BFD
;;
;; Takes:     nothing in registers
;; Leaves:    A
;; --------------------------------------------------------------------

; ---- PNCR ---- from &56B8, &5BBE, &5BD5, &5C09, &5C16, &5C19
PNCR:
               LD A,&0D                        ; 5BFC 3E 0D

;; --------------------------------------------------------------------
;; PTHP -- &5BFE to &5C00
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- PTHP ---- from &5C07
PTHP:
               JP PRINT_A_KEEPING_IT           ; 5BFE C3 66 57

;; --------------------------------------------------------------------
;; PLUR -- &5C01 to &5C08
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; Ends:      JP, JR
;; --------------------------------------------------------------------

; ---- PLUR ---- from &5BE4, &5BF9, &74B0
PLUR:
               DEC HL                          ; 5C01 2B
               LD A,H                          ; 5C02 7C
               OR L                            ; 5C03 B5
               RET Z                           ; 5C04 C8
               LD A,&73                        ; 5C05 3E 73
               JR PTHP                         ; 5C07 18 F5  MAKE IT PLURAL UNLESS ONLY 1 FILE

;; --------------------------------------------------------------------
;; PDIRH -- &5C09 to &5C15
;;
;; Takes:     DE
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls PNDNM, PNCR, PRINT_B_CHARACTERS, GPATD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- PDIRH ---- from &4B4F when bit 2 of (IX+&04) set, &5B7B
PDIRH:
               CALL PNCR                       ; 5C09 CD FC 5B
               CALL PNDNM                      ; 5C0C CD 98 58  PRINT DISC NAME
               CALL GPATD                      ; 5C0F CD 10 74  GET BC=LEN, HL=START OF PATH DATA
               LD B,C                          ; 5C12 41
               CALL PRINT_B_CHARACTERS         ; 5C13 CD 1B 5C  PRINT B FROM HL

;; --------------------------------------------------------------------
;; PDIRH_1 -- &5C16 to &5C1A
;;
;; Takes:     nothing in registers
;; Leaves:    A
;; Ends:      JR
;;
;; ? calls PNCR.
;; --------------------------------------------------------------------

; ---- PDIRH_1 ---- from &6B13, &6D74
PDIRH_1:
               CALL PNCR                       ; 5C16 CD FC 5B
               JR PNCR                         ; 5C19 18 E1

;; --------------------------------------------------------------------
;; PRINT_B_CHARACTERS -- &5C1B to &5C22
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      RET
;;
;; ? calls PRINT_A_KEEPING_IT.
;;
;; Shown for this routine in disasm/:
;;
;;     B characters from HL, each through PRINT_A_KEEPING_IT.
;; --------------------------------------------------------------------

; ---- PRINT_B_CHARACTERS ---- from &58EA, &5C13, &5C20 when B is not 0 yet
PRINT_B_CHARACTERS:
               LD A,(HL)                       ; 5C1B 7E
               INC HL                          ; 5C1C 23
               CALL PRINT_A_KEEPING_IT         ; 5C1D CD 66 57
               DJNZ PRINT_B_CHARACTERS         ; 5C20 10 F9
               RET                             ; 5C22 C9

;; --------------------------------------------------------------------
;; ZDVS -- &5C23 to &5C2F
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- ZDVS ---- from &5B6D, &7993
ZDVS:
               LD HL,&0000                     ; 5C23 21 00 00
               LD (CNT),HL                     ; 5C26 22 0E 41  ZERO "SECTORS USED" COUNTER
               LD (TCNT),HL                    ; 5C29 22 1A 42  ZERO "FILES ON DISC" COUNTER
               LD (FCNT),HL                    ; 5C2C 22 1C 42  ZERO "FILES IN DIR" COUNTER
               RET                             ; 5C2F C9

;; --------------------------------------------------------------------
;; DITOB -- &5C30 to &5C3D
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, HL
;; Ends:      JP
;;
;; ? calls GETSCR.
;; --------------------------------------------------------------------

; ---- DITOB ---- from &5B75, &7930, &7996
DITOB:
               CALL GETSCR                     ; 5C30 CD 2C 49
               LD HL,&A000                     ; 5C33 21 00 A0
               LD (PTRSCR),HL                  ; 5C36 22 2C 41  INIT BUFFER PTR
               LD A,&02                        ; 5C39 3E 02
               JP FDHR                         ; 5C3B C3 31 4B  SIMPLE DIR TO SCREEN BUFFER

;; --------------------------------------------------------------------
;; STATS -- &5C3E to &5C52
;;
;; Takes:     HL
;; Leaves:    A, F, BC, HL
;;
;; ? calls TSTD, TIRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      STATS -- free sectors and free directory slots
;;
;;      The capacity is derived from the track count, which is why the double-sided and RAM disc cases are adjusted
;;      separately: a RAM disc reports its tracks differently from a real one. The sectors already used were counted by
;;      FDHR during the scan.
;;
;;      Exit:   HL = free sectors, DE = free directory slots
;;
;;     GET HL=FREE SECTS, DE=FREE SLOTS
;; --------------------------------------------------------------------

; ---- STATS ---- from &5BC9, &7999
STATS:
               CALL TSTD                       ; 5C3E CD F4 4A  TRACKS TO A
               LD C,A                          ; 5C41 4F
               LD A,(DTKS)                     ; 5C42 3A 30 42
               LD B,A                          ; 5C45 47
               CALL TIRD                       ; 5C46 CD 5A 61  CY IF NOT RAM DISC
               LD A,C                          ; 5C49 79
               BIT 7,A                         ; 5C4A CB 7F
               JR Z,TRK0                       ; 5C4C 28 06  JR IF SINGLE SIDED
               JR C,TRKM1                      ; 5C4E 38 03  JR IF NORMAL DISK
               SUB &30                         ; 5C50 D6 30  E.G 130->82, 168->120
               DEFB SKIP_1_VIA_CP              ; 5C52 ~  "JR+1"

;; --------------------------------------------------------------------
;; TRKM1 -- &5C53 to &5C53
;;
;; Takes:     A
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- TRKM1 ---- from &5C4E
TRKM1:
               ADD A,A                         ; 5C53 87  *2 FOR DOUBLE-SIDED NORMAL.

;; --------------------------------------------------------------------
;; TRK0 -- &5C54 to &5C5B
;;
;; Takes:     A, B
;; Leaves:    A, F, B, DE, HL
;; --------------------------------------------------------------------

; ---- TRK0 ---- from &5C4C when bit 7 of A clear
TRK0:
               SUB B                           ; 5C54 90  NUMBER OF NON-DIRECTORY TRACKS
               LD HL,&0000                     ; 5C55 21 00 00
               LD B,&0A                        ; 5C58 06 0A  10 SECTS/TRK
               LD D,H                          ; 5C5A 54
               LD E,A                          ; 5C5B 5F

;; --------------------------------------------------------------------
;; TRKL -- &5C5C to &5C66
;;
;; Takes:     B, DE, HL
;; Leaves:    A, F, B, HL
;; --------------------------------------------------------------------

; ---- TRKL ---- from &5C5D when B is not 0 yet
TRKL:
               ADD HL,DE                       ; 5C5C 19  CALC SECTORS FOR DATA
               DJNZ TRKL                       ; 5C5D 10 FD
               LD A,(DTKS)                     ; 5C5F 3A 30 42
               CP &05                          ; 5C62 FE 05
               JR C,TRK1                       ; 5C64 38 01
               INC HL                          ; 5C66 23  ALLOW FOR UNUSED T4/S1 GIVING

;; --------------------------------------------------------------------
;; TRK1 -- &5C67 to &5C7F
;;
;; Takes:     A, HL
;; Leaves:    A, F, C, DE, HL
;; --------------------------------------------------------------------

; ---- TRK1 ---- from &5C64 when A < &05
TRK1:
               LD DE,(CNT)                     ; 5C67 ED 5B 0E 41
               AND A                           ; 5C6B A7
               SBC HL,DE                       ; 5C6C ED 52
               PUSH HL                         ; 5C6E E5  FREE SECTS
               LD A,(DTKS)                     ; 5C6F 3A 30 42
               LD C,A                          ; 5C72 4F
               ADD A,A                         ; 5C73 87  *2
               ADD A,A                         ; 5C74 87  *4
               ADD A,C                         ; 5C75 81  *5 (5-195)
               LD L,A                          ; 5C76 6F
               LD H,&00                        ; 5C77 26 00
               ADD HL,HL                       ; 5C79 29  *10
               LD A,C                          ; 5C7A 79
               CP &05                          ; 5C7B FE 05
               JR C,PCT2                       ; 5C7D 38 01  JR IF 4-TRACK DIR
               DEC HL                          ; 5C7F 2B  ALLOW FOR 2 UNUSABLE T4/S1 ENTRIES

;; --------------------------------------------------------------------
;; PCT2 -- &5C80 to &5C8A
;;
;; Takes:     A, HL
;; Leaves:    A, F, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- PCT2 ---- from &5C7D when A < &05
PCT2:
               ADD HL,HL                       ; 5C80 29  *20
               LD DE,(TCNT)                    ; 5C81 ED 5B 1A 42  FILES ON DISC
               AND A                           ; 5C85 A7
               SBC HL,DE                       ; 5C86 ED 52  ALL SLOTS-FILES=FREE SLOTS
               EX DE,HL                        ; 5C88 EB
               POP HL                          ; 5C89 E1
               RET                             ; 5C8A C9

;; --------------------------------------------------------------------
;; COLUMNS_FOR_DIRECTORY -- &5C8B to &5CA2
;;
;; Takes:     DE, HL
;; Leaves:    A, F, B, HL
;;
;; ? reaches the ROM through SYS_CHAR_WIDTH; calls NRRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     How many columns a directory listing gets: DCOLS if it is set, and
;;     otherwise MasterBASIC's SYS_CHAR_WIDTH read out of the system page --
;;     so a narrower character size gives a wider listing.
;; --------------------------------------------------------------------

; ---- COLUMNS_FOR_DIRECTORY ---- from &5BA1
COLUMNS_FOR_DIRECTORY:
               LD A,(DCOLS)                    ; 5C8B 3A 28 42
               LD B,A                          ; 5C8E 47
               AND A                           ; 5C8F A7
               RET NZ                          ; 5C90 C0  RET IF FIXED NUMBER ELSE
                                               ; read the ROM variable SYS_CHAR_WIDTH -- the word below is its address,
                                               ; and the call returns past it
               CALL NRRD                       ; 5C91 CD 5E 50
               DEFW SYS_CHAR_WIDTH             ; 5C94 EE 4A
               AND A                           ; 5C96 A7
               LD A,&00                        ; 5C97 3E 00
               JR NZ,COLUMNS_FOR_DIRECTORY_1   ; 5C99 20 08
                                               ; read the ROM variable WINDRHS -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 5C9B CD 53 50
               DEFW WINDRHS                    ; 5C9E 56 5A
               LD A,C                          ; 5CA0 79
               SUB B                           ; 5CA1 90
               INC A                           ; 5CA2 3C  WINDOW WIDTH (NORMALLY 32, 64 OR 85)

;; --------------------------------------------------------------------
;; COLUMNS_FOR_DIRECTORY_1 -- &5CA3 to &5CA9
;;
;; Takes:     A
;; Leaves:    A, F, B
;; --------------------------------------------------------------------

; ---- COLUMNS_FOR_DIRECTORY_1 ---- from &5C99 when A <> 0
COLUMNS_FOR_DIRECTORY_1:
               LD B,&01                        ; 5CA3 06 01
               SUB &0B                         ; 5CA5 D6 0B
               RET C                           ; 5CA7 D8
               INC A                           ; 5CA8 3C
               DEC B                           ; 5CA9 05

;; --------------------------------------------------------------------
;; COLBL -- &5CAA to &5CAF
;;
;; Takes:     A, B
;; Leaves:    A, F, B
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- COLBL ---- from &5CAD when A >= &0B
COLBL:
               INC B                           ; 5CAA 04  COUNT NAMES THAT WILL FIT ACROSS
               SUB &0B                         ; 5CAB D6 0B  NAME LEN, INC SPACE
               JR NC,COLBL                     ; 5CAD 30 FB
               RET                             ; 5CAF C9

;; --------------------------------------------------------------------
;; OVERO -- &5CB0 to &5CB5
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GTNC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OVERO ---- from &5CD0
OVERO:
               CALL GTNC                       ; 5CB0 CD 3C 50
               CP &A6                          ; 5CB3 FE A6  OVER
               RET NZ                          ; 5CB5 C0

;; --------------------------------------------------------------------
;; SF1S -- &5CB6 to &5CBA
;;
;; Takes:     HL
;; Leaves:    HL
;; Ends:      JP, JR
;;
;; ? calls SETF1.
;; --------------------------------------------------------------------

; ---- SF1S ---- from &5E33 when A = &89
SF1S:
               CALL SETF1                      ; 5CB6 CD F2 50
               JR GTNCH                        ; 5CB9 18 12

;; --------------------------------------------------------------------
;; REDIR -- &5CBB to &5CBD
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GTNC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- REDIR ---- from &5D4F
REDIR:
               CALL GTNC                       ; 5CBB CD 3C 50

;; --------------------------------------------------------------------
;; REDI2 -- &5CBE to &5CC5
;;
;; Takes:     A, HL
;; Leaves:    F, HL
;; Ends:      JP, JR
;;
;; ? calls SETF4.
;; --------------------------------------------------------------------

; ---- REDI2 ---- from &5CD3
REDI2:
               CP &90                          ; 5CBE FE 90  "DIR"
               RET NZ                          ; 5CC0 C0
               CALL SETF4                      ; 5CC1 CD 04 51
               JR GTNCH                        ; 5CC4 18 07  SKIP "DIR"

;; --------------------------------------------------------------------
;; ALLSR -- &5CC6 to &5CCC
;;
;; Takes:     A
;; Leaves:    A, F
;;
;; Shown for this routine in disasm/:
;;
;;     ALLOW "?" TO MEAN "ALL FILES"
;;      Setting CDIRT to &FF makes the directory scan accept files from every subdirectory rather than only the current
;;      one.
;; --------------------------------------------------------------------

; ---- ALLSR ---- from &5B1B, &5B48, &5B52, &7922
ALLSR:
               SUB &3F                         ; 5CC6 D6 3F
               RET NZ                          ; 5CC8 C0
               DEC A                           ; 5CC9 3D
               LD (CDIRT),A                    ; 5CCA 32 31 42  CDIRT=FF

;; --------------------------------------------------------------------
;; GTNCH -- &5CCD to &5CCF
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- GTNCH ---- from &5CB9, &5CC4
GTNCH:
               JP GTNC                         ; 5CCD C3 3C 50  SKIP "?"

;; --------------------------------------------------------------------
;; ERAZ -- &5CD0 to &5CDB
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls NMQU, OVERO, REDI2, EVFINS; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      ERAZ -- ERASE
;;
;;      Deletes every matching file by zeroing the first byte of its entry. A protected file is skipped with a beep
;;      unless
;;      OVER was given, and the fact that one was met is remembered so that "protected file" can be reported if nothing
;;      else was erased.
;;
;;      ERASE DIR deletes a subdirectory, but only if it is empty: the directory's own tag is put into CDIRT and the
;;      catalogue searched for any file carrying it.
;;
;;      Errors: REP33 "directory not empty", REP36 "protected file", REP26 "file not found"
;;
;;     ERASE A FILE
;; --------------------------------------------------------------------

ERAZ:
               CALL OVERO                      ; 5CD0 CD B0 5C
               CALL REDI2                      ; 5CD3 CD BE 5C
               CALL NMQU                       ; 5CD6 CD 90 59
               CALL EVFINS                     ; 5CD9 CD 21 73

;; --------------------------------------------------------------------
;; ERAZ3 -- &5CDC to &5CE3
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE, HL, IX
;;
;; ? calls SNDFX; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- ERAZ3 ---- from &5CE1, &5CE4, &5CF3, &5D1D, &5D25
ERAZ3:
               CALL SNDFX                      ; 5CDC CD 52 5E
               JR Z,ERAZ33                     ; 5CDF 28 03  JR IF FLAG=ERASE FILE, NOT DIR
               JR NC,ERAZ3                     ; 5CE1 30 F9  SKIP ERASE IF NOT DIR TYPE
               AND A                           ; 5CE3 A7  NC

;; --------------------------------------------------------------------
;; ERAZ33 -- &5CE4 to &5CEF
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;;
;; ? calls BITF1; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- ERAZ33 ---- from &5CDF
ERAZ33:
               JR C,ERAZ3                      ; 5CE4 38 F6  SKIP RENAME IF DIR TYPE
               LD A,(HL)                       ; 5CE6 7E
               CALL BITF1                      ; 5CE7 CD 22 51
               JR NZ,ERAZ45                    ; 5CEA 20 04  JR IF "ERASE OVER"
               BIT 6,A                         ; 5CEC CB 77
               JR NZ,ERAZ33_1                  ; 5CEE 20 2F  JR IF PROTECTED

;; --------------------------------------------------------------------
;; ERAZ45 -- &5CF0 to &5D17
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls FDHR, OHASR, PTSVT, CALL_ROM_66CB; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- ERAZ45 ---- from &5CEA
ERAZ45:
               CALL OHASR                      ; 5CF0 CD 2F 5D
               JR NZ,ERAZ3                     ; 5CF3 20 E7  JR IF "?" AND "N"
               CALL CALL_ROM_66CB              ; 5CF5 CD 70 5E
               JR Z,ERAZ46                     ; 5CF8 28 1E  JR IF ERASE FILE, NOT DIR
               LD BC,DIRT                      ; 5CFA 01 FA 00
               ADD HL,BC                       ; 5CFD 09
               LD A,(HL)                       ; 5CFE 7E
               LD (CDIRT+1),A                  ; 5CFF 32 32 42  SET TEMP DIR TO SUBJECT OF
               CALL EXDAT                      ; 5D02 CD 43 62  SAVE CURRENT FILE DETAILS
               LD L,&2A                        ; 5D05 2E 2A
               LD (NSTR1+1),HL                 ; 5D07 22 3B 41  H CANNOT BE "." (2EH) SO NAME
               LD A,&10                        ; 5D0A 3E 10  FIND FILE, IGNORE TYPE
               CALL FDHR                       ; 5D0C CD 31 4B  FIND ANY FILE IN THIS DIRECTORY
               JP Z,REP33                      ; 5D0F CA 98 51  "DIRECTORY NOT EMPTY" IF A FILE
               CALL EXDAT                      ; 5D12 CD 43 62  ORIG CDIRT AND NAME BACK
               CALL PTSVT                      ; 5D15 CD CF 5D  LOAD AND POINT TO DIR FILE ENTRY

;; --------------------------------------------------------------------
;; ERAZ46 -- &5D18 to &5D1E
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR
;;
;; ? calls WSAD, FDHR, BITF1, OHASR.
;; --------------------------------------------------------------------

; ---- ERAZ46 ---- from &5CF8
ERAZ46:
               LD (HL),&00                     ; 5D18 36 00
               CALL WSAD                       ; 5D1A CD 86 45
               JR ERAZ3                        ; 5D1D 18 BD

;; --------------------------------------------------------------------
;; ERAZ33_1 -- &5D1F to &5D26
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR
;;
;; ? calls WSAD, FDHR, BEEP, SETF3.
;; --------------------------------------------------------------------

; ---- ERAZ33_1 ---- from &5CEE when bit 6 of A set
ERAZ33_1:
               CALL BEEP                       ; 5D1F CD E1 4D
               CALL SETF3                      ; 5D22 CD FE 50  "TRIED TO ERASE PROTECTED FILE"
               JR ERAZ3                        ; 5D25 18 B5

;; --------------------------------------------------------------------
;; WRITE_BYTE_IF_OPEN -- &5D27 to &5D2E
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, IY
;; Ends:      JP
;;
;; ? calls OHASR.
;;
;; Shown for this routine in disasm/:
;;
;;     Check the channel is open through OHASR, and if it is, store A and
;;     leave for WSAD to write the sector.
;; --------------------------------------------------------------------

; ---- WRITE_BYTE_IF_OPEN ---- from &5E4D
WRITE_BYTE_IF_OPEN:
               CALL OHASR                      ; 5D27 CD 2F 5D
               RET NZ                          ; 5D2A C0  RET IF "?" OPTION AND "N"
               LD (HL),A                       ; 5D2B 77  ERASED/PROTECTED/HIDDEN
               JP WSAD                         ; 5D2C C3 86 45

;; --------------------------------------------------------------------
;; OHASR -- &5D2F to &5D43
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, IY
;; Preserves: DE, HL (saved and restored)
;; Ends:      RET
;;
;; ? calls SETF0, BITF7, OHNM, FNMAE.
;; --------------------------------------------------------------------

; ---- OHASR ---- from &59FE, &5CF0, &5D27, &5D8F
OHASR:
               CALL SETF0                      ; 5D2F CD EC 50  "GOT ONE"
               CALL BITF7                      ; 5D32 CD 40 51
               RET Z                           ; 5D35 C8  RET IF NOT "?" OPTION
               PUSH AF                         ; 5D36 F5
               PUSH DE                         ; 5D37 D5
               PUSH HL                         ; 5D38 E5
               CALL OHNM                       ; 5D39 CD D1 58  CMD NAME
               CALL FNMAE                      ; 5D3C CD FE 58  FILE NAME, Y/N/A/E, KEY.
               POP HL                          ; 5D3F E1  Z IF YES OR ALL
               POP DE                          ; 5D40 D1
               POP BC                          ; 5D41 C1
               LD A,B                          ; 5D42 78
               RET                             ; 5D43 C9  Z IF YES

;; --------------------------------------------------------------------
;; CKDIR -- &5D44 to &5D4E
;;
;; Takes:     HL
;; Leaves:    A, F, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CKDIR ---- from &5EA7
CKDIR:
               INC H                           ; 5D44 24
               DEC HL                          ; 5D45 2B
               DEC HL                          ; 5D46 2B
               LD A,(CDIRT)                    ; 5D47 3A 31 42
               CP &FF                          ; 5D4A FE FF
               RET Z                           ; 5D4C C8  RET IF "MATCH ANY"
               CP (HL)                         ; 5D4D BE
               RET                             ; 5D4E C9

;; --------------------------------------------------------------------
;; RENAM -- &5D4F to &5D6F
;;
;; Takes:     A, BC, DE, HL, IX, R
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls READ_SECTOR, CLEAR_TRANSFER_COUNT, GRPNTB, CEOS; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      RENAM -- RENAME
;;
;;      RENAME TO "name" renames the disk itself, which means rewriting the name field of the first directory entry and
;;      giving the disk a fresh random word so that anything caching its identity notices the change.
;;
;;      Otherwise it is file to file, with the target acting as a template: TRX0 applies it to each matching name, so
;;      wildcards rename in bulk.
;;
;;      Errors: REP28 if the new name is already in use
;;
;;     RENAME A FILE
;; --------------------------------------------------------------------

RENAM:
               CALL REDIR                      ; 5D4F CD BB 5C  SKIP ANY "DIR", SET FLAG4
               CP &8E                          ; 5D52 FE 8E  "TO"
               JR NZ,RENM1                     ; 5D54 20 1D
               CALL EVNAMX                     ; 5D56 CD CC 61
               CALL CEOS                       ; 5D59 CD 07 50
               CALL EVFINS                     ; 5D5C CD 21 73
               LD DE,&0001                     ; 5D5F 11 01 00
               CALL READ_SECTOR                ; 5D62 CD B7 45
               CALL CLEAR_TRANSFER_COUNT       ; 5D65 CD 8E 4F
               LD B,&FF                        ; 5D68 06 FF
               CALL GRPNTB                     ; 5D6A CD AE 4F
               CALL FESE2                      ; 5D6D CD F8 55  COPY NAME, NEW RND NO.

;; --------------------------------------------------------------------
;; NWSADH -- &5D70 to &5D72
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      JP
;; --------------------------------------------------------------------

NWSADH:
               JP WSAD                         ; 5D70 C3 86 45

;; --------------------------------------------------------------------
;; RENM1 -- &5D73 to &5D81
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CKDRX, EVAL_NAME_PAIR, COBUS, N2TN3; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- RENM1 ---- from &5D54 when A <> &8E
RENM1:
               CALL EVAL_NAME_PAIR             ; 5D73 CD 7B 59
               CALL COBUS                      ; 5D76 CD A0 59
               CALL N2TN3                      ; 5D79 CD DB 5D  COPY 2ND NAME TO TEMPLATE AREA
               LD A,(DSTR1)                    ; 5D7C 3A 36 41  FIRST FILE DRIVE
               CALL CKDRX                      ; 5D7F CD 0A 48  SO E.G. RENAME "D2:ASD"

;; --------------------------------------------------------------------
;; RENM2 -- &5D82 to &5D8C
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE, HL, IX
;;
;; ? calls REFBUF, SNDFX; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- RENM2 ---- from &5D8A, &5D8D, &5D92, &5DC2
RENM2:
               CALL REFBUF                     ; 5D82 CD C4 5D  REFRESH BUFFER
               CALL SNDFX                      ; 5D85 CD 52 5E  FIND 1ST NAME FILE
               JR Z,RENM3                      ; 5D88 28 03  JR IF FLAG= RENAME FILE, NOT DIR
               JR NC,RENM2                     ; 5D8A 30 F6  SKIP RENAME IF NOT DIR TYPE
               AND A                           ; 5D8C A7  NC

;; --------------------------------------------------------------------
;; RENM3 -- &5D8D to &5DC3
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR
;;
;; ? calls WSAD, FINDC, SETF0, OHASR.
;; --------------------------------------------------------------------

; ---- RENM3 ---- from &5D88
RENM3:
               JR C,RENM2                      ; 5D8D 38 F3  SKIP RENAME IF DIR TYPE
               CALL OHASR                      ; 5D8F CD 2F 5D
               JR NZ,RENM2                     ; 5D92 20 EE  JR IF "?" AND "N"
               PUSH HL                         ; 5D94 E5
               CALL EXDAT                      ; 5D95 CD 43 62  FIRST FILE NAME TO NSTR2
               POP HL                          ; 5D98 E1
               CALL TRX0                       ; 5D99 CD E9 62  COPY LOADED NAME TO NSTR1,
               CALL FINDC                      ; 5D9C CD A7 4F  USE TEMPLATE ON IT
               JP Z,REP28                      ; 5D9F CA 8C 51  "FILE NAME USED"
               CALL PTSVT                      ; 5DA2 CD CF 5D  PT TO FIRST FILE ENTRY AGAIN
               PUSH DE                         ; 5DA5 D5  T/S
               PUSH HL                         ; 5DA6 E5
               INC H                           ; 5DA7 24
               DEC HL                          ; 5DA8 2B
               DEC HL                          ; 5DA9 2B  SUB DIR TAG
               LD A,(CDIRT)                    ; 5DAA 3A 31 42  SUB DIR VALUE FOR 2ND NAME
               LD (HL),A                       ; 5DAD 77  SET SUB DIR TAG
               POP DE                          ; 5DAE D1
               INC DE                          ; 5DAF 13  NAME POSN
               LD HL,NSTR1+1                   ; 5DB0 21 3B 41
               LD BC,&000A                     ; 5DB3 01 0A 00
               LDIR                            ; 5DB6 ED B0
               POP DE                          ; 5DB8 D1  T/S
               CALL WSAD                       ; 5DB9 CD 86 45
               CALL SETF0                      ; 5DBC CD EC 50  "DONE ONE"
               CALL EXDAT                      ; 5DBF CD 43 62
               JR RENM2                        ; 5DC2 18 BE

;; --------------------------------------------------------------------
;; REFBUF -- &5DC4 to &5DC7
;;
;; Takes:     HL
;; Leaves:    F, HL
;;
;; ? calls BITF2; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      REFBUF / PTSVT -- re-read the directory sector and point back at the entry the search stopped on. Needed because
;;      the caller writes the entry back between finds, so the buffer cannot be trusted to still hold it.
;; --------------------------------------------------------------------

; ---- REFBUF ---- from &59F1, &5D82
REFBUF:
               CALL BITF2                      ; 5DC4 CD 28 51
               RET Z                           ; 5DC7 C8  RET IF SNDFL NOT USED YET

;; --------------------------------------------------------------------
;; RFB2 -- &5DC8 to &5DCE
;;
;; Takes:     nothing in registers
;; Leaves:    DE
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- RFB2 ---- from &5DCF
RFB2:
               LD DE,(SVTRS)                   ; 5DC8 ED 5B 24 41
               JP READ_SECTOR                  ; 5DCC C3 B7 45  ENSURE DRAM CONTAINS DIR ENTRIES

;; --------------------------------------------------------------------
;; PTSVT -- &5DCF to &5DDA
;;
;; Takes:     IX
;; Leaves:    A, DE
;; Ends:      JP
;;
;; ? calls RFB2.
;;
;; Shown for this routine in disasm/:
;;
;;     IN CASE 2ND ONE WANTED
;;     PT TO SVTRS ENTRY
;; --------------------------------------------------------------------

; ---- PTSVT ---- from &5D15, &5DA2
PTSVT:
               CALL RFB2                       ; 5DCF CD C8 5D
               LD A,(SVDPT)                    ; 5DD2 3A 22 41
               LD (IX+&0E),A                   ; 5DD5 DD 77 0E
               JP POINT                        ; 5DD8 C3 AC 4F

;; --------------------------------------------------------------------
;; N2TN3 -- &5DDB to &5DE6
;;
;; Takes:     nothing in registers
;; Leaves:    F, BC, DE, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- N2TN3 ---- from &59DB, &5D79
N2TN3:
               LD HL,NSTR2+1                   ; 5DDB 21 57 41
               LD DE,NSTR3+1                   ; 5DDE 11 6F 41
               LD BC,&000E                     ; 5DE1 01 0E 00
               LDIR                            ; 5DE4 ED B0
               RET                             ; 5DE6 C9

;; --------------------------------------------------------------------
;; CMD_PROTECT -- &5DE7 to &5DF0
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR
;;
;; ? calls GTNC, BITF1, NMQU, SF1S.
;; --------------------------------------------------------------------

CMD_PROTECT:
               LD A,&40                        ; 5DE7 3E 40
               LD (HSTR1),A                    ; 5DE9 32 35 41
               CALL GTNC                       ; 5DEC CD 3C 50
               JR CMD_HIDE_3                   ; 5DEF 18 40

;; --------------------------------------------------------------------
;; CMD_HIDE -- &5DF1 to &5E0C
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JR
;;
;; ? calls CEOS, GTNC, NRWRD, EVNUMX.
;; --------------------------------------------------------------------

CMD_HIDE:
               LD A,&80                        ; 5DF1 3E 80
               LD (HSTR1),A                    ; 5DF3 32 35 41
               CALL GTNC                       ; 5DF6 CD 3C 50
               CP &8E                          ; 5DF9 FE 8E
               JR NZ,CMD_HIDE_3                ; 5DFB 20 34
