;; --------------------------------------------------------------------
;; CMD_HIDE_1 -- &5E0D to &5E21
;;
;; Takes:     BC, DE, HL
;; Leaves:    F, BC, DE, HL, IY
;;
;; ? reaches the ROM through MB_FIND_LINE_FROM_START-&4000; calls CALLMB; falls into whatever follows rather than
;; returning.
;; --------------------------------------------------------------------

; ---- CMD_HIDE_1 ---- from &5E05
CMD_HIDE_1:
               INC B                              ; 5E0D 04
               JP Z,AHLNX_1                       ; 5E0E CA 91 60
