               INC HL                             ; 5E1C 23
               LD C,(HL)                          ; 5E1D 4E
               INC HL                             ; 5E1E 23
               LD B,(HL)                          ; 5E1F 46
               INC HL                             ; 5E20 23
               ADD HL,BC                          ; 5E21 09

;; --------------------------------------------------------------------
;; CMD_HIDE_2 -- &5E22 to &5E30
;;
;; Takes:     DE, HL
;; Leaves:    A, F, BC, HL
