               LD (HD001),A                    ; 63A1 32 49 41
               LD A,(UIFA+31)                  ; 63A4 3A 9C 41
               LD (PAGE1),A                    ; 63A7 32 51 41
               LD HL,(UIFA+32)                 ; 63AA 2A 9D 41
               LD (HD0D1),HL                   ; 63AD 22 4C 41
               LD A,(UIFA+34)                  ; 63B0 3A 9F 41
               AND &1F                         ; 63B3 E6 1F
               LD (PGES1),A                    ; 63B5 32 50 41
               LD HL,(UIFA+35)                 ; 63B8 2A A0 41
               RES 7,H                         ; 63BB CB BC
               LD (UIFA+35),HL                 ; 63BD 22 A0 41
               LD (HD0B1),HL                   ; 63C0 22 4A 41
