;; --------------------------------------------------------------------
;; TXHED -- &63D3 to &63E1
;;
;; Takes:     IX
;; Leaves:    A, F, BC, HL
;;
;; ? calls RDA; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      TXHED / TXRM / RXHSR -- copy a header to or from the ROM's buffer
;;
;;      UIFA goes to the ROM's HDR and DIFA to HDL, eighty bytes further on, exactly as SAMDOS does. One byte needs
;;      care:
;;      bit 7 of the length's high byte is sometimes set and sometimes not in the ROM's copy, and VERIFY compares the
;;      two
;;      headers for equality, so that bit is taken from the ROM's version rather than overwritten.
;;
;;      The buffer may be in the system page, which is mapped in for the copy when the address says so.
;;
;;     OUTPUT DIFA TO ROMDIFA (DIFA TO IX+80)
;; --------------------------------------------------------------------

; ---- TXHED ---- from &6051
TXHED:
               PUSH IX                         ; 63D3 DD E5
               POP HL                          ; 63D5 E1
               PUSH HL                         ; 63D6 E5
               LD BC,&0024                     ; 63D7 01 24 00
               ADD HL,BC                       ; 63DA 09  IX+24H
               CALL RDA                        ; 63DB CD C9 50  MSB OF LEN MOD 16K (HDR) TO A
               LD HL,DIFA+&24                  ; 63DE 21 D1 41
               XOR (HL)                        ; 63E1 AE

;; --------------------------------------------------------------------
;; TXHED_1 -- &63E2 to &63EB
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE
;; --------------------------------------------------------------------

; ---- TXHED_1 ---- from &6DFD
TXHED_1:
               AND &80                         ; 63E2 E6 80  TAKE BIT 7 FROM HDR
               XOR (HL)                        ; 63E4 AE  VERIFY DEPENDS ON EQUALIT
               LD (HL),A                       ; 63E5 77
               LD DE,DIFA                      ; 63E6 11 AD 41
               LD BC,&0050                     ; 63E9 01 50 00

;; --------------------------------------------------------------------
;; TXRM -- &63EC to &63EF
;;
;; Takes:     BC, DE
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JR, RET
;;
;; ? drives IN A,(HMPR), OUT (C),B.
;; --------------------------------------------------------------------

; ---- TXRM ---- from &6388
TXRM:
               POP HL                          ; 63EC E1  WAS IX
               ADD HL,BC                       ; 63ED 09  NC. DEST IN HL=IX OR IX+80
               JR RXTXC                        ; 63EE 18 07

;; --------------------------------------------------------------------
;; RXHSR -- &63F0 to &63F6
;;
;; Takes:     IX
;; Leaves:    F, DE, HL
;; --------------------------------------------------------------------

; ---- RXHSR ---- from &633D
RXHSR:
               LD DE,UIFA                      ; 63F0 11 7D 41
               PUSH IX                         ; 63F3 DD E5
               POP HL                          ; 63F5 E1  SRC=HL, DEST=UIFA
               SCF                             ; 63F6 37

;; --------------------------------------------------------------------
;; RXTXC -- &63F7 to &6405
;;
;; Takes:     H
;; Leaves:    A, F, BC, H
;;
;; ? drives IN A,(HMPR), OUT (C),B; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- RXTXC ---- from &63EE
RXTXC:
               BIT 7,H                         ; 63F7 CB 7C
               IN A,(HMPR)                     ; 63F9 DB FB
               LD BC,&00FB                     ; 63FB 01 FB 00
               JR NZ,RXH1                      ; 63FE 20 06  JR IF NO PAGING REQUIRED
                                               ; HMPR is 0, so setting bit 7 and clearing bit 6 turns an address in
                                               ; &4000-&7FFF into the same byte of the ROM's system page at &8000-&BFFF
               SET 7,H                         ; 6400 CB FC
               RES 6,H                         ; 6402 CB B4
               OUT (C),B                       ; 6404 ED 41  SYSTEM PAGE

