;; --------------------------------------------------------------------
;; FNLN2 -- &6597 to &6599
;;
;; Takes:     nothing in registers
;; Leaves:    A
;;
;; Shown for this routine in disasm/:
;;
;;      HEOF / HPTR / FNLN2 -- the EOF, PTR and LENGTH functions
;;
;;      All three share one body, told apart by the value pushed on entry: 0 for EOF, 1 for PTR, 2 for LENGTH. EOF is
;;      the
;;      only one that returns a truth value rather than a number, and does so by comparing the pointer with the length.
;; --------------------------------------------------------------------

FNLN2:
               LD A,&02                        ; 6597 3E 02
               DEFB SKIP_2_VIA_LD_HL           ; 6599 !  "JR+2"

;; --------------------------------------------------------------------
;; HPTR -- &659A to &659C
;;
;; Takes:     nothing in registers
;; Leaves:    A
;; --------------------------------------------------------------------

HPTR:
               LD A,&01                        ; 659A 3E 01
               DEFB SKIP_1_VIA_CP              ; 659C ~  "JR+1"

;; --------------------------------------------------------------------
;; HEOF -- &659D to &65B4
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;; Preserves: IX (saved and restored)
;; Ends:      JP, JR
;;
;; ? drives IN B,(C), OUT (C),B; calls GET_STREAM_NUMBER, GLEN.
;; --------------------------------------------------------------------

HEOF:
               XOR A                           ; 659D AF
               PUSH IX                         ; 659E DD E5
               LD C,HMPR                       ; 65A0 0E FB
               IN B,(C)                        ; 65A2 ED 40
               PUSH BC                         ; 65A4 C5
               PUSH AF                         ; 65A5 F5  0 IF EOF, 1 IF PTR
               CALL GET_STREAM_NUMBER          ; 65A6 CD 0B 70  AHL=PTR
               POP DE                          ; 65A9 D1
               DEC D                           ; 65AA 15
               JR Z,EPCOM                      ; 65AB 28 12  JR IF PTR
               DEC D                           ; 65AD 15
               JR NZ,HEOF2                     ; 65AE 20 05
               CALL GLEN                       ; 65B0 CD D4 71  GET FILE LEN IN AHL
               JR EPCOM                        ; 65B3 18 0A

;; --------------------------------------------------------------------
;; HEOF2 -- &65B5 to &65BE
;;
;; Takes:     IX
;; Leaves:    A, F, BC, HL
;;
;; ? calls CPPTR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- HEOF2 ---- from &65AE when D is not 0 yet
HEOF2:
               CALL CPPTR                      ; 65B5 CD DC 6F
               LD HL,&0000                     ; 65B8 21 00 00
               LD A,H                          ; 65BB 7C
               JR NZ,EPCOM                     ; 65BC 20 01
               INC HL                          ; 65BE 23  HL=1, EOF=TRUE

;; --------------------------------------------------------------------
;; EPCOM -- &65BF to &65C3
;;
;; Takes:     nothing in registers
;; Leaves:    BC, IX
;;
;; ? drives OUT (C),B; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- EPCOM ---- from &65AB when D reaches 0, &65B3, &65BC
EPCOM:
               POP BC                          ; 65BF C1
               OUT (C),B                       ; 65C0 ED 41
               POP IX                          ; 65C2 DD E1

;; --------------------------------------------------------------------
;; EPCOM_1 -- &65C4 to &65CD
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JP, JR
;; --------------------------------------------------------------------

; ---- EPCOM_1 ---- from &79C7, &7B64
EPCOM_1:
               LD B,A                          ; 65C4 47
               OR H                            ; 65C5 B4
               OR L                            ; 65C6 B5
               JR Z,EPCOM_2                    ; 65C7 28 05  ZERO IS A SPECIAL CASE
               LD A,B                          ; 65C9 78
               LD B,&98                        ; 65CA 06 98  INIT EXPONENT
               JR HVAR1                        ; 65CC 18 B4

;; --------------------------------------------------------------------
;; EPCOM_2 -- &65CE to &65F0
;;
;; Takes:     HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JP, JR
;; --------------------------------------------------------------------

; ---- EPCOM_2 ---- from &65C7, &79A7, &79E2, &7B4B
EPCOM_2:
               LD A,H                          ; 65CE 7C
               LD H,L                          ; 65CF 65
               LD L,A                          ; 65D0 6F
               XOR A                           ; 65D1 AF
               LD E,A                          ; 65D2 5F
               JR HVAR1_1                      ; 65D3 18 B8

;; --------------------------------------------------------------------
;; MasterBASIC changed this routine: only 8 of the 12
;; instructions stock MasterDOS 2.3 has in AUTNAM survive
;; here, so that version's description of it has been
;; left out rather than carried across.  Compare
;; ref/masterdos/annotated-src/masterdos23.asm.
;; --------------------------------------------------------------------

AUTNAM:
               DEFB &01,&FF,&FF,&44,&10,&41,&55,&54,&4F,&2A,&20,&20,&20,&20,&20 ; 65D5 ...D.AUTO*
               DEFB &20,&20,&20,&20,&00,&FF,&FF,&FF,&FF,&FF,&FF,&FF,&FF         ; 65E4     .........

;; --------------------------------------------------------------------
;; HAUTO -- &65F1 to &65F6
;;
;; Takes:     DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? calls AUINSR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     LOOK FOR AN AUTO FILE
;;      HAUTO reports if there is none; INIT, which is the boot hook, simply returns so that booting a disk without an
;;      auto-load file is not an error.
;; --------------------------------------------------------------------

HAUTO:
               CALL AUINSR                     ; 65F1 CD FD 65
               JP NZ,REP20                     ; 65F4 C2 7A 51  ERROR IF NOT FOUND

;; --------------------------------------------------------------------
;; AUINC -- &65F7 to &65FC
;;
;; Takes:     HL, IX
;; Leaves:    A, F, BC, DE, HL, IX, IY, I
;; Ends:      JP
;;
;; ? drives IN A,(HMPR), IN A,(LMPR); calls READ_SECTOR, HK_SKSAFE, ROOM_LEFT_IN_PAGE, CHECK_FILE_TYPE.
;; --------------------------------------------------------------------

; ---- AUINC ---- from &661E
AUINC:
               CALL CHECK_FILE_TYPE            ; 65F7 CD 75 4E
               JP CMD_LOAD_1                   ; 65FA C3 BB 5F

;; --------------------------------------------------------------------
;; AUINSR -- &65FD to &661F
;;
;; Takes:     DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? reaches the ROM through CURCMD; calls NRWR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- AUINSR ---- from &65F1
AUINSR:
               LD A,&95                        ; 65FD 3E 95  LOAD TOK
                                               ; write the ROM variable CURCMD
               CALL NRWR                       ; 65FF CD 74 50
               DEFW CURCMD                     ; 6602 74 5B
               DEFB SKIP_2_VIA_LD_HL           ; 6604 !  skipped: reads as LD HL,AUTNAM from here, and as part of the
                                               ; instruction above it
               PUSH DE                         ; 6605 D5
               LD H,L                          ; 6606 65
               LD DE,DSTR1                     ; 6607 11 36 41
               LD BC,&001C                     ; 660A 01 1C 00
               LDIR                            ; 660D ED B0
               CALL GTDEF                      ; 660F CD D7 66
               CALL CKDRV                      ; 6612 CD 07 48
               LD A,&10                        ; 6615 3E 10  "LOOK FOR NAME"
               JP FDHR                         ; 6617 C3 31 4B

INIT:
               DEFB &CD,&FD                    ; 661A M}  skipped: reads as CALL AUINSR from here, and as part of the
                                               ; instruction above it
               LD H,L                          ; 661C 65
               RET NZ                          ; 661D C0  RET IF NOT FOUND
               JR AUINC                        ; 661E 18 D7

