;; --------------------------------------------------------------------
;; HRSAD -- &6658 to &665A
;;
;; Takes:     A
;; Leaves:    A, F, BC, HL
;;
;; ? calls CALS; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      HRSAD / HWSAD / HFRSAD / HFWSAD -- raw sector access
;;
;;      One sector or many, to or from any page. IY carries the routine to use, so the loop is written once. The address
;;      advances by MSINC a sector -- normally 512, but a program can change it to interleave sectors into memory some
;;      other way -- and CHKHL pages on when it crosses &C000.
;;
;;      Entry:  HKA = drive, HKDE = track and sector, HKHL = offset, HKBC = page, SVHDR = sectors
;;
;;     HOOK READ 1 SECTOR AT DE
;; --------------------------------------------------------------------

HRSAD:
               CALL CALS                       ; 6658 CD B5 66

;; --------------------------------------------------------------------
;; HFRSAD -- &665B to &6660
;;
;; Takes:     A, BC, HL
;; Leaves:    BC, DE, IX, IY
;; Preserves: A, F, HL (saved and restored)
;; Ends:      JP, JR
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A; calls HFWCD, RESET_BUFFER_POINTERS, ITRCK, ISECT.
;; --------------------------------------------------------------------

; ---- HFRSAD ---- from &6656, &6A39
HFRSAD:
               LD IY,READ_SECTOR               ; 665B FD 21 B7 45
               JR FRWSR                        ; 665F 18 10

;; --------------------------------------------------------------------
;; HWSAD -- &6661 to &6663
;;
;; Takes:     A
;; Leaves:    A, F, BC, HL
;;
;; ? calls CALS; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

HWSAD:
               CALL CALS                       ; 6661 CD B5 66

;; --------------------------------------------------------------------
;; HFWSAD -- &6664 to &6670
;;
;; Takes:     BC, HL
;; Leaves:    A, F, BC, IY
;;
;; ? calls DWAIT, HFWCD, SELD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- HFWSAD ---- from &6651, &6A61
HFWSAD:
               CALL HFWCD                      ; 6664 CD F8 47  CONVERT HKA AND CHECK DRIVE
               CALL SELD                       ; 6667 CD 2F 48
               CALL DWAIT                      ; 666A CD 64 45
               LD IY,WSAD                      ; 666D FD 21 86 45

;; --------------------------------------------------------------------
;; FRWSR -- &6671 to &668F
;;
;; Takes:     BC, HL
;; Leaves:    A, F, BC, DE, HL, IX
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A; calls HFWCD, RESET_BUFFER_POINTERS; falls into whatever follows rather than
;; returning.
;; --------------------------------------------------------------------

; ---- FRWSR ---- from &665F
FRWSR:
               IN A,(HMPR)                     ; 6671 DB FB
               PUSH AF                         ; 6673 F5
               XOR A                           ; 6674 AF
               LD (RDAT),A                     ; 6675 32 0D 42  SO RAM DISC KEEPS TRACK UNFIDDLED
               CALL HFWCD                      ; 6678 CD F8 47
               CALL RESET_BUFFER_POINTERS      ; 667B CD 84 4F
               LD HL,(HKHL)                    ; 667E 2A DE 41  ADDR
               LD BC,(SVHDR)                   ; 6681 ED 4B 0A 41  SECTORS
               LD A,(HKBC)                     ; 6685 3A E2 41  ADDR PAGE
               AND &1F                         ; 6688 E6 1F
               OUT (HMPR),A                    ; 668A D3 FB
               LD DE,(HKDE)                    ; 668C ED 5B E0 41  T/S

;; --------------------------------------------------------------------
;; FRWL -- &6690 to &66A8
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE
;; Preserves: HL (saved and restored)
;;
;; ? calls ITRCK, ISECT, CHKHL; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FRWL ---- from &66AD
FRWL:
               PUSH BC                         ; 6690 C5
               CALL CHKHL                      ; 6691 CD 85 77
               LD (BUF),HL                     ; 6694 22 0F 7C
               CALL IYJUMP                     ; 6697 CD 06 00
               LD BC,(MSINC)                   ; 669A ED 4B 45 42  USUALLY 0200H
               ADD HL,BC                       ; 669E 09
               CALL ISECT                      ; 669F CD 24 56
               JR NZ,FRW2                      ; 66A2 20 05
               PUSH HL                         ; 66A4 E5
               CALL ITRCK                      ; 66A5 CD D8 55
               POP HL                          ; 66A8 E1

;; --------------------------------------------------------------------
;; FRW2 -- &66A9 to &66B4
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC
;; Ends:      JP
;;
;; ? drives OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- FRW2 ---- from &66A2
FRW2:
               POP BC                          ; 66A9 C1
               DEC BC                          ; 66AA 0B
               LD A,B                          ; 66AB 78
               OR C                            ; 66AC B1
               JR NZ,FRWL                      ; 66AD 20 E1
               POP AF                          ; 66AF F1
               OUT (HMPR),A                    ; 66B0 D3 FB
               JP RESET_BUFFER_POINTERS        ; 66B2 C3 84 4F  NORMAL BUF AGAIN

;; --------------------------------------------------------------------
;; CALS -- &66B5 to &66BF
;;
;; Takes:     A
;; Leaves:    A, F, BC, HL
;;
;; ? calls PAGEFORM; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     CALCULATE ADDRESS SECTION
;;      Split the caller's address into a page and an offset. An address below &4000 has no page of its own and is
;;      rejected.
;; --------------------------------------------------------------------

; ---- CALS ---- from &6658, &6661
CALS:
               LD HL,(HKHL)                    ; 66B5 2A DE 41
               XOR A                           ; 66B8 AF
               CALL PAGEFORM                   ; 66B9 CD E4 75
               DEC A                           ; 66BC 3D  PAGE 0-2 FOR SECTS B/C/D
               LD BC,&0001                     ; 66BD 01 01 00  1 SECT TO DO

;; --------------------------------------------------------------------
;; SCASD -- &66C0 to &66CD
;;
;; Takes:     A, BC, HL
;; Leaves:    A, F
;; --------------------------------------------------------------------

; ---- SCASD ---- from &5F2A
SCASD:
               LD (HKBC),A                     ; 66C0 32 E2 41
               INC A                           ; 66C3 3C
               JP Z,AHLNX_1                    ; 66C4 CA 91 60  0-3FFFH ILLEGAL ADDR
               LD (HKHL),HL                    ; 66C7 22 DE 41  OFFSET
               LD (SVHDR),BC                   ; 66CA ED 43 0A 41  SECTORS TO DO

;; --------------------------------------------------------------------
;; HDUMMY -- &66CE to &66CE
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      RET
;; --------------------------------------------------------------------

HDUMMY:
               RET                             ; 66CE C9  DUMMY HOOK (WAS S:)

;; --------------------------------------------------------------------
;; FDFSR -- &66CF to &66D6
;;
;; Takes:     nothing in registers
;; Leaves:    A
;; --------------------------------------------------------------------

; ---- FDFSR ---- from &5AEE, &6095, &790B
FDFSR:
               LD A,&2A                        ; 66CF 3E 2A
               LD (NSTR1+1),A                  ; 66D1 32 3B 41  NULL NAME
               LD (NSTR1+2),A                  ; 66D4 32 3C 41  ENSURE NOT "." IF DIR$

;; --------------------------------------------------------------------
;; GTDEF -- &66D7 to &66DE
;;
;; Takes:     DE, HL
;; Leaves:    A, F, HL
;;
;; ? reaches the ROM through DEVL; calls NRRD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- GTDEF ---- from &660F, &6701, &7AB0, &7B98
GTDEF:
                                               ; read the ROM variable DEVL -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 66D7 CD 5E 50
               DEFW DEVL                       ; 66DA 06 5A
               LD (LSTR1),A                    ; 66DC 32 39 41

;; --------------------------------------------------------------------
;; GTDD -- &66DF to &66EA
;;
;; Takes:     DE, HL
;; Leaves:    A, F, HL
;;
;; ? reaches the ROM through DEVN; calls NRRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     GET DEFAULT NUMBER
;;      The ROM's DEVICE variable is shared with the tape system, where it holds a tape speed rather than a drive, so a
;;      value outside the legal drive range is taken to mean that and the DOS's own default is used instead.
;; --------------------------------------------------------------------

; ---- GTDD ---- from &6183
GTDD:
                                               ; read the ROM variable DEVN -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRD                       ; 66DF CD 5E 50
               DEFW DEVN                       ; 66E2 07 5A
               AND A                           ; 66E4 A7
               JR Z,GTDD_1                     ; 66E5 28 04
               CP RDLIM+1                      ; 66E7 FE 09
               JR C,GTDD_2                     ; 66E9 38 03  JR IF LEGAL DRIVE

;; --------------------------------------------------------------------
;; GTDD_1 -- &66EB to &66ED
;;
;; Takes:     nothing in registers
;; Leaves:    A
;; --------------------------------------------------------------------

; ---- GTDD_1 ---- from &66E5 when A = 0
GTDD_1:
               LD A,(ODEF)                     ; 66EB 3A 2F 42  USE "OTHER" DEFAULT

;; --------------------------------------------------------------------
;; GTDD_2 -- &66EE to &6700
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? reaches the ROM through SLDEV; calls NRWR, CODN, DRSET; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- GTDD_2 ---- from &66E9 when A < RDLIM+1
GTDD_2:
               PUSH HL                         ; 66EE E5
               LD (ODEF),A                     ; 66EF 32 2F 42
               CALL CODN                       ; 66F2 CD 9F 61  CONVERT DRV NUM
               CALL DRSET                      ; 66F5 CD 81 67
               LD A,&44                        ; 66F8 3E 44
                                               ; write the ROM variable SLDEV
               CALL NRWR                       ; 66FA CD 74 50
               DEFW SLDEV                      ; 66FD B7 5B
               POP HL                          ; 66FF E1
               RET                             ; 6700 C9

;; --------------------------------------------------------------------
;; DEFAULT_FILE_TYPE -- &6701 to &6713
;;
;; Takes:     DE, HL
;; Leaves:    A, F, HL
;;
;; ? calls GTDEF; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     GTDEF, and if the type byte is &FF -- nothing chosen -- write &54 in
;;     its place before going on.
;; --------------------------------------------------------------------

; ---- DEFAULT_FILE_TYPE ---- from &6390, &724E, &7324
DEFAULT_FILE_TYPE:
               CALL GTDEF                      ; 6701 CD D7 66
               PUSH HL                         ; 6704 E5
               LD (SVHL),HL                    ; 6705 22 05 7C
               LD A,(HL)                       ; 6708 7E
               CP &FF                          ; 6709 FE FF
               JR NZ,EVFL0                     ; 670B 20 07  JR UNLESS NULL NAME
               LD A,&54                        ; 670D 3E 54  LOAD "" BECOMES LOAD "T:"
               LD (HL),A                       ; 670F 77
               INC HL                          ; 6710 23
               LD (HL),&3A                     ; 6711 36 3A
               DEC HL                          ; 6713 2B

;; --------------------------------------------------------------------
