               OUT (HMPR),A                    ; 67B5 D3 FB
               LD A,MIN                        ; 67B7 3E BF
               LD (FSTR1),A                    ; 67B9 32 37 41
               CALL OPMOV                      ; 67BC CD 6C 69  OPEN "IN" TEMP CHANNEL - GET
               JP C,SNOP                       ; 67BF DA 48 70  IF OPMOV RETURNS C WHEN CREATING
