               ADD HL,BC                       ; 690E 09  PT TO CHAN LETTER
               LD A,(HL)                       ; 690F 7E
               CP &53                          ; 6910 FE 53
               RET Z                           ; 6912 C8
               CP &50                          ; 6913 FE 50
               RET Z                           ; 6915 C8
               CP &4B                          ; 6916 FE 4B
               RET                             ; 6918 C9

;; --------------------------------------------------------------------
;; MOVRC -- &6919 to &691E
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;;
;; Shown for this routine in disasm/:
;;
;;      MOVRC / MOVWC -- read and write one byte through a channel
;;
;;      The channel's own input routine is called through an address patched into the instruction at MTARG, since it may
;;      be anywhere. A channel whose routine lies in the DOS's own page -- recognised by the high byte being &4B -- is
;;      handled directly instead, because it cannot be called that way.
;;
;;      Exit:   MOVRC -- CY and the byte in A, or NC at end of file
;;
;;     MOVE - READ CHAR
;;     EXIT: CY IF GOT CHAR IN A, NC IF EOF
;; --------------------------------------------------------------------

; ---- MOVRC ---- from &6844, &684C, &685F, &6875, &687C, &6891
MOVRC:
               LD HL,(NSTR1)                   ; 6919 2A 3A 41
               LD (CURCHL+&4000),HL            ; 691C 22 51 9C

;; --------------------------------------------------------------------
;; MOVRC2 -- &691F to &6938
;;
;; Takes:     BC
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- MOVRC2 ---- from &693D, &7A57
MOVRC2:
               LD HL,(CURCHL+&4000)            ; 691F 2A 51 9C
               LD DE,FS+2                      ; 6922 11 02 40
               ADD HL,DE                       ; 6925 19  SYS PAGE IS AT 8000H
               LD E,(HL)                       ; 6926 5E
               INC HL                          ; 6927 23
               LD D,(HL)                       ; 6928 56
               EX DE,HL                        ; 6929 EB  HL=INPUT ADDRESS
               LD A,H                          ; 692A 7C
               CP &4B                          ; 692B FE 4B
               JR Z,DOSIP                      ; 692D 28 0A  JR IF DOS
               LD (MTARG),HL                   ; 692F 22 35 69
                                               ; call the ROM at &0000 with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 6932 CD B2 7B

; ---- MTARG ---- from &692F
MTARG:
               DEFW &0000                      ; 6935 00 00
               JR GIPC                         ; 6937 18 03

;; --------------------------------------------------------------------
;; DOSIP -- &6939 to &693B
;;
;; Takes:     A, IX
;; Leaves:    A, F, BC, HL
;;
;; ? calls MCHRD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- DOSIP ---- from &692D when A = &4B
DOSIP:
               CALL MCHRD                      ; 6939 CD F9 6E

;; --------------------------------------------------------------------
;; GIPC -- &693C to &693F
;;
;; Takes:     nothing in registers
;; Leaves:    registers unchanged
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- GIPC ---- from &6937
GIPC:
               RET C                           ; 693C D8  RET IF GOT CHAR
               JR Z,MOVRC2                     ; 693D 28 E0  LOOP UNLESS EOF
               RET                             ; 693F C9

;; --------------------------------------------------------------------
;; MOVWC -- &6940 to &6954
;;
;; Takes:     A
;; Leaves:    A, F, DE, HL
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- MOVWC ---- from &6868, &6888, &6896
MOVWC:
               LD HL,(NSTR2)                   ; 6940 2A 56 41
               LD (CURCHL+&4000),HL            ; 6943 22 51 9C
               LD DE,FS+1                      ; 6946 11 01 40
               ADD HL,DE                       ; 6949 19
               LD D,A                          ; 694A 57
               LD A,(HL)                       ; 694B 7E
               CP &4B                          ; 694C FE 4B
               LD A,D                          ; 694E 7A
               JP Z,MCHWR                      ; 694F CA 3B 6F
               JP PRINT_A_KEEPING_IT           ; 6952 C3 66 57

;; --------------------------------------------------------------------
;; EVMOV -- &6955 to &695C
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls GTNC; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- EVMOV ---- from &6799, &67A8
EVMOV:
               CALL GTNC                       ; 6955 CD 3C 50
               CP &23                          ; 6958 FE 23
               JP Z,EVSRM                      ; 695A CA 99 62

;; --------------------------------------------------------------------
;; EVSYN -- &695D to &6960
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls EVNAM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- EVSYN ---- from &6B2C, &7200
EVSYN:
               CALL EVNAM                      ; 695D CD CF 61
               RET Z                           ; 6960 C8  RET IF SYNTAX TIME

;; --------------------------------------------------------------------
;; EVSY2 -- &6961 to &6966
;;
;; Takes:     A, DE
;; Leaves:    HL
;; Preserves: A, F (saved and restored)
;; Ends:      RET
;;
;; ? calls EVFINS.
;; --------------------------------------------------------------------

; ---- EVSY2 ---- from &696A
EVSY2:
               PUSH AF                         ; 6961 F5
               CALL EVFINS                     ; 6962 CD 21 73
               POP AF                          ; 6965 F1
               RET                             ; 6966 C9

;; --------------------------------------------------------------------
;; HEVSY -- &6967 to &696B
;;
;; Takes:     A
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
;; Ends:      JR, RET
;;
;; ? calls HEVNAM, EVFINS.
;; --------------------------------------------------------------------

; ---- HEVSY ---- from &6B0C
HEVSY:
               CALL HEVNAM                     ; 6967 CD B5 61
               JR EVSY2                        ; 696A 18 F5

;; --------------------------------------------------------------------
;; OPMOV -- &696C to &6986
;;
;; Takes:     E
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through STREAM; calls STRMD, CMR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      OPMOV -- open one end of a MOVE
;;
;;      Either an existing stream, in which case its channel is used as it stands, or a file, in which case a temporary
;;      disk channel is created. Temporary channels are marked by a channel letter with bit 7 set, so that CLTEMP can
;;      recognise and reclaim them afterwards.
;;
;;      Exit:   NC and NSTR1 = the channel address; CY on failure, with Z if the reason was a stream that is not open
;;
;;     OPEN A MOVE CHANNEL. RETURN NSTR1=CHANNEL ADDR IN CHANNELS
;;     (SECT B) CY IF ERROR, (AND Z IF STREAM NOT OPEN), NC IF OK
;; --------------------------------------------------------------------

; ---- OPMOV ---- from &67BC, &67D9
OPMOV:
               LD A,(SSTR1)                    ; 696C 3A 38 41
               INC A                           ; 696F 3C
               JR Z,OPMV1                      ; 6970 28 15  JR IF NOT A STREAM
               DEC A                           ; 6972 3D
               CALL STRMD                      ; 6973 CD 4C 70
               LD D,A                          ; 6976 57
               LD A,B                          ; 6977 78
               OR C                            ; 6978 B1
               SCF                             ; 6979 37
               RET Z                           ; 697A C8  RET IF STREAM NOT OPEN, WITH CY
               LD A,D                          ; 697B 7A
                                               ; call the ROM at STREAM with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 697C CD B2 7B
               DEFW STREAM                     ; 697F 12 01
               LD IX,(CURCHL+&4000)            ; 6981 DD 2A 51 9C
               JR OPMV2                        ; 6985 18 1F

;; --------------------------------------------------------------------
;; OPMV1 -- &6987 to &69A5
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, DE, IX
;;
;; ? calls CKDRV, RESET_CHANNEL_SCAN; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPMV1 ---- from &6970 when A wraps to 0
OPMV1:
               LD A,(LSTR1)                    ; 6987 3A 39 41
               AND &DF                         ; 698A E6 DF
               CP &44                          ; 698C FE 44
               JP NZ,REP0                      ; 698E C2 E0 5E
               CALL CKDRV                      ; 6991 CD 07 48
               CALL RESET_CHANNEL_SCAN         ; 6994 CD 77 6B
               LD A,&01                        ; 6997 3E 01
               INC A                           ; 6999 3C  NZ = ERROR NOT DUE STREAM NOT OPEN
               RET C                           ; 699A D8  RET IF ABORTED (OVERWRITE?+N)
               LD A,(NSTR1)                    ; 699B 3A 3A 41
               LD (FSTR1),A                    ; 699E 32 37 41
               LD BC,&C000                     ; 69A1 01 00 C0
               ADD IX,BC                       ; 69A4 DD 09

;; --------------------------------------------------------------------
;; OPMV2 -- &69A6 to &69AB
;;
;; Takes:     A, IX
;; Leaves:    A, F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- OPMV2 ---- from &6985
OPMV2:
               LD (NSTR1),IX                   ; 69A6 DD 22 3A 41
               AND A                           ; 69AA A7  NC=OK
               RET                             ; 69AB C9

;; --------------------------------------------------------------------
;; CLMOV -- &69AC to &69B9
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, IX
;; --------------------------------------------------------------------

; ---- CLMOV ---- from &68A2, &68A8
CLMOV:
               LD A,(SSTR1)                    ; 69AC 3A 38 41
               INC A                           ; 69AF 3C
               RET NZ                          ; 69B0 C0  RET IF THERE WAS A STREAM
               LD IX,(NSTR1)                   ; 69B1 DD 2A 3A 41
               LD BC,HEADER                    ; 69B5 01 00 40
               ADD IX,BC                       ; 69B8 DD 09

;; --------------------------------------------------------------------
;; DELD -- &69BA to &69CE
;;
;; Takes:     A, IX
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JP, JR, RET
;;
;; ? calls CHANNEL_LENGTH_AND_FLAGS, DECSAM.
;; --------------------------------------------------------------------

; ---- DELD ---- from &68C3
DELD:
               PUSH IX                         ; 69BA DD E5
               POP HL                          ; 69BC E1
               LD DE,&C000                     ; 69BD 11 00 C0
               ADD HL,DE                       ; 69C0 19  CORRECT TO SECT B, LIKE CHANS
               LD DE,(CHANS+&4000)             ; 69C1 ED 5B 4F 9C
               OR A                            ; 69C5 B7
               SBC HL,DE                       ; 69C6 ED 52
               INC HL                          ; 69C8 23
               LD (SVTRS),HL                   ; 69C9 22 24 41  CHANNEL DISP
               JP CLRCHD                       ; 69CC C3 20 6E

;; --------------------------------------------------------------------
;; BACKUP -- &69CF to &69ED
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? calls CKDRV, FDHR, CLSAM, GTNC; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      BACKUP -- copy a whole disk, transferring only the sectors in use
;;
;;      The free-sector map tells the DOS how much of the disk is actually occupied: scanning it backwards for the last
;;      non-zero byte gives the highest sector in use, and everything above that can be skipped. On a disk holding a few
;;      small files this turns a whole-disk copy into a very short one.
;;
;;      The transfer runs in passes sized by whatever free RAM there is -- FFPG again -- with each page holding 32
;;      sectors. The first pass stamps the target with a fresh random word and the disk name, so that the copy is a
;;      distinct disk rather than a duplicate identity.
;;
;;      With one drive, the user is prompted to swap disks between each read and write.
;;
;;      Errors: REP35 if there are no free pages
;; --------------------------------------------------------------------

BACKUP:
               CALL GTNC                       ; 69CF CD 3C 50
               CALL EVAL_NAME_PAIR             ; 69D2 CD 7B 59  EVAL FILE TO FILE
               CALL COBUS                      ; 69D5 CD A0 59  EVFILES, SET SINGLE-DISC FLAG
               CALL CKDRV                      ; 69D8 CD 07 48  AS NEEDED
               LD HL,MB_PUTSWA                 ; 69DB 21 00 80
               LD (HKHL),HL                    ; 69DE 22 DE 41  SRC/DEST
               CALL CLSAM                      ; 69E1 CD FA 4C  CLEAR SAM
               LD A,&20                        ; 69E4 3E 20
               CALL FDHR                       ; 69E6 CD 31 4B  CREATE SAM
               LD B,&C3                        ; 69E9 06 C3  BYTES IN SAM
               LD HL,SAM+194                   ; 69EB 21 D1 40

;; --------------------------------------------------------------------
;; SBKSL -- &69EE to &69F4
;;
;; Takes:     B, HL
;; Leaves:    A, F, B, HL
;; --------------------------------------------------------------------

; ---- SBKSL ---- from &69F3 when B is not 0 yet
SBKSL:
               LD A,(HL)                       ; 69EE 7E
               AND A                           ; 69EF A7
               JR NZ,BKU2                      ; 69F0 20 03  EXIT WHEN 1ST USED MAP BYTE FOUND
               DEC HL                          ; 69F2 2B
               DJNZ SBKSL                      ; 69F3 10 F9

;; --------------------------------------------------------------------
;; BKU2 -- &69F5 to &6A06
;;
;; Takes:     B
;; Leaves:    F, BC, DE, HL
;; --------------------------------------------------------------------

; ---- BKU2 ---- from &69F0 when A <> 0
BKU2:
               LD L,B                          ; 69F5 68
               LD H,&00                        ; 69F6 26 00
               ADD HL,HL                       ; 69F8 29
               ADD HL,HL                       ; 69F9 29
               ADD HL,HL                       ; 69FA 29  HL=SECTORS USED
               LD BC,&0028                     ; 69FB 01 28 00
               ADD HL,BC                       ; 69FE 09  ALLOW FOR DIRECTORY TKS 0-3
               INC B                           ; 69FF 04  NZ
               LD DE,&0001                     ; 6A00 11 01 00
               LD (HKDE),DE                    ; 6A03 ED 53 E0 41  START AT T0/S1

;; --------------------------------------------------------------------
;; BKUL -- &6A07 to &6A2B
;;
;; This routine moves the return address about with EX (SP),HL, so the
;; register tracking below cannot be trusted: read it as a list of what
;; is touched, not of what is destroyed.
;;
;; Takes:     A, C, DE, HL, R
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR, RET
;;
;; ? drives OUT (HMPR),A; calls SETF6, BITF1, BITF6, FESE2.
;; --------------------------------------------------------------------

; ---- BKUL ---- from &6A6F
BKUL:
               PUSH DE                         ; 6A07 D5  T/S TO WRITE TO
               PUSH HL                         ; 6A08 E5  SECTS LEFT TO DO
               CALL Z,TSPCE2                   ; 6A09 CC 3D 59  PROMPT FOR SRC DISC IF 1-DRIVE
               CALL FFPG                       ; 6A0C CD B7 5A
               LD A,B                          ; 6A0F 78
               AND A                           ; 6A10 A7
               JP Z,REP33_1                    ; 6A11 CA 9B 51  ERROR IF NO PAGES FREE
               LD (HKBC),DE                    ; 6A14 ED 53 E2 41  HKBC=PAGE
               LD L,A                          ; 6A18 6F
               LD H,&00                        ; 6A19 26 00
               ADD HL,HL                       ; 6A1B 29
               ADD HL,HL                       ; 6A1C 29
               ADD HL,HL                       ; 6A1D 29
               ADD HL,HL                       ; 6A1E 29
               ADD HL,HL                       ; 6A1F 29
               EX DE,HL                        ; 6A20 EB  DE=SECTORS FREE AT 32/PAGE
               POP HL                          ; 6A21 E1  LEFT TO DO
               SBC HL,DE                       ; 6A22 ED 52  SUB LEFT TO DO,FREE
               PUSH HL                         ; 6A24 E5  NEW LEFT TO DO, UNLESS LAST PASS
               JR C,BKU3                       ; 6A25 38 05  JR IF CAN FINISH IN THIS PASS
               JR Z,BKU3                       ; 6A27 28 03
               EX DE,HL                        ; 6A29 EB  HL=FREE
               JR BKU4                         ; 6A2A 18 04

;; --------------------------------------------------------------------
;; BKU3 -- &6A2C to &6A2F
;;
;; Takes:     DE, HL
;; Leaves:    F, HL
;;
;; ? calls SETF1; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- BKU3 ---- from &6A25, &6A27
BKU3:
               ADD HL,DE                       ; 6A2C 19  HL=LEFT TO DO
               CALL SETF1                      ; 6A2D CD F2 50  "LAST PASS"

;; --------------------------------------------------------------------
;; BKU4 -- &6A30 to &6A60
;;
;; This routine moves the return address about with EX (SP),HL, so the
;; register tracking below cannot be trusted: read it as a list of what
;; is touched, not of what is destroyed.
;;
;; Takes:     BC, HL, R
;; Leaves:    A, F, BC, DE, HL, IX, IY
;;
;; ? drives OUT (HMPR),A; calls SETF6, BITF6, FESE2, TSPCE1; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- BKU4 ---- from &6A2A
BKU4:
               LD (SVHDR),HL                   ; 6A30 22 0A 41  IX=SECTS TO DO
               LD A,(DSTR1)                    ; 6A33 3A 36 41
               LD (HKA),A                      ; 6A36 32 DD 41  DRIVE
               CALL HFRSAD                     ; 6A39 CD 5B 66  READ SECTS
               POP HL                          ; 6A3C E1  LEFT TO DO
               EX (SP),HL                      ; 6A3D E3
               LD (HKDE),HL                    ; 6A3E 22 E0 41  T/S TO WRITE TO NEXT
               PUSH DE                         ; 6A41 D5  T/S REACHED ON SRC
               CALL TSPCE1                     ; 6A42 CD 34 59  PROMPT FOR DEST DISC IF 1-DRIVE
               CALL EXDAT                      ; 6A45 CD 43 62  BACKUP
               LD A,(DSTR1)                    ; 6A48 3A 36 41
               LD (HKA),A                      ; 6A4B 32 DD 41  DRIVE
               CALL BITF6                      ; 6A4E CD 3A 51
               JR NZ,BKU5                      ; 6A51 20 0E  JR IF NOT FIRST PASS
               LD A,(HKBC)                     ; 6A53 3A E2 41
               OUT (HMPR),A                    ; 6A56 D3 FB
               LD HL,&80FF                     ; 6A58 21 FF 80
               CALL FESE2                      ; 6A5B CD F8 55  SET RND WORD AND NAME
               CALL SETF6                      ; 6A5E CD 10 51  "NOT FIRST PASS"

;; --------------------------------------------------------------------
;; BKU5 -- &6A61 to &6A71
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, HL, IY
;; Ends:      RET
;;
;; ? calls BITF1, EXDAT, HFWSAD.
;; --------------------------------------------------------------------

; ---- BKU5 ---- from &6A51
BKU5:
               CALL HFWSAD                     ; 6A61 CD 64 66  WRITE SECTS
               POP HL                          ; 6A64 E1
               LD (HKDE),HL                    ; 6A65 22 E0 41  T/S TO READ FROM NEXT IF MORE
               CALL EXDAT                      ; 6A68 CD 43 62
               POP HL                          ; 6A6B E1  LEFT TO DO OR JUNK
               CALL BITF1                      ; 6A6C CD 22 51
               JR Z,BKUL                       ; 6A6F 28 96  LOOP UNTIL LAST PASS
               RET                             ; 6A71 C9

;; --------------------------------------------------------------------
;; OPSR -- &6A72 to &6A88
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls IS_END_OF_STATEMENT, GTNC; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     OPSR -- read the access mode at the end of an OPEN.
;;
;;         OPEN #4;"file" IN     &FF &60   the ROM's IN token
;;         OPEN #4;"file" OUT    &E0       the ROM's OUT token
;;         OPEN #4;"file" RND    &FF &3C   the ROM's RND function token
;;
;;     The mode is stored in FSTR1 as MIN, MOUT or MRND, and OUT is what a
;;     filespec with nothing after it gets.  RND is spelled with the function
;;     token for RND because the ROM has no keyword closer to the meaning to
;;     borrow, which is also why the test for it sits under the &FF prefix
;;     with IN rather than beside OUT.
;;
;;     MasterBASIC has rewritten the head of this routine: where MasterDOS
;;     tested for &0D and ":" inline, this calls a helper that does both, so
;;     the annotated source's description of it is not carried automatically.
;;
;;     MIN, MOUT and MRND are access modes and nothing else, whatever their
;;     names suggest.  The original source calls MIN and MOUT the "serial
;;     input port" and "serial output port", but they are never sent to an
;;     IN or an OUT; they are stored in FSTR1 and compared against token
;;     bytes.  Nothing in this page drives a serial chip -- every IN and OUT
;;     here goes to LMPR, HMPR, VMPR, the keyboard, status, border and
;;     palette ports, the disk controller ports patched into the transfer
;;     loops, or, once in the boot code, RESP at &E9 for printer control.
;;
;;     The real serial driver is in the extension page, and it does program
;;     the SCC2691 in the SAM Comms Interface: see SERINIT and the two hooks
;;     beside it in masterbasic.asm.  It takes its port from XVAR 11, SPORT,
;;     so no port number appears in its code either.
;; --------------------------------------------------------------------

; ---- OPSR ---- from &6B09, &6B2F
OPSR:
               CALL IS_END_OF_STATEMENT        ; 6A72 CD F3 4F
               RET Z                           ; 6A75 C8
               CP &FF                          ; 6A76 FE FF
               JR NZ,OPSR0                     ; 6A78 20 0F
               CALL GTNC                       ; 6A7A CD 3C 50
               LD C,MIN                        ; 6A7D 0E BF  USE ZX "IN" CODE
               CP &60                          ; 6A7F FE 60  FF 60 IS "IN" CODE
               JR Z,OPSR1                      ; 6A81 28 0D
               LD C,MRND                       ; 6A83 0E A5  ZX "RND" CODE
               CP &3C                          ; 6A85 FE 3C  FF 3C IS "RND" CODE
               JR Z,OPSR1                      ; 6A87 28 07

;; --------------------------------------------------------------------
;; OPSR0 -- &6A89 to &6A8F
;;
;; Takes:     A
;; Leaves:    F, C
;; --------------------------------------------------------------------

; ---- OPSR0 ---- from &6A78 when A <> &FF
OPSR0:
               LD C,MOUT                       ; 6A89 0E DF  ZX OUT CODE
               CP &E0                          ; 6A8B FE E0  OUT TOKEN
               JP NZ,REP0                      ; 6A8D C2 E0 5E

;; --------------------------------------------------------------------
;; OPSR1 -- &6A90 to &6A96
;;
;; Takes:     C
;; Leaves:    A
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- OPSR1 ---- from &6A81 when A = &60, &6A87 when A = &3C
OPSR1:
               LD A,C                          ; 6A90 79
               LD (FSTR1),A                    ; 6A91 32 37 41
               JP GTNC                         ; 6A94 C3 3C 50

;; --------------------------------------------------------------------
;; CMD_OPEN -- &6A97 to &6ABE
;;
;; Takes:     A, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CFSO, CEOS, GTNC, REMFP; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

CMD_OPEN:
               CALL CFSO                       ; 6A97 CD F9 4F
               CALL Z,REMFP                    ; 6A9A CC 55 5F  REMOVE ANY FP FORMS IN SYNTAX TIME
               CALL GTNC                       ; 6A9D CD 3C 50
               CP &A9                          ; 6AA0 FE A9
               JR NZ,CMD_OPEN_1                ; 6AA2 20 7D
               CALL EVNUMX                     ; 6AA4 CD AF 62
               CALL CEOS                       ; 6AA7 CD 07 50
               INC B                           ; 6AAA 04
               DEC B                           ; 6AAB 05
               JP NZ,AHLNX_1                   ; 6AAC C2 91 60
               LD A,C                          ; 6AAF 79
               LD B,A                          ; 6AB0 47
               DEC A                           ; 6AB1 3D
               CP &06                          ; 6AB2 FE 06
               JP NC,AHLNX_1                   ; 6AB4 D2 91 60
               LD DE,&0313                     ; 6AB7 11 13 03
               PUSH BC                         ; 6ABA C5
               PUSH DE                         ; 6ABB D5
               LD HL,&0000                     ; 6ABC 21 00 00

;; --------------------------------------------------------------------
;; CMD_OPEN_LOOP -- &6ABF to &6AD1
;;
;; Takes:     A, B, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through JMKRBIG; calls CHANNEL_ENTRY_AT_ZERO_PAGE, CMR; falls into whatever follows rather than
;; returning.
;; --------------------------------------------------------------------

; ---- CMD_OPEN_LOOP ---- from &6AC0 when B is not 0 yet
CMD_OPEN_LOOP:
               ADD HL,DE                       ; 6ABF 19
               DJNZ CMD_OPEN_LOOP              ; 6AC0 10 FD
               LD B,H                          ; 6AC2 44
               LD C,L                          ; 6AC3 4D
               CALL CHANNEL_ENTRY_AT_ZERO_PAGE ; 6AC4 CD EA 6A
               XOR A                           ; 6AC7 AF
               PUSH HL                         ; 6AC8 E5
                                               ; call the ROM at JMKRBIG with ROM1 paged in, and page back on the way
                                               ; out
               CALL CMR                        ; 6AC9 CD B2 7B
               DEFW JMKRBIG                    ; 6ACC 0C 01
               POP IX                          ; 6ACE DD E1
               POP DE                          ; 6AD0 D1
               POP BC                          ; 6AD1 C1

;; --------------------------------------------------------------------
;; CMD_OPEN_LOOP2 -- &6AD2 to &6AE3
;;
;; Takes:     B, DE, IX
;; Leaves:    F, B, IX
;; --------------------------------------------------------------------

; ---- CMD_OPEN_LOOP2 ---- from &6AE2 when B is not 0 yet
CMD_OPEN_LOOP2:
               LD (IX+&00),&00                 ; 6AD2 DD 36 00 00
               LD (IX+&04),&00                 ; 6AD6 DD 36 04 00
               LD (IX+&09),E                   ; 6ADA DD 73 09
               LD (IX+&0A),D                   ; 6ADD DD 72 0A
               ADD IX,DE                       ; 6AE0 DD 19
               DJNZ CMD_OPEN_LOOP2             ; 6AE2 10 EE

;; --------------------------------------------------------------------
;; CMD_OPEN_DONE -- &6AE4 to &6AE9
;;
;; Takes:     BC, DE, HL
;; Leaves:    BC, DE, HL, IY
;;
;; ? reaches the ROM through MB_SET_DCT_COMPILE_BITS-&4000; calls CALLMB; falls into whatever follows rather than
;; returning.
;; --------------------------------------------------------------------

; ---- CMD_OPEN_DONE ---- from &681A, &6D63
CMD_OPEN_DONE:
                                                  ; call MB_SET_DCT_COMPILE_BITS-&4000 in the other page: LMPR is
                                                  ; switched first, so that address is how the other listing numbers it
               CALL CALLMB                        ; 6AE4 CD BD 42
               DEFW MB_SET_DCT_COMPILE_BITS-&4000 ; 6AE7 9C 45
               RET                                ; 6AE9 C9

;; --------------------------------------------------------------------
;; CHANNEL_ENTRY_AT_ZERO_PAGE -- &6AEA to &6AF2
;;
;; Takes:     A
;; Leaves:    A, F, DE, HL
;;
;; ? drives OUT (HMPR),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Zero HMPR so the system page is in the window, take CHANS from it and
;;     add &1E, then check the result with the ROM's CHKHL before reading
;;     through it.
;; --------------------------------------------------------------------

; ---- CHANNEL_ENTRY_AT_ZERO_PAGE ---- from &5E07, &6AC4
CHANNEL_ENTRY_AT_ZERO_PAGE:
               XOR A                           ; 6AEA AF
               OUT (HMPR),A                    ; 6AEB D3 FB
               LD HL,(CHANS+&4000)             ; 6AED 2A 4F 9C
               LD DE,&401E                     ; 6AF0 11 1E 40

;; --------------------------------------------------------------------
;; CHANNEL_ENTRY_AT_ZERO_PAGE_LOOP -- &6AF3 to &6B05
;;
;; Takes:     DE, HL
;; Leaves:    A, F, DE
;; Preserves: HL (saved and restored)
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CHANNEL_ENTRY_AT_ZERO_PAGE_LOOP ---- from &6B03 when A <> &0D
CHANNEL_ENTRY_AT_ZERO_PAGE_LOOP:
               ADD HL,DE                             ; 6AF3 19
               CALL ROM_CHKHL                        ; 6AF4 CD EF 3F
               LD A,(HL)                             ; 6AF7 7E
               PUSH HL                               ; 6AF8 E5
               LD DE,&0009                           ; 6AF9 11 09 00
               ADD HL,DE                             ; 6AFC 19
               LD E,(HL)                             ; 6AFD 5E
               INC HL                                ; 6AFE 23
               LD D,(HL)                             ; 6AFF 56
               POP HL                                ; 6B00 E1
               CP &0D                                ; 6B01 FE 0D
               JR NZ,CHANNEL_ENTRY_AT_ZERO_PAGE_LOOP ; 6B03 20 EE
               RET                                   ; 6B05 C9

;; --------------------------------------------------------------------
;; HK_HOPEN -- &6B06 to &6B20
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IX, IY
;; Ends:      JR, RET
;;
;; ? calls CKDRV, GCHR, HEVSY, OPSR.
;; --------------------------------------------------------------------

HK_HOPEN:
               CALL GCHR                       ; 6B06 CD 42 50
               CALL OPSR                       ; 6B09 CD 72 6A
               CALL HEVSY                      ; 6B0C CD 67 69
               LD HL,(HKHL)                    ; 6B0F 2A DE 41
               DEC HL                          ; 6B12 2B
               LD BC,PDIRH_1                   ; 6B13 01 16 5C  &5C16 is the ROM's STRMS, the stream table in the system
                                               ; page -- not this page's PDIRH_1, which happens to sit at the same
                                               ; address
               AND A                           ; 6B16 A7
               SBC HL,BC                       ; 6B17 ED 42
               LD A,L                          ; 6B19 7D
               SRL A                           ; 6B1A CB 3F
               LD (SSTR1),A                    ; 6B1C 32 38 41
               JR OPEX                         ; 6B1F 18 17

;; --------------------------------------------------------------------
;; CMD_OPEN_1 -- &6B21 to &6B37
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls CEOS, PLNS, SEPARX, EVSRM; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- CMD_OPEN_1 ---- from &6AA2 when A <> &A9
CMD_OPEN_1:
               CP &23                          ; 6B21 FE 23
               JP NZ,OPNDIR                    ; 6B23 C2 FB 71
               CALL EVSRM                      ; 6B26 CD 99 62  SKIP, EVAL STREAM
               CALL SEPARX                     ; 6B29 CD DC 5E  INSIST ,/; (SKIPPED) OR QUOTE
               CALL EVSYN                      ; 6B2C CD 5D 69  NAME
               CALL OPSR                       ; 6B2F CD 72 6A  DEAL WITH CR/:/IN/OUT
               CALL PLNS                       ; 6B32 CD 8E 50  PLACE NEXT STAT ADDR
               CALL CEOS                       ; 6B35 CD 07 50

;; --------------------------------------------------------------------
;; OPEX -- &6B38 to &6B4A
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, BC, HL
;;
;; ? calls STRMD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPEX ---- from &6B1F
OPEX:
               LD A,(SSTR1)                    ; 6B38 3A 38 41
               CALL STRMD                      ; 6B3B CD 4C 70  BC=CURRENT DISP IN STRMS
               CP &04                          ; 6B3E FE 04
               JR C,OPEN25                     ; 6B40 38 09  DON'T WORRY IF STREAMS 0-3
               LD HL,&001A                     ; 6B42 21 1A 00  DISP OF LAST STANDARD CHANNEL
               AND A                           ; 6B45 A7
               SBC HL,BC                       ; 6B46 ED 42
               JP C,REP30                      ; 6B48 DA 8F 51  "STREAM USED" IF STREAM OPEN TO

;; --------------------------------------------------------------------
;; OPEN25 -- &6B4B to &6B5C
;;
;; Takes:     nothing in registers
;; Leaves:    A, F
;;
;; ? calls CKDRV; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPEN25 ---- from &6B40 when A < &04
OPEN25:
               LD A,(LSTR1)                    ; 6B4B 3A 39 41
               AND &DF                         ; 6B4E E6 DF
               CP &44                          ; 6B50 FE 44
               JP NZ,REP0                      ; 6B52 C2 E0 5E  "NONSENSE"
               CALL CKDRV                      ; 6B55 CD 07 48
               LD A,&0A                        ; 6B58 3E 0A
               LD (NSTR1),A                    ; 6B5A 32 3A 41  FILE TYPE

;; --------------------------------------------------------------------
;; OPDST -- &6B5D to &6B6D
;;
;; Takes:     nothing in registers
;; Leaves:    A, F, DE, HL, IX
;;
;; ? calls RESET_CHANNEL_SCAN; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

OPDST:
               LD A,(SSTR1)                    ; 6B5D 3A 38 41
               ADD A,A                         ; 6B60 87
               LD HL,&5C16+FS                  ; 6B61 21 16 9C
               LD E,A                          ; 6B64 5F
               LD D,&00                        ; 6B65 16 00
               ADD HL,DE                       ; 6B67 19
               PUSH HL                         ; 6B68 E5  ADDR OF PTR IN STRMS
               CALL RESET_CHANNEL_SCAN         ; 6B69 CD 77 6B
               POP DE                          ; 6B6C D1
               RET C                           ; 6B6D D8  RET IF ERROR

;; --------------------------------------------------------------------
;; OPDST1 -- &6B6E to &6B76
;;
;; Takes:     DE, HL, IX
;; Leaves:    DE, HL, IX
;; Ends:      RET
;; --------------------------------------------------------------------

OPDST1:
               RES 7,(IX+&04)                  ; 6B6E DD CB 04 BE  "D" NOT "D"+80H - PERM CHANNEL
               EX DE,HL                        ; 6B72 EB
               LD (HL),E                       ; 6B73 73
               INC HL                          ; 6B74 23
               LD (HL),D                       ; 6B75 72  STRM PTR
               RET                             ; 6B76 C9

;; --------------------------------------------------------------------
;; RESET_CHANNEL_SCAN -- &6B77 to &6B83
;;
;; Takes:     A
;; Leaves:    A, F, DE, IX
;;
;; ? drives OUT (HMPR),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The same setup with IX instead of HL, and V4213 cleared first --
;;     which is what makes it the start of a scan rather than a single
;;     lookup.
;; --------------------------------------------------------------------

; ---- RESET_CHANNEL_SCAN ---- from &6994, &6B69
RESET_CHANNEL_SCAN:
               XOR A                           ; 6B77 AF
               OUT (HMPR),A                    ; 6B78 D3 FB
               LD (V4213),A                    ; 6B7A 32 13 42
               LD IX,(CHANS+&4000)             ; 6B7D DD 2A 4F 9C
               LD DE,&401E                     ; 6B81 11 1E 40

;; --------------------------------------------------------------------
;; RESET_CHANNEL_SCAN_1 -- &6B84 to &6B96
;;
;; Takes:     DE, IX
;; Leaves:    A, F, IX
;; --------------------------------------------------------------------

; ---- RESET_CHANNEL_SCAN_1 ---- from &6BD3
RESET_CHANNEL_SCAN_1:
               ADD IX,DE                       ; 6B84 DD 19  SKIP 6 STANDARD CHANNELS
               LD A,(IX+&00)                   ; 6B86 DD 7E 00
               CP &0D                          ; 6B89 FE 0D
               JR Z,RESET_CHANNEL_SCAN_3       ; 6B8B 28 48  JR IF CHANS TERMINATOR FOUND
               LD A,(IX+&04)                   ; 6B8D DD 7E 04
               AND A                           ; 6B90 A7
               JR NZ,RESET_CHANNEL_SCAN_2      ; 6B91 20 04
               LD (TEMPW1),IX                  ; 6B93 DD 22 12 42

;; --------------------------------------------------------------------
;; RESET_CHANNEL_SCAN_2 -- &6B97 to &6BBF
;;
;; Takes:     A, IX
;; Leaves:    A, F, B, DE, HL
;; --------------------------------------------------------------------

; ---- RESET_CHANNEL_SCAN_2 ---- from &6B91 when A <> 0
RESET_CHANNEL_SCAN_2:
               AND &5F                         ; 6B97 E6 5F
               CP &44                          ; 6B99 FE 44
               JR NZ,OPND2_1                   ; 6B9B 20 30
               LD A,(DSTR1)                    ; 6B9D 3A 36 41
               CP (IX+&0B)                     ; 6BA0 DD BE 0B
               JR NZ,OPND2_1                   ; 6BA3 20 28
               LD A,(FSTR1)                    ; 6BA5 3A 37 41
               CP &BF                          ; 6BA8 FE BF
               JR Z,OPND2_1                    ; 6BAA 28 21
               LD A,(IX+&0C)                   ; 6BAC DD 7E 0C
               AND &03                         ; 6BAF E6 03
               JR Z,OPND2_1                    ; 6BB1 28 1A
               PUSH IX                         ; 6BB3 DD E5
               POP HL                          ; 6BB5 E1
               LD DE,NAME                      ; 6BB6 11 14 00
               ADD HL,DE                       ; 6BB9 19
               EX DE,HL                        ; 6BBA EB
               LD HL,NSTR1+1                   ; 6BBB 21 3B 41
               LD B,&0A                        ; 6BBE 06 0A

;; --------------------------------------------------------------------
;; OPND2 -- &6BC0 to &6BCC
;;
;; Takes:     B, DE, HL
;; Leaves:    A, F, B, DE, HL
;; Ends:      JP
;; --------------------------------------------------------------------

; ---- OPND2 ---- from &6BC8 when B is not 0 yet
OPND2:
               LD A,(DE)                       ; 6BC0 1A
               XOR (HL)                        ; 6BC1 AE
               AND &DF                         ; 6BC2 E6 DF
               JR NZ,OPND2_1                   ; 6BC4 20 07
               INC HL                          ; 6BC6 23
               INC DE                          ; 6BC7 13
               DJNZ OPND2                      ; 6BC8 10 F6
               JP REP31                        ; 6BCA C3 92 51  "CHANNEL USED"

;; --------------------------------------------------------------------
;; OPND2_1 -- &6BCD to &6BD4
;;
;; Takes:     IX
;; Leaves:    A, F, B, DE, HL, IX
;; Ends:      JP, JR
;; --------------------------------------------------------------------

; ---- OPND2_1 ---- from &6B9B when A <> &44, &6BA3 when A <> (IX+&0B), &6BAA when A = &BF, &6BB1 when no bit of &03 is
; set, &6BC4 when a bit of &DF is set
OPND2_1:
               LD E,(IX+&09)                   ; 6BCD DD 5E 09
               LD D,(IX+&0A)                   ; 6BD0 DD 56 0A
               JR RESET_CHANNEL_SCAN_1         ; 6BD3 18 AF

;; --------------------------------------------------------------------
;; RESET_CHANNEL_SCAN_3 -- &6BD5 to &6BDE
;;
;; This routine moves the return address about with EX (SP),HL, so the
;; register tracking below cannot be trusted: read it as a list of what
;; is touched, not of what is destroyed.
;;
;; Takes:     IX
;; Leaves:    A, F, HL
;; --------------------------------------------------------------------

; ---- RESET_CHANNEL_SCAN_3 ---- from &6B8B when A = &0D
RESET_CHANNEL_SCAN_3:
               PUSH IX                         ; 6BD5 DD E5
               LD HL,(TEMPW1)                  ; 6BD7 2A 12 42
               LD A,H                          ; 6BDA 7C
               AND A                           ; 6BDB A7
               JR Z,OPND2_2                    ; 6BDC 28 01
               EX (SP),HL                      ; 6BDE E3

;; --------------------------------------------------------------------
;; OPND2_2 -- &6BDF to &6C07
;;
;; Takes:     A
;; Leaves:    F, BC, DE, HL, IX, IY
;; Preserves: A (saved and restored)
;;
;; ? calls FDHR, POINT, MOVE_TABLE_IF_PAGED; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPND2_2 ---- from &6BDC when A = 0
OPND2_2:
               LD A,&10                        ; 6BDF 3E 10
               CALL FDHR                       ; 6BE1 CD 31 4B  Z IF FOUND
               POP HL                          ; 6BE4 E1  ADDR OF CHANS TERMINATOR
               PUSH HL                         ; 6BE5 E5  - LOCN FOR NEW CHAN
               LD A,(FSTR1)                    ; 6BE6 3A 37 41
               JP NZ,OPND45                    ; 6BE9 C2 BF 6C  JR IF NOT FOUND
               PUSH AF                         ; 6BEC F5
               CALL MOVE_TABLE_IF_PAGED        ; 6BED CD 30 6D  CREATE CHANNEL
               CALL POINT                      ; 6BF0 CD AC 4F  HL=DIR ENTRY  (USES IX=DCHAN)
               POP AF                          ; 6BF3 F1
               POP IX                          ; 6BF4 DD E1  CHANS PTR
               PUSH HL                         ; 6BF6 E5  DIR ENTRY PTR
               LD C,&04                        ; 6BF7 0E 04  BITS 1 AND 0 SHOW READ, BIT 2
               CP MIN                          ; 6BF9 FE BF  SHOWS EXISTS
               JR Z,OPND44                     ; 6BFB 28 0B
               CP MOUT                         ; 6BFD FE DF
               JP Z,REP19                      ; 6BFF CA 77 51  WRITING A READ FILE IF EXIST
               CP MRND                         ; 6C02 FE A5
               JR NZ,OPND44                    ; 6C04 20 02  JR IF DEFAULT - IN
               LD C,&06                        ; 6C06 0E 06  BITS 1 AND 0 SHOW RND, BIT 2

;; --------------------------------------------------------------------
;; OPND44 -- &6C08 to &6C56
;;
;; Takes:     C, DE, HL, IX
;; Leaves:    A, F, BC, HL, IX
;; Preserves: DE (saved and restored)
;;
;; ? calls OPND8, COUNT_AND_READ_SECTOR, RAMST; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPND44 ---- from &6BFB when A = MIN, &6C04 when A <> MRND
OPND44:
               LD A,C                          ; 6C08 79
               CALL RAMST                      ; 6C09 CD 5D 70
               LD DE,FFSA                      ; 6C0C 11 13 00
               LD BC,&0100                     ; 6C0F 01 00 01
               PUSH IX                         ; 6C12 DD E5
               POP HL                          ; 6C14 E1  CHANNEL
               ADD HL,DE                       ; 6C15 19
               EX DE,HL                        ; 6C16 EB  DE=TYPE/NAME ETC DEST IN CHANNEL
               POP HL                          ; 6C17 E1  DIR ENTRY
               PUSH HL                         ; 6C18 E5  DIR ENTRY
               PUSH DE                         ; 6C19 D5  TYPE IN CHANNEL
               LDIR                            ; 6C1A ED B0  COPY 256 BYTES FROM DIR ENTRY TO CHANNE
               POP DE                          ; 6C1C D1  TYPE IN CHANNEL
               POP HL                          ; 6C1D E1  DIR ENTRY
               LD BC,&000B                     ; 6C1E 01 0B 00
               LD A,(HL)                       ; 6C21 7E
               LD (NSTR1),A                    ; 6C22 32 3A 41
               LDIR                            ; 6C25 ED B0
               INC HL                          ; 6C27 23
               INC HL                          ; 6C28 23
               LD D,(HL)                       ; 6C29 56
               INC HL                          ; 6C2A 23
               LD E,(HL)                       ; 6C2B 5E
               PUSH DE                         ; 6C2C D5  FIRST T/S
               XOR A                           ; 6C2D AF
               LD (IX+&1F),A                   ; 6C2E DD 77 1F
               LD (IX+&1E),A                   ; 6C31 DD 77 1E  FILE'S SECTOR=0 TO START WITH
               CALL COUNT_AND_READ_SECTOR      ; 6C34 CD CC 6F  INC SECTOR, LOAD AND MARK 1ST SECT
               CALL OPND8                      ; 6C37 CD 1F 6D  WITH T/S. GET STREAM OFFSET IN HL
               POP DE                          ; 6C3A D1
               PUSH HL                         ; 6C3B E5
               LD (IX+&20),D                   ; 6C3C DD 72 20  TRK
               LD (IX+&21),E                   ; 6C3F DD 73 21  SECT
               PUSH IX                         ; 6C42 DD E5
               POP HL                          ; 6C44 E1
               LD BC,FFSA+&F2                  ; 6C45 01 05 01
               ADD HL,BC                       ; 6C48 09  PT TO EXECUTION ADDR OF FFFFF
               LD BC,&0009                     ; 6C49 01 09 00  HDR LEN
               LD A,(IX+&13)                   ; 6C4C DD 7E 13  TYPE
               BIT 6,A                         ; 6C4F CB 77  PROTECT BIT
               JR Z,OPNDUP                     ; 6C51 28 04
               LD (IX+&0C),&04                 ; 6C53 DD 36 0C 04  ENSURE PROTECTED FILES ARE

;; --------------------------------------------------------------------
;; OPNDUP -- &6C57 to &6C62
;;
;; Takes:     A, HL
;; Leaves:    A, F, C
;; --------------------------------------------------------------------

; ---- OPNDUP ---- from &6C51 when bit 6 of A clear
OPNDUP:
               AND &1F                         ; 6C57 E6 1F
               CP &0A                          ; 6C59 FE 0A
               JR NZ,NOTF                      ; 6C5B 20 06  JR IF NOT OPENTYPE
               LD A,(HL)                       ; 6C5D 7E
               INC A                           ; 6C5E 3C
               JR NZ,OOTF2                     ; 6C5F 20 1E  JR IF G+DOS OPEN-TYPE FILE
               LD C,A                          ; 6C61 4F  C=0. NO HDR IN OPENTYPE FILE
               DEC A                           ; 6C62 3D  A=FF SO NO JR

;; --------------------------------------------------------------------
;; NOTF -- &6C63 to &6C76
;;
;; Takes:     A, BC, HL, IX
;; Leaves:    A, F, BC, DE, HL
;; Preserves: IX (saved and restored)
;; Ends:      JR, RET
;;
;; ? calls ROFSM, SETF4, AHLNX, D510.
;; --------------------------------------------------------------------

; ---- NOTF ---- from &6C5B when A <> &0A
NOTF:
               CP &10                          ; 6C63 FE 10
               JR C,OOTF                       ; 6C65 38 10  JR IF ZX TYPE
               DEC HL                          ; 6C67 2B  PT TO LEN DATA FOR ALL FILE TYPES
               LD D,(HL)                       ; 6C68 56
               DEC HL                          ; 6C69 2B
               LD E,(HL)                       ; 6C6A 5E
               DEC HL                          ; 6C6B 2B
               LD A,(HL)                       ; 6C6C 7E
               EX DE,HL                        ; 6C6D EB
               CALL AHLNX                      ; 6C6E CD 84 60  GET 20-BIT LEN
               ADD HL,BC                       ; 6C71 09  HDR LEN OR ZERO
               ADC A,&00                       ; 6C72 CE 00
               LD B,A                          ; 6C74 47
               JR GT19B                        ; 6C75 18 13

;; --------------------------------------------------------------------
;; OOTF -- &6C77 to &6C7E
;;
;; Takes:     A
;; Leaves:    F, B, HL
;; --------------------------------------------------------------------

; ---- OOTF ---- from &6C65 when A < &10
OOTF:
               LD HL,&C000                     ; 6C77 21 00 C0
               LD B,L                          ; 6C7A 45
               CP &05                          ; 6C7B FE 05
               JR Z,GT19B                      ; 6C7D 28 0B  JR IF 48K SNAP

;; --------------------------------------------------------------------
;; OOTF2 -- &6C7F to &6C89
;;
;; Takes:     IX
;; Leaves:    F, BC, DE, HL
;;
;; ? calls CHANNEL_LENGTH_FIELD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OOTF2 ---- from &6C5F when A is not 0
OOTF2:
               CALL CHANNEL_LENGTH_FIELD       ; 6C7F CD F3 71
               DEC HL                          ; 6C82 2B
               LD D,(HL)                       ; 6C83 56
               DEC HL                          ; 6C84 2B
               LD E,(HL)                       ; 6C85 5E
               DEC HL                          ; 6C86 2B
               DEC HL                          ; 6C87 2B
               LD B,(HL)                       ; 6C88 46
               EX DE,HL                        ; 6C89 EB  BHL=LEN IN ZX FORM

;; --------------------------------------------------------------------
;; GT19B -- &6C8A to &6CB0
;;
;; Takes:     A, BC, E, HL, IX
;; Leaves:    A, F, BC, DE, HL
;; Preserves: IX (saved and restored)
;;
;; ? calls ROFSM, SETF4, D510, CHANNEL_LENGTH_FIELD; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- GT19B ---- from &6C75, &6C7D when A = &05
GT19B:
               CALL D510                       ; 6C8A CD B1 71  GET HL=LEN MOD 510, HL'=DIV 510
               EX DE,HL                        ; 6C8D EB
               CALL CHANNEL_LENGTH_FIELD       ; 6C8E CD F3 71  NC
               LD (HL),E                       ; 6C91 73
               INC HL                          ; 6C92 23
               LD (HL),D                       ; 6C93 72  LEN MOD 510
               INC HL                          ; 6C94 23
                                               ; to the alternate register set and back again
               EXX                             ; 6C95 D9
               PUSH HL                         ; 6C96 E5  LEN DIV 510 (LEN CNT)
                                               ; to the alternate register set and back again
               EXX                             ; 6C97 D9
               POP DE                          ; 6C98 D1
               LD (HL),E                       ; 6C99 73
               INC HL                          ; 6C9A 23
               LD (HL),D                       ; 6C9B 72  LEN DIV 510
               XOR A                           ; 6C9C AF
               LD (NSTR1+1),A                  ; 6C9D 32 3B 41  NO NAME SO NO "OVERWRITE?"
               PUSH IX                         ; 6CA0 DD E5
               LD IX,DOSBUF                    ; 6CA2 DD 21 00 7C  ENSURE CLEARING HITS DCHAN,
               CALL SETF4                      ; 6CA6 CD 04 51  "NO SECTOR NEEDED"
               CALL ROFSM                      ; 6CA9 CD 05 4D  SET UP SAM, CLEAR, INC SAMCNT
               POP IX                          ; 6CAC DD E1
               LD HL,SAM+195                   ; 6CAE 21 D2 40

;; --------------------------------------------------------------------
;; CSL1 -- &6CB1 to &6CB6
;;
;; Takes:     HL
;; Leaves:    A, F, L
;; --------------------------------------------------------------------

; ---- CSL1 ---- from &6CB4 when A = 0
CSL1:
               DEC L                           ; 6CB1 2D
               LD A,(HL)                       ; 6CB2 7E
               AND A                           ; 6CB3 A7  (NC)
               JR Z,CSL1                       ; 6CB4 28 FB  LOOK FOR LAST BYTE WITH ANY BIT
               INC L                           ; 6CB6 2C

;; --------------------------------------------------------------------
;; CSL2 -- &6CB7 to &6CBE
;;
;; Takes:     A, HL
;; Leaves:    A, F, HL
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CSL2 ---- from &6CBA when L is not 0 yet
CSL2:
               DEC L                           ; 6CB7 2D
               LD (HL),&FF                     ; 6CB8 36 FF
               JR NZ,CSL2                      ; 6CBA 20 FB
               POP HL                          ; 6CBC E1  STREAM OFFSET
               AND A                           ; 6CBD A7  NC=OK (NOT NEEDED...)
               RET                             ; 6CBE C9

;; --------------------------------------------------------------------
;; OPND45 -- &6CBF to &6CD1
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL, IX
;;
;; ? calls MOVE_TABLE_IF_PAGED; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPND45 ---- from &6BE9
OPND45:
               CP MIN                          ; 6CBF FE BF
               JP Z,REP26                      ; 6CC1 CA 62 5E  "FILE NOT FOUND" IF "IN" WITH
               PUSH AF                         ; 6CC4 F5
               CALL MOVE_TABLE_IF_PAGED        ; 6CC5 CD 30 6D
               POP AF                          ; 6CC8 F1
               POP IX                          ; 6CC9 DD E1
               CP MRND                         ; 6CCB FE A5
               LD A,&02                        ; 6CCD 3E 02
               JR Z,OPND45_1                   ; 6CCF 28 01  JR IF RND (BITS 1-0 = 10)
               DEC A                           ; 6CD1 3D  BITS 1-0 SHOW OUT (01). OUT IS

;; --------------------------------------------------------------------
;; OPND45_1 -- &6CD2 to &6CD5
;;
;; Takes:     A, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? calls OPND7; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPND45_1 ---- from &6CCF when A = MRND
OPND45_1:
               CALL OPND7                      ; 6CD2 CD EF 6C  SETS FTRK/FSCT, CNT=1
               RET C                           ; 6CD5 D8

;; --------------------------------------------------------------------
;; STORE_TRANSFER_COUNT -- &6CD6 to &6CEE
;;
;; Takes:     HL, IX
;; Leaves:    A, F, BC
;; Preserves: HL (saved and restored)
;; Ends:      RET
;;
;; ? calls CHANNEL_LENGTH_FIELD.
;;
;; Shown for this routine in disasm/:
;;
;;     Write the two count bytes at (IX+&0D) and (IX+&0E) out through the
;;     pointer &71F3 returns.
;; --------------------------------------------------------------------

; ---- STORE_TRANSFER_COUNT ---- from &6F6B
STORE_TRANSFER_COUNT:
               PUSH HL                         ; 6CD6 E5
               CALL CHANNEL_LENGTH_FIELD       ; 6CD7 CD F3 71
               LD A,(IX+&0D)                   ; 6CDA DD 7E 0D
               LD (HL),A                       ; 6CDD 77
               INC HL                          ; 6CDE 23
               LD A,(IX+&0E)                   ; 6CDF DD 7E 0E
               LD (HL),A                       ; 6CE2 77
               INC HL                          ; 6CE3 23
               LD A,(IX+&1F)                   ; 6CE4 DD 7E 1F
               LD (HL),A                       ; 6CE7 77
               INC HL                          ; 6CE8 23
               LD A,(IX+&1E)                   ; 6CE9 DD 7E 1E
               LD (HL),A                       ; 6CEC 77
               POP HL                          ; 6CED E1
               RET                             ; 6CEE C9  C=ABORTED

;; --------------------------------------------------------------------
;; OPND7 -- &6CEF to &6D06
;;
;; Takes:     A, DE, HL, IX
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through JRECLAIM; calls ROFSM, DDEL, RAMST, CMR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- OPND7 ---- from &6CD2
OPND7:
               CALL RAMST                      ; 6CEF CD 5D 70  SET MFLG ETC
               CALL DDEL                       ; 6CF2 CD 5F 65  DELAY IF NOT RAMDISC IN CASE 1ST
               CALL ROFSM                      ; 6CF5 CD 05 4D  CREATE SAM FOR DRIVE, INIT AREA AT
               JR NC,OPND75                    ; 6CF8 30 0D  JR IF NOT ABORT DUE "OVERWRITE"
               LD BC,&0313                     ; 6CFA 01 13 03
               PUSH IX                         ; 6CFD DD E5
               POP HL                          ; 6CFF E1
                                               ; call the ROM at JRECLAIM with ROM1 paged in, and page back on the way
                                               ; out
               CALL CMR                        ; 6D00 CD B2 7B
