;; --------------------------------------------------------------------
;; CLSRM -- &6DE5 to &6E0A
;;
;; This routine moves the return address about with EX (SP),HL, so the
;; register tracking below cannot be trusted: read it as a list of what
;; is touched, not of what is destroyed.
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls STRMD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     CLEAR STREAM AND CLOSE CHANNEL
;;      Streams 0 to 3 are put back to the channels the ROM gives them by default rather than being left unattached.
;; --------------------------------------------------------------------

; ---- CLSRM ---- from &6D80, &6DBD, &6DD1
CLSRM:
               CALL STRMD                      ; 6DE5 CD 4C 70
               LD A,C                          ; 6DE8 79
               OR B                            ; 6DE9 B0
               RET Z                           ; 6DEA C8  RET IF CLOSED ALREADY
               LD (SVTRS),BC                   ; 6DEB ED 43 24 41
               PUSH HL                         ; 6DEF E5  PTR TO STRMS
               LD HL,(CHANS+&4000)             ; 6DF0 2A 4F 9C
               DEC HL                          ; 6DF3 2B
               ADD HL,BC                       ; 6DF4 09
                                               ; HMPR is 0, so setting bit 7 and clearing bit 6 turns an address in
                                               ; &4000-&7FFF into the same byte of the ROM's system page at &8000-&BFFF
               SET 7,H                         ; 6DF5 CB FC
               RES 6,H                         ; 6DF7 CB B4  PT TO CHANNEL SWITCHED IN SECT C
               EX (SP),HL                      ; 6DF9 E3  HL=PTR TO STRMS
               LD BC,&0000                     ; 6DFA 01 00 00
               LD DE,TXHED_1                   ; 6DFD 11 E2 63
               EX DE,HL                        ; 6E00 EB
               ADD HL,DE                       ; 6E01 19  ADD -9C1EH, STRMS PTR
               JR C,CLOSE1                     ; 6E02 38 07  JR IF STREAM >3
               LD BC,MCHRD                     ; 6E04 01 F9 6E
               ADD HL,BC                       ; 6E07 09
               LD C,(HL)                       ; 6E08 4E
               INC HL                          ; 6E09 23
               LD B,(HL)                       ; 6E0A 46

;; --------------------------------------------------------------------
;; CLOSE1 -- &6E0B to &6E1F
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, DE, HL, IX
