               SET 7,H                         ; 6E0C CB FC
               RES 6,H                         ; 6E0E CB B4  ADDR IN STREAMS
               LD (HL),C                       ; 6E10 71
               INC HL                          ; 6E11 23
               LD (HL),B                       ; 6E12 70
               POP IX                          ; 6E13 DD E1  CHANNEL START
               LD A,B                          ; 6E15 78
               OR C                            ; 6E16 B1
               RET NZ                          ; 6E17 C0  RET IF STREAM 0-3 JUST CLOSED
               LD A,(IX+&04)                   ; 6E18 DD 7E 04
               AND &5F                         ; 6E1B E6 5F
