;; --------------------------------------------------------------------
;; MCHIN -- &6F07 to &6F2C
;;
;; Takes:     A, IX
;; Leaves:    A, F, BC, HL
;; Preserves: IX (saved and restored)
;; Ends:      JR, RET
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A; calls CPPTR.
;; --------------------------------------------------------------------

; ---- MCHIN ---- from &6EF9
MCHIN:
               IN A,(HMPR)                     ; 6F07 DB FB
               PUSH AF                         ; 6F09 F5
               XOR A                           ; 6F0A AF
               OUT (HMPR),A                    ; 6F0B D3 FB
               PUSH IX                         ; 6F0D DD E5  KEEP FPC HAPPY DURING INKEY$
               LD HL,TVFLAG+&4000              ; 6F0F 21 3C 9C
               RES 3,(HL)                      ; 6F12 CB 9E  "NO NEED TO COPY LINE TO LS"
               LD IX,(CURCHL+&4000)            ; 6F14 DD 2A 51 9C  - NEEDED?
               LD BC,HEADER                    ; 6F18 01 00 40
               ADD IX,BC                       ; 6F1B DD 09
               BIT 0,(IX+&0C)                  ; 6F1D DD CB 0C 46
               JP NZ,REP18                     ; 6F21 C2 74 51  "READING A WRITE FILE"
               CALL CPPTR                      ; 6F24 CD DC 6F
               JR NZ,MCHN1                     ; 6F27 20 04  JR IF NOT EOF
               ADD A,&0D                       ; 6F29 C6 0D  NC+NZ=EOF (WHEN PTR=LEN)
               JR MCHN2                        ; 6F2B 18 04

;; --------------------------------------------------------------------
;; MCHN1 -- &6F2D to &6F30
