;; Takes:     BC, DE, HL, IX
;; Leaves:    A, F
;;
;; ? calls LBYT; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- MCHN1 ---- from &6F27
MCHN1:
               CALL LBYT                       ; 6F2D CD F6 6F
               SCF                             ; 6F30 37  "GOT KEY"

;; --------------------------------------------------------------------
;; MCHN2 -- &6F31 to &6F34
;;
;; Takes:     A
;; Leaves:    BC, IX
;; --------------------------------------------------------------------

; ---- MCHN2 ---- from &6F2B
MCHN2:
               PUSH AF                         ; 6F31 F5
               POP BC                          ; 6F32 C1  AF IN BC FOR TRANSMISSION OUT
               POP IX                          ; 6F33 DD E1

;; --------------------------------------------------------------------
;; MCHN2_1 -- &6F35 to &6F3A
;;
;; Takes:     A
;; Leaves:    A, F
;; Ends:      RET
;;
;; ? drives OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- MCHN2_1 ---- from &6F58 when A = &C6, &6F73
MCHN2_1:
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 6F35 08
               POP AF                          ; 6F36 F1
               OUT (HMPR),A                    ; 6F37 D3 FB
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 6F39 08
               RET                             ; 6F3A C9

;; --------------------------------------------------------------------
;; MCHWR -- &6F3B to &6F74
;;
;; Takes:     A, E
;; Leaves:    A, F, BC, DE, HL, IX
;; Ends:      JR, RET
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A; calls STORE_TRANSFER_COUNT, WRITE_LAST_PAGE, CPPTR.
;;
;; Shown for this routine in disasm/:
;;
;;     MasterBASIC changed this routine: only 62 of the 96
;;     instructions stock MasterDOS 2.3 has in MCHWR survive
;;     here, so that version's description of it has been
;;     left out rather than carried across.  Compare
;;     ref/masterdos/annotated-src/masterdos23.asm.
;; --------------------------------------------------------------------

; ---- MCHWR ---- from &694F when A = &4B, &6D9D
MCHWR:
               LD D,A                          ; 6F3B 57
               IN A,(HMPR)                     ; 6F3C DB FB
               PUSH AF                         ; 6F3E F5
               XOR A                           ; 6F3F AF
               OUT (HMPR),A                    ; 6F40 D3 FB
               LD IX,(CURCHL+&4000)            ; 6F42 DD 2A 51 9C
               LD BC,HEADER                    ; 6F46 01 00 40
               ADD IX,BC                       ; 6F49 DD 09
               LD A,(IX+&0C)                   ; 6F4B DD 7E 0C
               AND &03                         ; 6F4E E6 03
               JP Z,REP19                      ; 6F50 CA 77 51  "WRITING A READ FILE" IF "IN"
               LD A,(CURCMD+&4000)             ; 6F53 3A 74 9B
               CP &C6                          ; 6F56 FE C6  VALUE FOR "INPUT"
               JR Z,MCHN2_1                    ; 6F58 28 DB  NO WRITE IF SO
               CALL CPPTR                      ; 6F5A CD DC 6F  Z IF PTR=LEN
               PUSH AF                         ; 6F5D F5
               LD A,D                          ; 6F5E 7A
               CALL WRITE_LAST_PAGE            ; 6F5F CD 8D 6F  SAVE BYTE
               SET 3,(IX+&0C)                  ; 6F62 DD CB 0C DE  "SECTOR WRITTEN TO"
               SET 5,(IX+&0C)                  ; 6F66 DD CB 0C EE  "FILE WRITTEN TO"
               POP AF                          ; 6F6A F1
               CALL Z,STORE_TRANSFER_COUNT     ; 6F6B CC D6 6C  COPY PTR TO LEN IF WRITING TO
               LD A,(&5C4B+FS)                 ; 6F6E 3A 4B 9C  RESTORE BORDER COLOUR - QUICK
               OUT (BORDER),A                  ; 6F71 D3 FE
               JR MCHN2_1                      ; 6F73 18 C0

