;; --------------------------------------------------------------------
;; WRITE_LAST_PAGE -- &6F8D to &6FB5
;;
;; Takes:     A, BC, DE, HL, IX
;; Leaves:    A, F, BC, DE
;; Preserves: HL (saved and restored)
;;
;; ? calls WRITE_SECTOR, IS_LAST_PAGE, FNFS, SWAP_TRACK_AND_SECTOR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     The tail of a write: IS_LAST_PAGE decides whether this is the final
;;     page, and everything is pushed around the decision so the caller's
;;     registers survive either path.
;; --------------------------------------------------------------------

; ---- WRITE_LAST_PAGE ---- from &6F5F
WRITE_LAST_PAGE:
               PUSH BC                         ; 6F8D C5
               PUSH HL                         ; 6F8E E5
               PUSH AF                         ; 6F8F F5
               CALL IS_LAST_PAGE               ; 6F90 CD 47 48
               JR NZ,WRITE_LAST_PAGE_2         ; 6F93 20 25  JR IF BUFFER NOT FULL
               PUSH DE                         ; 6F95 D5
               PUSH HL                         ; 6F96 E5
               CALL CPPTR                      ; 6F97 CD DC 6F  CP PTR WITH FILE LEN
               POP HL                          ; 6F9A E1
               JR NZ,WRITE_LAST_PAGE_1         ; 6F9B 20 19  JR IF WE ARE NOT AT FILE END
               CALL FNFS                       ; 6F9D CD 83 4A
               LD (HL),D                       ; 6FA0 72
               INC HL                          ; 6FA1 23
               LD (HL),E                       ; 6FA2 73
               EX DE,HL                        ; 6FA3 EB
               CALL SWAP_TRACK_AND_SECTOR      ; 6FA4 CD CD 4F  SELECT DRIVE
               CALL WRITE_SECTOR               ; 6FA7 CD 80 45  PREV
               PUSH HL                         ; 6FAA E5
               LD D,H                          ; 6FAB 54
               LD E,L                          ; 6FAC 5D
               INC DE                          ; 6FAD 13
               LD BC,&01FF                     ; 6FAE 01 FF 01
               XOR A                           ; 6FB1 AF  Z
               LD (HL),A                       ; 6FB2 77
               LDIR                            ; 6FB3 ED B0  BLANK NEW SECTOR
               POP HL                          ; 6FB5 E1

