;; --------------------------------------------------------------------
;; CPPTR -- &6FDC to &6FF5
;;
;; Takes:     IX
;; Leaves:    A, F, BC, HL
;; Ends:      RET
;;
;; ? calls CHANNEL_LENGTH_FIELD.
;;
;; Shown for this routine in disasm/:
;;
;;     CP PTR WITH LEN. Z IF MATCH (AND HL=LEN MSB OF 4)
;;      Both are kept as an offset within a sector plus a sector count, so end of file is four byte comparisons.
;; --------------------------------------------------------------------

; ---- CPPTR ---- from &65B5, &6F24, &6F5A, &6F97
CPPTR:
               CALL CHANNEL_LENGTH_FIELD       ; 6FDC CD F3 71
               LD A,(IX+&0D)                   ; 6FDF DD 7E 0D
               CP (HL)                         ; 6FE2 BE  HL PTS TO LEN LOW (LIKE RPT)
               RET NZ                          ; 6FE3 C0
               INC HL                          ; 6FE4 23
               LD A,(IX+&0E)                   ; 6FE5 DD 7E 0E
               CP (HL)                         ; 6FE8 BE
               RET NZ                          ; 6FE9 C0
               INC HL                          ; 6FEA 23
               LD A,(IX+&1F)                   ; 6FEB DD 7E 1F
               CP (HL)                         ; 6FEE BE
               RET NZ                          ; 6FEF C0
               INC HL                          ; 6FF0 23
               LD A,(IX+&1E)                   ; 6FF1 DD 7E 1E
               SUB (HL)                        ; 6FF4 96
               RET                             ; 6FF5 C9  A=0 IF EOF, Z FLAG

