;; --------------------------------------------------------------------
;; D510 -- &71B1 to &71BA
;;
;; Takes:     A, BC, E, HL
;; Leaves:    A, F, BC, DE, HL
;;
;; Shown for this routine in disasm/:
;;
;;     ENTRY: BHL=24-BIT NUMBER
;;     EXIT: HL=NUMBER MOD 510, HL'=NUMBER DIV 510
;;      Division by repeated subtraction, which is cheap here because a file's sector count is small.
;; --------------------------------------------------------------------

; ---- D510 ---- from &6C8A, &70A2
D510:
               XOR A                           ; 71B1 AF
               LD D,A                          ; 71B2 57  D MUST BE ZERO LATER
                                               ; to the alternate register set and back again
               EXX                             ; 71B3 D9
               LD L,A                          ; 71B4 6F
               LD H,A                          ; 71B5 67  SECTOR COUNT INITED
                                               ; to the alternate register set and back again
               EXX                             ; 71B6 D9
               LD A,B                          ; 71B7 78
               LD BC,&01FE                     ; 71B8 01 FE 01  DBC=510

;; --------------------------------------------------------------------
;; D510_LOOP -- &71BB to &71D3
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
