; ---- D510_LOOP ---- from &71C1
D510_LOOP:
                                               ; to the alternate register set and back again
               EXX                             ; 71BB D9
               INC HL                          ; 71BC 23
                                               ; to the alternate register set and back again
               EXX                             ; 71BD D9
               SBC HL,BC                       ; 71BE ED 42
               SBC A,D                         ; 71C0 9A
               JR NC,D510_LOOP                 ; 71C1 30 F8
               ADD HL,BC                       ; 71C3 09  HL=DISP IN SECTOR
               LD A,H                          ; 71C4 7C
               OR L                            ; 71C5 B5
               RET NZ                          ; 71C6 C0
                                               ; to the alternate register set and back again
               EXX                             ; 71C7 D9
               LD A,L                          ; 71C8 7D
               DEC A                           ; 71C9 3D
               OR H                            ; 71CA B4
                                               ; to the alternate register set and back again
               EXX                             ; 71CB D9
               RET Z                           ; 71CC C8
                                               ; to the alternate register set and back again
               EXX                             ; 71CD D9
               DEC HL                          ; 71CE 2B
                                               ; to the alternate register set and back again
               EXX                             ; 71CF D9
               LD HL,&01FE                     ; 71D0 21 FE 01
               RET                             ; 71D3 C9  HL=SECTOR

