; ---- SKIPF ---- from &72A3
SKIPF:
               LD (HL),A                       ; 72AD 77  SET LENGTH
               INC DE                          ; 72AE 13  SKIP LEADING ROOT OR ARROW SYMBOL.
               DJNZ SDFCL                      ; 72AF 10 EC  DEC LEN
               CALL DERR                       ; 72B1 CD AD 51
               DEFB &12                        ; 72B4 .

;; --------------------------------------------------------------------
;; STDNR -- &72B5 to &72C2
;;
;; Takes:     BC, DE
;; Leaves:    A, F, B, DE, HL
