               LD BC,DIRT                      ; 7373 01 FA 00  DISP TO TAG VALUE FOR FILES IN
               ADD HL,BC                       ; 7376 09  THIS DIR
               LD A,(HL)                       ; 7377 7E
               LD (CDIRT),A                    ; 7378 32 31 42
               POP BC                          ; 737B C1
               POP HL                          ; 737C E1
               JR DTREL                        ; 737D 18 EB

