               PUSH DE                         ; 7519 D5
               PUSH HL                         ; 751A E5
               EX DE,HL                        ; 751B EB
               LD HL,HEADER                    ; 751C 21 00 40
               LD B,&02                        ; 751F 06 02

;; --------------------------------------------------------------------
