;; --------------------------------------------------------------------
;; RDRSCT -- &7533 to &7540
;;
;; Takes:     DE, IX
;; Leaves:    A, F, BC, HL
;; Preserves: DE (saved and restored)
;; Ends:      JP, JR
;;
;; ? calls CLEAR_TRANSFER_COUNT, GTBUF, READ_ADDRESS_CLEAR, SDCHK2.
;;
;; Shown for this routine in disasm/:
;;
;;     Read a sector from a RAM disc -- the author's own name, from the part
;;     of the source ref/masterdos/docs/ram-discs.md calls RAMD.  Every disk
;;     operation starts with TIRD, and for drives 3 to 7 it comes here
;;     instead of touching a controller at all.
;;
;;     The shipped code has one thing the reference source does not.  There
;;     RDRSCT is CALL GTBUF then LD BC,&0200 straight into RDRS2; here
;;     SDCHK2 goes between them, and its own comments say what it decides --
;;     "RET IF HL IN DRAM" and "CY IF HL WILL CROSS PAGE BOUNDARY".  A
;;     destination that would run off the end of a page takes the long way
;;     round through DRAM; one that will not is read into the caller's
;;     buffer directly.
;; --------------------------------------------------------------------

; ---- RDRSCT ---- from &45BA, &74EA, &7516
RDRSCT:
               CALL GTBUF                      ; 7533 CD A0 4F
               CALL SDCHK2                     ; 7536 CD B9 77
               JR C,RDRSCT_1                   ; 7539 38 06
               PUSH DE                         ; 753B D5
               CALL READ_ADDRESS_CLEAR         ; 753C CD 8F 77
               JR RDW4                         ; 753F 18 A2

;; --------------------------------------------------------------------
;; RDRSCT_1 -- &7541 to &7543
;;
;; Takes:     nothing in registers
;; Leaves:    BC
;; --------------------------------------------------------------------

; ---- RDRSCT_1 ---- from &7539
RDRSCT_1:
               LD BC,&0200                     ; 7541 01 00 02

;; --------------------------------------------------------------------
;; RDRS2 -- &7544 to &7563
;;
;; Takes:     BC, DE, HL, IX
;; Leaves:    A, F, BC, HL
;; Preserves: DE (saved and restored)
;; Ends:      JP
;;
;; ? drives OUT (HMPR),A; calls CLEAR_TRANSFER_COUNT, RDADR.
;;
;; Shown for this routine in disasm/:
;;
;;     The copy itself, and it is an LDIR: RDADR works out where the sector
;;     lives in the RAM disc's pages, and &0200 bytes move from there to
;;     DRAM.  A RAM disc read is a memory copy with the same interface as a
;;     floppy read, which is the whole point of the design.
;; --------------------------------------------------------------------

; ---- RDRS2 ---- from &7763
RDRS2:
               PUSH DE                         ; 7544 D5  T/S
               PUSH HL                         ; 7545 E5  MAIN MEM PTR
               PUSH BC                         ; 7546 C5
               CALL RDADR                      ; 7547 CD 64 75  GET SRC ADDR IN HL
               LD BC,&0200                     ; 754A 01 00 02
               LD DE,DRAM                      ; 754D 11 13 7D
               LDIR                            ; 7550 ED B0  COPY RAMDISC TO DRAM
               OUT (HMPR),A                    ; 7552 D3 FB  ORIG URPORT
               POP BC                          ; 7554 C1
               POP HL                          ; 7555 E1
               LD A,&7D                        ; 7556 3E 7D
               CP H                            ; 7558 BC
               JR Z,RDW4                       ; 7559 28 88  RET IF DEST=DRAM - DONE IT
               EX DE,HL                        ; 755B EB  DE=BUF
               LD HL,DRAM                      ; 755C 21 13 7D
               LDIR                            ; 755F ED B0
               JP RDW4                         ; 7561 C3 E3 74

;; --------------------------------------------------------------------
;; RDADR -- &7564 to &757D
;;
;; Takes:     D
;; Leaves:    A, F, D, HL
;;
;; ? drives OUT (HMPR),A; calls SELFP; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      RDADR -- turn a track and sector into a page and an address, and map that page
;;
;;      A RAM disc may have fewer than four directory tracks, in which case its data tracks still begin at track 4 as
;;      far
;;      as the rest of the DOS is concerned, and the track number is shifted down here to close the gap. That is the
;;      "fiddle" the comments refer to, and RDAT suppresses it for raw sector access, where the caller means the track
;;      it
;;      said.
;;
;;      Exit:   HL = the address, the page mapped, A = the previous paging value
;;      Errors: REP22 if the drive does not exist, REP4 if the track is out of range
;;
;;     RAM DISC ADDRESS - GET HL=ADDR, PAGE SELECTED, FROM D/E (T/S)
;;     GET A=CUR. URPORT. BC, DE USED
;; --------------------------------------------------------------------

; ---- RDADR ---- from &74D7, &7547, &7791, &779B
RDADR:
               LD A,(RDAT)                     ; 7564 3A 0D 42
               AND A                           ; 7567 A7
               JR Z,RDAD2                      ; 7568 28 14
               CALL SELFP                      ; 756A CD A7 75
               LD HL,(MB_CALLDOS_2)            ; 756D 2A FF 82
               OUT (HMPR),A                    ; 7570 D3 FB
               LD A,L                          ; 7572 7D
               ADD A,&03                       ; 7573 C6 03
               CP D                            ; 7575 BA  CP DTKS-1,TRK
               JR NC,RDAD2                     ; 7576 30 06  JR IF TRK IN DIRECTORY - NO FIDDLE
               SUB &03                         ; 7578 D6 03
               JR NC,RDAD2                     ; 757A 30 02  LEAVE TRACK ALONE IF 4 DIR TKS OR
               ADD A,D                         ; 757C 82
               LD D,A                          ; 757D 57  E.G. TRACK 4 ACCESS BECOMES TRACK 1

;; --------------------------------------------------------------------
;; RDAD2 -- &757E to &7587
;;
;; Takes:     D
;; Leaves:    A, F, C, HL
;;
;; ? calls RTSTD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     SO IF DTKS=1, DISK=40 TRK, TRK 0=0
;;     TRKS 4-42 BECOME 1-39
;; --------------------------------------------------------------------

; ---- RDAD2 ---- from &7568 when A = 0, &7576 when A >= D, &757A when A >= &03
RDAD2:
               CALL RTSTD                      ; 757E CD 2F 74  GET A=TRACKS/DRIVE
               AND A                           ; 7581 A7
               JP Z,REP22                      ; 7582 CA 7D 51  "NO SUCH DRIVE" IF TKS=0
               LD C,A                          ; 7585 4F
               LD A,D                          ; 7586 7A
               CP C                            ; 7587 B9

;; --------------------------------------------------------------------
;; REP4H -- &7588 to &7598
;;
;; Takes:     A, D
;; Leaves:    A, F, D
;; --------------------------------------------------------------------

; ---- REP4H ---- from &758F when A >= &50
REP4H:
               JP NC,REP4                      ; 7588 D2 65 51  TRK/SCT ERROR IF TRACK >=(LIMIT)
               AND &7F                         ; 758B E6 7F
               CP &50                          ; 758D FE 50
               JR NC,REP4H                     ; 758F 30 F7  ERROR IF E.G. TRK 81
               BIT 7,D                         ; 7591 CB 7A
               JR Z,RDAD3                      ; 7593 28 04  JR IF "SIDE 1"
               LD A,D                          ; 7595 7A
               SUB &30                         ; 7596 D6 30  128->80
               LD D,A                          ; 7598 57

;; --------------------------------------------------------------------
;; RDAD3 -- &7599 to &75A6
;;
;; Takes:     DE
;; Leaves:    A, F, BC
;; Preserves: HL (saved and restored)
;; Ends:      JR
;;
;; ? drives OUT (HMPR),A; calls CPFTS, PTRD2.
;; --------------------------------------------------------------------

; ---- RDAD3 ---- from &7593 when bit 7 of D clear
RDAD3:
               CALL CPFTS                      ; 7599 CD BF 75  GET PAGEFORM OF DISC ADDR
               PUSH HL                         ; 759C E5
               CALL PTRD2                      ; 759D CD 22 77  PT TO ENTRY "A" IN LIST
               LD L,(HL)                       ; 75A0 6E  GET PAGE VALUE
               OUT (HMPR),A                    ; 75A1 D3 FB
               LD A,L                          ; 75A3 7D
               POP HL                          ; 75A4 E1
               JR SELRDP                       ; 75A5 18 04

;; --------------------------------------------------------------------
;; SELFP -- &75A7 to &75AA
;;
;; Takes:     nothing in registers
;; Leaves:    A, HL
;;
;; ? calls GFPA; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- SELFP ---- from &756A, &7723, &7737
SELFP:
               CALL GFPA                       ; 75A7 CD 37 74
               LD A,(HL)                       ; 75AA 7E  A=FIRST PAGE

;; --------------------------------------------------------------------
;; SELRDP -- &75AB to &75B5
;;
;; Takes:     A, DE
;; Leaves:    F, D
;;
;; ? drives OUT (XMPRL),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     SELECT RAM DISC PAGE. ENTRY: A=PAGE. 00-1F=INTERNAL RAM, 20-FFL
;;      20-FFH=EXTERNAL. EXIT: A=ORIG URPORT VALUE
;;      A page number of &20 or more is MegaRAM: the number selects a bank through MRPRT and the paging register gets
;;      the
;;      external-memory bit instead of a page.
;; --------------------------------------------------------------------

; ---- SELRDP ---- from &75A5, &76BC
SELRDP:
               DI                              ; 75AB F3
               PUSH DE                         ; 75AC D5  SAVE THROUGHOUT
               LD D,A                          ; 75AD 57  40-7F=MEGA RAM 1,
               CP &20                          ; 75AE FE 20  ??? SUB &20 ???
               JR C,SRDP2                      ; 75B0 38 04  JR IF MAIN RAM
               OUT (XMPRL),A                   ; 75B2 D3 80  SELECT MEGA RAM
               LD D,&80                        ; 75B4 16 80  XMEM BIT HIGH

;; --------------------------------------------------------------------
;; SRDP2 -- &75B6 to &75BE
;;
;; Takes:     D
;; Leaves:    DE
;; Preserves: A, F (saved and restored)
;; Ends:      RET
;;
;; ? drives IN A,(HMPR), OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- SRDP2 ---- from &75B0 when A < &20
SRDP2:
               IN A,(HMPR)                     ; 75B6 DB FB
               PUSH AF                         ; 75B8 F5
               LD A,D                          ; 75B9 7A
               OUT (HMPR),A                    ; 75BA D3 FB
               POP AF                          ; 75BC F1  ORIG PAGE
               POP DE                          ; 75BD D1  ORIG
               RET                             ; 75BE C9

;; --------------------------------------------------------------------
;; CPFTS -- &75BF to &75D5
;;
;; Takes:     DE
;; Leaves:    A, F, BC, HL
;;
;; Shown for this routine in disasm/:
;;
;;      CPFTS -- track and sector to a page and an offset
;;
;;      The sector number is ten times the track plus the sector, less one. Adding a thirty-first of that, plus one,
;;      makes
;;      the result skip every thirty-second 512-byte block -- which is the block at the start of each page, where the
;;      mover code and the page list live.
;;
;;     CALCULATE PAGE FORM FROM T/S IN DE
;; --------------------------------------------------------------------

; ---- CPFTS ---- from &7599, &768E
CPFTS:
               LD L,D                          ; 75BF 6A
               LD H,&00                        ; 75C0 26 00
               LD B,H                          ; 75C2 44
               LD C,L                          ; 75C3 4D
               ADD HL,HL                       ; 75C4 29
               ADD HL,HL                       ; 75C5 29
               ADD HL,BC                       ; 75C6 09
               ADD HL,HL                       ; 75C7 29  TRACK*10
               LD C,E                          ; 75C8 4B
               DEC C                           ; 75C9 0D
               LD A,C                          ; 75CA 79
               CP &0A                          ; 75CB FE 0A
               JP NC,REP27                     ; 75CD D2 89 51  "END OF FILE" IF SECTOR NOT 1-10
               ADD HL,BC                       ; 75D0 09  SECTOR NUMBER 0 TO DISC LIMIT
               PUSH HL                         ; 75D1 E5
               LD C,&1F                        ; 75D2 0E 1F
               XOR A                           ; 75D4 AF  NC
               DEC A                           ; 75D5 3D  A=0FFH

;; --------------------------------------------------------------------
;; DIV31L -- &75D6 to &75E0
;;
;; Takes:     A, BC, HL
;; Leaves:    A, F, C, HL
;; --------------------------------------------------------------------

; ---- DIV31L ---- from &75D9
DIV31L:
               INC A                           ; 75D6 3C
               SBC HL,BC                       ; 75D7 ED 42
               JP NC,DIV31L                    ; 75D9 D2 D6 75
               POP HL                          ; 75DC E1  SECT NO 0 TO LIMIT-1
               LD C,A                          ; 75DD 4F
               ADD HL,BC                       ; 75DE 09  SECT=SECT+INT(SECT/31) TO AVOID
               INC HL                          ; 75DF 23  AVOID SECT 0,32,64,96 ETC
               ADD HL,HL                       ; 75E0 29  HL=SECT NO.*2

;; --------------------------------------------------------------------
;; PTHRD_2 -- &75E1 to &75E3
;;
;; Takes:     B, HL
;; Leaves:    A, HL
;; --------------------------------------------------------------------

; ---- PTHRD_2 ---- from &40E0
PTHRD_2:
               LD A,H                          ; 75E1 7C
               LD H,L                          ; 75E2 65
               LD L,B                          ; 75E3 68  AHL=20-BIT DISPLACEMENT (512*SECT)

;; --------------------------------------------------------------------
;; PAGEFORM -- &75E4 to &75EF
;;
;; Takes:     A, H
;; Leaves:    A, F, H
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;     NOW GET A=PG DISP, HL=OFFSET
;;
;;     TRANSFORM 20-BIT NUMBER IN AHL TO PAGE, ADDR (8000-BFFF)
;; --------------------------------------------------------------------

; ---- PAGEFORM ---- from &4F18, &4F2D, &5A1E, &603D, &6539, &66B9, &6EBF
PAGEFORM:
               RL H                            ; 75E4 CB 14
               RLA                             ; 75E6 17
               RL H                            ; 75E7 CB 14
               RLA                             ; 75E9 17  NC. PAGE NOW OK
               RR H                            ; 75EA CB 1C
               SCF                             ; 75EC 37
               RR H                            ; 75ED CB 1C  ADDR NOW OK IN 8000-BFFF FORM
               RET                             ; 75EF C9

;; --------------------------------------------------------------------
;; RDSB -- &75F0 to &75F7
;;
;; Takes:     A, DE, IX
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JR
;;
;; ? calls WSAD, CCNT, FFNS, SWAP_TRACK_AND_SECTOR.
;;
;; Shown for this routine in disasm/:
;;
;;      RDSB -- the RAM disc form of a block save
;;
;;      The disk version allocates all its sectors in advance so that each can carry the address of its successor. Here
;;      that is unnecessary -- there is no rotational delay to plan around -- so sectors are allocated one at a time,
;;      the
;;      data staged through DRAM, and the link written into the last two bytes before each write.
;;
;;     RAM DISC SAVE BLOCK
;; --------------------------------------------------------------------

; ---- RDSB ---- from &4994
RDSB:
               CALL WSAD                       ; 75F0 CD 86 45  SAVE FIRST BLOCK
               LD BC,&0000                     ; 75F3 01 00 00  SECT COUNT=0
               JR RDSB2                        ; 75F6 18 30

;; --------------------------------------------------------------------
;; RDSBL -- &75F8 to &7627
;;
;; Takes:     DE, IX
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls WSAD, CCNT, FFNS, SWAP_TRACK_AND_SECTOR; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- RDSBL ---- from &762C
RDSBL:
               CALL CCNT                       ; 75F8 CD 0C 49  CHECK BYTES REMAINING, SUB 511
               EX DE,HL                        ; 75FB EB
               LD HL,(SVHL)                    ; 75FC 2A 05 7C  SRC
               JR C,RDSB3                      ; 75FF 38 2D  JR IF 510 OR LESS BYTES TO GO
               INC DE                          ; 7601 13  CORRECT FOR SUB 511 ->SUB 510 NOW
               LD (SVDE),DE                    ; 7602 ED 53 02 7C
               LD DE,DRAM                      ; 7606 11 13 7D  TEMP STORE
               LD BC,&01FE                     ; 7609 01 FE 01
               LDIR                            ; 760C ED B0  COPY DATA TO TEMP BUFFER IN
               CALL CHKHL                      ; 760E CD 85 77
               LD (SVHL),HL                    ; 7611 22 05 7C
               CALL FFNS                       ; 7614 CD 78 4A  FAST FIND NEXT FREE SECT IN SAM
               LD L,D                          ; 7617 6A
               LD H,E                          ; 7618 63
               LD (DRAM+510),HL                ; 7619 22 11 7F
               EX DE,HL                        ; 761C EB
               CALL SWAP_TRACK_AND_SECTOR      ; 761D CD CD 4F  GET T/S IN D/E
               CALL WSAD                       ; 7620 CD 86 45
               LD BC,(SVCNT)                   ; 7623 ED 4B 28 41
               INC BC                          ; 7627 03  INC SECTOR COUNT

;; --------------------------------------------------------------------
;; RDSB2 -- &7628 to &762D
;;
;; Takes:     BC, DE, IX
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JR
;;
;; ? calls WSAD, CCNT, FFNS, SWAP_TRACK_AND_SECTOR.
;; --------------------------------------------------------------------

; ---- RDSB2 ---- from &75F6
RDSB2:
               LD (SVCNT),BC                   ; 7628 ED 43 28 41
               JR RDSBL                        ; 762C 18 CA

;; --------------------------------------------------------------------
;; RDSB3 -- &762E to &7642
;;
;; Takes:     BC, HL, IX
;; Leaves:    A, F, BC, DE, HL
;; Ends:      JP, JR
;; --------------------------------------------------------------------

; ---- RDSB3 ---- from &75FF
RDSB3:
               LD BC,(SVDE)                    ; 762E ED 4B 02 7C  * POP DE          ;PREV TRK
               LD (IX+&0E),B                   ; 7632 DD 70 0E
               LD (IX+&0D),C                   ; 7635 DD 71 0D
               LD DE,DRAM                      ; 7638 11 13 7D
               PUSH BC                         ; 763B C5
               LDIR                            ; 763C ED B0  LAST PART-BUFFER COPIED
               EX DE,HL                        ; 763E EB  BUFFER DEST IN HL
               POP BC                          ; 763F C1  PTR
               JP SVBS1                        ; 7640 C3 67 4A

;; --------------------------------------------------------------------
;; FORMRD -- &7643 to &7665
;;
;; Takes:     A
;; Leaves:    A, F, BC, DE, HL
;;
;; ? drives OUT (HMPR),A; calls RTSTD, PTRD; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      FORMRD -- create, resize or delete a RAM disc
;;
;;      Any pages the disc already owns are given back first -- to the ROM's allocation table if they are internal, to
;;      MRTAB if they are MegaRAM -- and then as many as the requested size needs are claimed. A size of zero stops
;;      there,
;;      which is how FORMAT "D3:",0 deletes a RAM disc.
;;
;;      As each page is claimed it is prepared: the block mover is written at &8002, 128 LDI instructions and a loop are
;;      built at &8020, and every position that could hold a directory entry is set to start 00/00 so the directory scan
;;      reads it as never used. Only then is the page list written into the first page and the disc marked usable.
;;
;;      Errors: REP22 for a drive above RDLIM, "out of memory" if there are not enough free pages
;;
;;     FORMAT RAM DISC. A=DSTR1
;; --------------------------------------------------------------------

; ---- FORMRD ---- from &6153
FORMRD:
               CP RDLIM                        ; 7643 FE 08
               JP NC,REP22                     ; 7645 D2 7D 51  "NO SUCH DRIVE"
               DI                              ; 7648 F3
               LD (DRIVE),A                    ; 7649 32 0B 7C
               XOR A                           ; 764C AF
               OUT (HMPR),A                    ; 764D D3 FB  SYS PAGE AT 8000H
               CALL RTSTD                      ; 764F CD 2F 74  GET TKS/DRIVE
               AND A                           ; 7652 A7
               JR Z,FRMRD2                     ; 7653 28 24  JR IF NEW RAMDISC
               CALL PTRD                       ; 7655 CD 21 77  PT TO TABLE START - 50 BYTES OF
               LD DE,DRAM                      ; 7658 11 13 7D
               PUSH DE                         ; 765B D5
               LD BC,&0034                     ; 765C 01 34 00
               LDIR                            ; 765F ED B0  COPY TO BUFFER
               POP HL                          ; 7661 E1
               OUT (HMPR),A                    ; 7662 D3 FB  ORIG
               LD D,&91                        ; 7664 16 91

;; --------------------------------------------------------------------
;; FRMRDL -- &7666 to &7672
;;
;; Takes:     D, HL
;; Leaves:    A, F, E, HL
;; Ends:      JR
;; --------------------------------------------------------------------

; ---- FRMRDL ---- from &7671, &7677
FRMRDL:
               LD A,(HL)                       ; 7666 7E
               INC HL                          ; 7667 23
               LD E,A                          ; 7668 5F
               AND A                           ; 7669 A7  TERMINATOR IS 0
               JR Z,FRMRD2                     ; 766A 28 0D  EXIT IF ALL USED PAGES DE-ALLOCTED
               AND &E0                         ; 766C E6 E0
               JR NZ,FRMRD1                    ; 766E 20 03  JR IF MEGA RAM PAGE
               LD (DE),A                       ; 7670 12  FREE PAGE IN ALLOCT
               JR FRMRDL                       ; 7671 18 F3

;; --------------------------------------------------------------------
;; FRMRD1 -- &7673 to &7678
;;
;; Takes:     BC, DE, HL
;; Leaves:    A, F, BC, E, HL
;; Ends:      JR
;;
;; ? calls RMRBIT.
;; --------------------------------------------------------------------

; ---- FRMRD1 ---- from &766E when a bit of &E0 is set
FRMRD1:
               LD A,E                          ; 7673 7B
               CALL RMRBIT                     ; 7674 CD 06 78  FREE BIT IN MEGA RAM MAP
               JR FRMRDL                       ; 7677 18 ED

;; --------------------------------------------------------------------
;; FRMRD2 -- &7679 to &767E
;;
;; Takes:     A
;; Leaves:    A, F, B, HL
;; --------------------------------------------------------------------

; ---- FRMRD2 ---- from &7653 when A = 0, &766A when A = 0
FRMRD2:
               LD HL,DRAM                      ; 7679 21 13 7D  PT TO TABLE START - 50 BYTES OF
               LD B,&34                        ; 767C 06 34  PAGES USED
               XOR A                           ; 767E AF

;; --------------------------------------------------------------------
;; RDCLL -- &767F to &76A5
;;
;; Takes:     A, B, HL
;; Leaves:    A, F, BC, DE, HL
;;
;; ? calls CPFTS, CNTFP; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- RDCLL ---- from &7681 when B is not 0 yet
RDCLL:
               LD (HL),A                       ; 767F 77
               INC HL                          ; 7680 23
               DJNZ RDCLL                      ; 7681 10 FC  CLEAR TABLE
               LD A,(TEMPW1)                   ; 7683 3A 12 42  TKS/DISC
               AND A                           ; 7686 A7
               JP Z,FTKPD                      ; 7687 CA 0C 77  JUST ERASE ANY EXISTING RAM DISC
               LD D,A                          ; 768A 57
               DEC D                           ; 768B 15
               LD E,&0A                        ; 768C 1E 0A  LAST SECTOR ON DISC
               CALL CPFTS                      ; 768E CD BF 75  GET PAGE FORM OF T/S ADDR
               INC A                           ; 7691 3C
               LD C,A                          ; 7692 4F  PAGES NEEDED
               CALL CNTFP                      ; 7693 CD 29 78  COUNT FREE PAGES IN A AND B
               CP C                            ; 7696 B9
               JP C,OOMERR                     ; 7697 DA 1D 77
               LD A,C                          ; 769A 79
               PUSH AF                         ; 769B F5  PAGES NEEDED
               LD B,&00                        ; 769C 06 00
               LD HL,DRAM                      ; 769E 21 13 7D
               ADD HL,BC                       ; 76A1 09  LAST REQUIRED POSN IN TABLE,+1
               POP BC                          ; 76A2 C1  B=PAGES NEEDED
               LD DE,ALLOCT+FS+32              ; 76A3 11 20 91

;; --------------------------------------------------------------------
;; FRMRDEL -- &76A6 to &76B2
;;
;; Takes:     A, DE
;; Leaves:    A, F, E
;;
;; ? drives OUT (HMPR),A; calls SFMRP; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;      Claim each page, preferring MegaRAM so that internal memory is left for programs. The pages are recorded in the
;;      list from the end backwards, so the first page of the disc ends up first in the table.
;; --------------------------------------------------------------------

; ---- FRMRDEL ---- from &76B1 when A <> 0, &76F2 when B is not 0 yet
FRMRDEL:
               CALL SFMRP                      ; 76A6 CD E7 77  SEARCH FOR FREE MR PAGE & RESERVE IT
               JR Z,FRMRD6                     ; 76A9 28 0F  JR IF PAGE FREE (A=PAGE)
               DEC E                           ; 76AB 1D  INTERNAL RAM PAGE NO./ALLOCT PTR
               XOR A                           ; 76AC AF
               OUT (HMPR),A                    ; 76AD D3 FB  SYS PAGE IN AT 8000H
               LD A,(DE)                       ; 76AF 1A
               AND A                           ; 76B0 A7
               JR NZ,FRMRDEL                   ; 76B1 20 F3  JR IF PAGE NOT FREE

;; --------------------------------------------------------------------
;; FRMRD5 -- &76B3 to &76B9
;;
;; Takes:     DE
;; Leaves:    A, F
;; --------------------------------------------------------------------

FRMRD5:
               LD A,(DRIVE)                    ; 76B3 3A 0B 7C
               OR &D0                          ; 76B6 F6 D0
               LD (DE),A                       ; 76B8 12  RESERVE IN ALLOCT
               LD A,E                          ; 76B9 7B

;; --------------------------------------------------------------------
;; FRMRD6 -- &76BA to &76CE
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    F, BC, DE, HL
;;
;; ? calls SELRDP; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FRMRD6 ---- from &76A9
FRMRD6:
               DEC HL                          ; 76BA 2B  NEXT TABLE POSN
               LD (HL),A                       ; 76BB 77  PAGE NUMBER TO RAM DISC'S LIST
               CALL SELRDP                     ; 76BC CD AB 75
                                               ; to the alternate register set and back again
               EXX                             ; 76BF D9
               LD HL,RDCODE                    ; 76C0 21 C9 77
               LD DE,&8002                     ; 76C3 11 02 80
               LD BC,RDCE-RDCODE+1             ; 76C6 01 1E 00
               LDIR                            ; 76C9 ED B0  CREATE MOVER CODE IN UNUSED
               LD HL,&8020                     ; 76CB 21 20 80
               LD B,H                          ; 76CE 44  B=128

;; --------------------------------------------------------------------
;; FTCCL -- &76CF to &76E9
;;
;; Takes:     B, HL
;; Leaves:    B, HL
;; --------------------------------------------------------------------

; ---- FTCCL ---- from &76D5 when B is not 0 yet
FTCCL:
               LD (HL),&ED                     ; 76CF 36 ED
               INC HL                          ; 76D1 23
               LD (HL),&A0                     ; 76D2 36 A0
               INC HL                          ; 76D4 23
               DJNZ FTCCL                      ; 76D5 10 F8  CREATE 128 LDIs
               LD (HL),&3D                     ; 76D7 36 3D  DEC A
               INC HL                          ; 76D9 23
               LD (HL),&C2                     ; 76DA 36 C2  JP NZ
               INC HL                          ; 76DC 23
               LD (HL),&20                     ; 76DD 36 20
               INC HL                          ; 76DF 23
               LD (HL),&80                     ; 76E0 36 80  8020H
               INC HL                          ; 76E2 23
               LD (HL),&C9                     ; 76E3 36 C9  RET
               LD B,&3E                        ; 76E5 06 3E  MAX NUMBER OF POSSIBLE DIR
               LD HL,&8200                     ; 76E7 21 00 82  FIRST POSSIBLE DIR ENTRY

;; --------------------------------------------------------------------
;; FZDL -- &76EA to &770B
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    BC, DE, HL
;; Preserves: A, F (saved and restored)
;;
;; ? calls FESET, GFPA; falls into whatever follows rather than returning.
;; --------------------------------------------------------------------

; ---- FZDL ---- from &76EF when B is not 0 yet
FZDL:
               LD (HL),C                       ; 76EA 71
               INC L                           ; 76EB 2C
               LD (HL),C                       ; 76EC 71  ENSURE IT STARTS 00/00
               DEC L                           ; 76ED 2D  SO "NEVER USED"
