               LD HL,MB_FN_SVAL_S_1            ; 773A 21 60 81
               LD DE,PTHRD+2                   ; 773D 11 D4 40
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 7740 08
               JR NC,MRDPN2                    ; 7741 30 01
