; ---- RDLB3 ---- from &776E
RDLB3:
               LD HL,(SVHL)                    ; 7773 2A 05 7C
               LD DE,&01FE                     ; 7776 11 FE 01
               ADD HL,DE                       ; 7779 19
               CALL CHKHL                      ; 777A CD 85 77
               LD (SVHL),HL                    ; 777D 22 05 7C
               LD D,B                          ; 7780 50
