               JP CLEAR_TRANSFER_COUNT         ; 7782 C3 8E 4F

;; --------------------------------------------------------------------
;; CHKHL -- &7785 to &778E
;;
;; Takes:     A, H
;; Leaves:    F
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- CHKHL ---- from &6691, &760E, &777A
CHKHL:
                                               ; the rotating window check: if HL has walked out of section C into
                                               ; section D, the page goes up by one and RES 6,H brings HL back &4000
                                               ; lower onto the same byte. The Technical Manual gives this idiom as the
                                               ; standard way to walk a structure longer than 16K
               BIT 6,H                         ; 7785 CB 74
               RET Z                           ; 7787 C8
               CALL INCURPAGE                  ; 7788 CD F2 3F
               LD (PORT1),A                    ; 778B 32 2E 41
               RET                             ; 778E C9

;; --------------------------------------------------------------------
;; READ_ADDRESS_CLEAR -- &778F to &7798
;;
;; Takes:     A, DE, HL
;; Leaves:    BC, HL
;; Preserves: A, F, DE (saved and restored)
;; Ends:      JR, RET
;;
;; ? drives IN A,(LMPR), OUT (HMPR),A; calls RDADR.
;; --------------------------------------------------------------------

; ---- READ_ADDRESS_CLEAR ---- from &753C
READ_ADDRESS_CLEAR:
               PUSH DE                         ; 778F D5  T/S
               PUSH HL                         ; 7790 E5  MAIN MEMORY PTR - DEST
               CALL RDADR                      ; 7791 CD 64 75  PT HL TO SRC IN RAMD, PAGE IN
               POP DE                          ; 7794 D1  DEST
               PUSH AF                         ; 7795 F5  ORIG PAGE
               AND A                           ; 7796 A7
               JR READ_ADDRESS_CLEAR_1         ; 7797 18 08

;; --------------------------------------------------------------------
;; READ_ADDRESS_SET -- &7799 to &77A0
;;
;; Takes:     DE, HL
;; Leaves:    A, F, DE, HL
;;
;; ? calls RDADR; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     Read the sector's address mark through RDADR, and differ in one
;;     instruction: AND A leaves carry clear where SCF sets it, and both
;;     join at &77A1.  The flag is the caller's answer, carried out in the
;;     alternate accumulator.
;; --------------------------------------------------------------------

; ---- READ_ADDRESS_SET ---- from &7770
READ_ADDRESS_SET:
               PUSH DE                         ; 7799 D5
               PUSH HL                         ; 779A E5
               CALL RDADR                      ; 779B CD 64 75
               POP DE                          ; 779E D1
               PUSH AF                         ; 779F F5
               SCF                             ; 77A0 37

;; --------------------------------------------------------------------
;; READ_ADDRESS_CLEAR_1 -- &77A1 to &77B8
;;
;; Takes:     A, HL
;; Leaves:    A, F, BC, DE, HL
;; Ends:      RET
;;
;; ? drives IN A,(LMPR), OUT (HMPR),A.
;; --------------------------------------------------------------------

; ---- READ_ADDRESS_CLEAR_1 ---- from &7797
READ_ADDRESS_CLEAR_1:
               LD C,A                          ; 77A1 4F  MAIN MEM PAGE
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 77A2 08
               DEC C                           ; 77A3 0D  TO BE PAGED IN AT 4000H
               IN A,(LMPR)                     ; 77A4 DB FA
               LD B,A                          ; 77A6 47
               XOR C                           ; 77A7 A9
               AND &E0                         ; 77A8 E6 E0
               XOR C                           ; 77AA A9  A=VALUE FOR PORT 250 TO PAGE
               CALL MB_SOFV                    ; 77AB CD 02 80  IN DEST AT 4000H
               LD B,(HL)                       ; 77AE 46
               INC HL                          ; 77AF 23
               LD C,(HL)                       ; 77B0 4E  NEXT T/S
               POP AF                          ; 77B1 F1
               OUT (HMPR),A                    ; 77B2 D3 FB
               POP DE                          ; 77B4 D1  CURRENT T/S
               RET                             ; 77B5 C9

SDCHK:
               DEFB &CD,&A0,&4F                ; 77B6 M O  PT HL TO BUFF (EITHER DRAM

;; --------------------------------------------------------------------
;; SDCHK2 -- &77B9 to &77C8
;;
;; Takes:     HL
;; Leaves:    A, F, BC, H
;; Preserves: L (saved and restored)
;; Ends:      RET
;; --------------------------------------------------------------------

; ---- SDCHK2 ---- from &7536, &775B
SDCHK2:
               LD A,H                          ; 77B9 7C
               CP &80                          ; 77BA FE 80
               RET C                           ; 77BC D8  RET IF HL IN DRAM
               PUSH HL                         ; 77BD E5
               LD BC,L41FF                     ; 77BE 01 FF 41
               ADD HL,BC                       ; 77C1 09
               POP HL                          ; 77C2 E1
               RET C                           ; 77C3 D8  CY IF HL WILL CROSS PAGE BOUNDARY
               RES 7,H                         ; 77C4 CB BC  - USE BUFF
               SET 6,H                         ; 77C6 CB F4
               RET                             ; 77C8 C9  ADDR IN 4000-7FFF AREA NOW

;; --------------------------------------------------------------------
;; RDCODE -- &77C9 to &77DB
;;
;; Takes:     A, BC
;; Leaves:    A, F
;;
;; ? drives OUT (LMPR),A; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     AT 8002H
;;      The mover, as copied into every RAM disc page. It saves the stack pointer in the page, switches to a stack
;;      there,
;;      maps the destination at &4000, and calls the unrolled LDI block at &8020 -- four passes of 128 for a whole
;;      sector, or a shorter run for the 510-byte case.
;; --------------------------------------------------------------------

; ---- RDCODE ---- from &76C0
RDCODE:
               LD (MB_PUTSWA),SP               ; 77C9 ED 73 00 80
                                               ; the stack is being reset, so this path does not return
               LD SP,MB_CALL_STKSTR_2          ; 77CD 31 00 82
               OUT (LMPR),A                    ; 77D0 D3 FA  PAGE IN DEST IN SECTION B
               PUSH BC                         ; 77D2 C5  ORIG PORT 250 VALUE
                                               ; to the alternate register set and back again
               EX AF,AF'                       ; 77D3 08
               LD A,&04                        ; 77D4 3E 04  4 MOVES OF 128 BYTES
               JR C,RDC1                       ; 77D6 38 04  JR IF 510 BYTES WANTED
               CALL &8020                      ; 77D8 CD 20 80  MOVER - DO 128*4=512
               AND A                           ; 77DB A7  NC

