;; --------------------------------------------------------------------
;; INPST -- &7A0E to &7A42
;;
;; Takes:     A, B, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;;
;; ? reaches the ROM through CURCHL; calls ISEP, NRRDD, SIBKS, NNB; falls into whatever follows rather than returning.
;;
;; Shown for this routine in disasm/:
;;
;;     MasterBASIC changed this routine: only 17 of the 29
;;     instructions stock MasterDOS 2.3 has in INPST survive
;;     here, so that version's description of it has been
;;     left out rather than carried across.  Compare
;;     ref/masterdos/annotated-src/masterdos23.asm.
;; --------------------------------------------------------------------

INPST:
               CALL SIBKS                      ; 7A0E CD 09 7A  INSIST "("
               LD C,&23                        ; 7A11 0E 23
               CALL ISEP                       ; 7A13 CD 38 50
               CALL NNB                        ; 7A16 CD 96 7A  GET CHARS IN BC, STREAM IN DE.
               LD HL,&0010                     ; 7A19 21 10 00
               AND A                           ; 7A1C A7
               SBC HL,DE                       ; 7A1D ED 52
               JP C,INVST                      ; 7A1F DA 44 70  LIMIT STREAM TO 0-16
               PUSH BC                         ; 7A22 C5
                                               ; read the ROM variable CURCHL -- the word below is its address, and the
                                               ; call returns past it
               CALL NRRDD                      ; 7A23 CD 53 50
               DEFW CURCHL                     ; 7A26 51 5C
               POP HL                          ; 7A28 E1
               PUSH BC                         ; 7A29 C5
               IN A,(HMPR)                     ; 7A2A DB FB
               PUSH AF                         ; 7A2C F5
               PUSH HL                         ; 7A2D E5
               LD A,E                          ; 7A2E 7B
                                               ; call the ROM at STREAM with ROM1 paged in, and page back on the way out
               CALL CMR                        ; 7A2F CD B2 7B
               DEFW STREAM                     ; 7A32 12 01
               POP BC                          ; 7A34 C1
               LD A,B                          ; 7A35 78
               OR C                            ; 7A36 B1
               JR Z,INPST_1                    ; 7A37 28 0A
               PUSH BC                         ; 7A39 C5
               DEC BC                          ; 7A3A 0B  Z->FFFF
               LD A,B                          ; 7A3B 78
               CP &40                          ; 7A3C FE 40
               JP NC,AHLNX_1                   ; 7A3E D2 91 60
               JR INPST_2                      ; 7A41 18 03

