;; --------------------------------------------------------------------
;; RETURN_INTO_BC -- &7BAC to &7BB1
;;
;; Takes:     nothing in registers
;; Leaves:    HL
;; Ends:      JP
;;
;; Shown for this routine in disasm/:
;;
;;     Write BC over the word at the stack pointer kept in &7FFC -- the
;;     ROM's stack as it stood when the DOS was entered -- so that the
;;     pending return goes to BC instead.  The same trick MasterBASIC plays
;;     with STORE_BC_AT_XVAR76, from the other side.
;; --------------------------------------------------------------------

; ---- RETURN_INTO_BC ---- from &4413, &64A4, &78B2
RETURN_INTO_BC:
               LD HL,(&7FFC)                   ; 7BAC 2A FC 7F
               JP WRTBC                        ; 7BAF C3 AB 50

;; --------------------------------------------------------------------
;; CMR -- &7BB2 to &7BD7
;;
;; Takes:     A, BC, DE, HL
;; Leaves:    A, F, BC, DE, HL, IY
;; Ends:      JP
;;
;; ? drives IN A,(HMPR), IN A,(LMPR).
;;
;; Shown for this routine in disasm/:
;;
;;     Call the main ROM.
;;
;;         CALL CMR
;;         DEFW <ROM address>
;;
;;     The mirror of the routine above: it pages the ROM back in rather than
;;     the other half, saves the current HMPR into the code that restores it,
;;     and returns through a stub that undoes both.
;; --------------------------------------------------------------------

; ---- CMR ---- from &423E, &4DED, &503C, &5042, &5767, &5953, &5AE6, &5B5A ...
CMR:
                                               ; to the alternate register set and back again
               EXX                             ; 7BB2 D9
               POP HL                          ; 7BB3 E1
               LD E,(HL)                       ; 7BB4 5E
               INC HL                          ; 7BB5 23
               LD D,(HL)                       ; 7BB6 56
               INC HL                          ; 7BB7 23
               PUSH HL                         ; 7BB8 E5
               LD HL,(&7FFC)                   ; 7BB9 2A FC 7F  MAIN ROM SP ON ENTRY TO DOS
               PUSH HL                         ; 7BBC E5
               LD HL,CMR_DONE                  ; 7BBD 21 F7 7B
               PUSH HL                         ; 7BC0 E5
               LD C,A                          ; 7BC1 4F
               IN A,(HMPR)                     ; 7BC2 DB FB
                                               ; self-modifying: patches the operand of the LD at &7BF2
               LD (L7BF2+1),A                  ; 7BC4 32 F3 7B  patches the operand of the LD at &7BF2
               IN A,(LMPR)                     ; 7BC7 DB FA
               LD B,A                          ; 7BC9 47
               INC A                           ; 7BCA 3C
               AND &1F                         ; 7BCB E6 1F
               OUT (HMPR),A                    ; 7BCD D3 FB  DOS AT 8000H ALSO
               LD IY,&0000                     ; 7BCF FD 21 00 00
               ADD IY,SP                       ; 7BD3 FD 39
               JP &BBD8                        ; 7BD5 C3 D8 BB

;; --------------------------------------------------------------------
;; L7BD8 -- &7BD8 to &7BF6
;;
;; Takes:     BC, DE, IY
;; Leaves:    A, F, HL
;; Ends:      JP
;;
;; ? drives OUT (LMPR),A; calls PTM.
;; --------------------------------------------------------------------

               LD A,&1F                        ; 7BD8 3E 1F
               LD HL,(&BFFC)                   ; 7BDA 2A FC BF
               DI                              ; 7BDD F3
               OUT (LMPR),A                    ; 7BDE D3 FA  SYS PAGE AT 4000H
                                               ; the stack is being reset, so this path does not return
               LD SP,HL                        ; 7BE0 F9
               EI                              ; 7BE1 FB  STACK
               LD HL,(&5C59)                   ; 7BE2 2A 59 5C
                                               ; self-modifying: patches the operand of the LD at &5C58
               LD (&5C59),IY                   ; 7BE5 FD 22 59 5C
               PUSH IY                         ; 7BE9 FD E5
               PUSH BC                         ; 7BEB C5
               PUSH HL                         ; 7BEC E5  ORIG SP
               LD HL,PNDN2_2                   ; 7BED 21 A4 58  RET ADDR TO PAGING SR
               PUSH HL                         ; 7BF0 E5  AFTER DEFKEYS
               PUSH DE                         ; 7BF1 D5  ROUTINE ADDR TO CALL

L7BF2:
               LD A,&00                        ; 7BF2 3E 00  the operand is written here at run time, from &7BC4
               JP XTRA+CMR3-PFV                ; 7BF4 C3 9F 58  PAGE IN ORIG URPORT,

;; --------------------------------------------------------------------
;; CMR_DONE -- &7BF7 to &7D5F
;;
;; Takes:     BC, DE
;; Leaves:    BC, DE, HL
;; Ends:      RET
;;
;; Shown for this routine in disasm/:
;;
;;      INIP3 -- boot-time initialisation
;; --------------------------------------------------------------------

; ---- CMR_DONE ---- from &7BBD
CMR_DONE:
               POP HL                          ; 7BF7 E1
               LD (&7FFC),HL                   ; 7BF8 22 FC 7F

;; --------------------------------------------------------------------
;;  The blocks copied into the system page at boot
;; --------------------------------------------------------------------

                                               ; to the alternate register set and back again
               EXX                             ; 7BFB D9
               RET                             ; 7BFC C9
               DEFB &00,&00,&00                ; 7BFD ...  zero fill

;; --------------------------------------------------------------------
;; The DOS's variables and buffers -- and, from &7C00, the landing ground
;; for the block the boot sector copies out of the MasterBASIC page.
;;
;; Routines all over the DOS reach into the lower part of this with
;; LD HL,&7Cxx and LD (&7Cxx),A, and nothing in the DOS page calls or
;; jumps into any of it, so as far as this listing goes it is not code.
;;
;; That is only half the story.  The LDIR at the end of BOOT copies 943
;; bytes from &75E1 in the MasterBASIC page to &BC00 -- this address, as
;; the boot sector has the pages mapped -- and jumps to it.  MasterBASIC
;; then goes on calling into the copy: &7D79 from twenty-seven sites, and
;; four more addresses once each.  Those are marked MBCOPY_xxxx, named for
;; the MasterBASIC address they were copied from, which is where the code
;; that actually runs there can be read.
;;
;; So the bytes below are whatever was in the DOS's buffers when the image
;; was saved.  None of them is ever executed.
;; --------------------------------------------------------------------

; ---- DOSBUF ---- from &4BA7, &4C3E, &4D8D, &4F84, &53DD, &67D0, &6CA2
DOSBUF:
               DEFB &C9,&02                    ; 7C00 I.

; ---- SVDE ---- from &486E, &489B, &4905, &490C, &4920, &4927, &4950, &4983 ...
SVDE:
               DEFB &06,&21                    ; 7C02 .!  (2) saved DE, usually a track and sector

; ---- V7C04 ---- from &4B37, &4B90, &4C5D
V7C04:
               DEFB &13                        ; 7C04 .

; ---- SVHL ---- from &487D, &48CD, &48F3, &4902, &4954, &4969, &497A, &4A1E ...
SVHL:
               DEFB &72                        ; 7C05 r  (2) saved HL, usually the transfer address

; ---- V7C06 ---- from &472A, &475E, &4767
V7C06:
               DEFB &F3                        ; 7C06 s

; ---- SVIX ---- from &4E1E, &4E46
SVIX:
               DEFB &ED,&73,&3A,&BD            ; 7C07 ms:=  (2) saved IX

; ---- DRIVE ---- from &4825, &482C, &4D1C, &615A, &6186, &6781, &743F, &744D ...
DRIVE:
